// Generated by scripts/gen-l10n.mjs (gdetail n5, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["id"]=Object.assign(window.GRAMMAR_DETAIL_L10N["id"]||{},{"n5-51":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, siapa pun yang memberi ke siapa pun, kita bilang \"memberi\". Bahasa Jepang memperhatikan <b>arah perpindahan barangnya</b>: kalau barang <b>keluar</b> dari pihak kita, pakai <span class='gd-jp'>あげます</span>; kalau barang <b>datang</b> dari orang lain ke pihak kita, pakai <span class='gd-jp'>くれます</span>; dan kalau kamu bicara dari sisi penerima, \"aku <b>menerima</b>\", pakai <span class='gd-jp'>もらいます</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>あげます</span>Aku (atau orang di pihakku) memberi orang lain, barangnya bergerak keluar. Kalau orang lain memberi orang lain pun, pakai ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に誕生日プレゼントをあげました。</span>（Aku memberi temanku hadiah ulang tahun）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは山田さんに花をあげました。</span>（Pak Tanaka memberi bunga kepada Bu Yamada）</div><div class='gd-sec'><span class='gd-tag'>くれます</span>Orang lain memberi <b>aku</b>, atau memberi <b>keluargaku</b>, jadi barangnya datang ke pihak kita. \"Kepadaku\" biasanya tidak perlu disebut, orang Jepang langsung paham.</div><div class='gd-ex-line'>・<span class='gd-jp'>母が時計をくれました。</span>（Ibu memberiku sebuah jam tangan）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が妹にお菓子をくれました。</span>（Temanku memberi adik perempuanku camilan）</div><div class='gd-sec'><span class='gd-tag'>もらいます</span>Dari sisi si penerima, \"aku dapat, aku menerima\".</div><div class='gd-ex-line'>・<span class='gd-jp'>先生から手紙をもらいました。</span>（Aku menerima surat dari guru）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ketiganya punya unsur \"siapa, kepada siapa, barang apa\". Bedanya ada pada <b>siapa yang jadi tokoh utama</b>:<br><b>あげます</b>: pemberi<span class='gd-jp'>は</span>　penerima<span class='gd-jp'>に</span>　barang<span class='gd-jp'>を</span>　<span class='gd-jp'>あげます</span><br><b>くれます</b>: pemberi<span class='gd-jp'>が</span>　（aku<span class='gd-jp'>に</span>）　barang<span class='gd-jp'>を</span>　<span class='gd-jp'>くれます</span><br><b>もらいます</b>: aku<span class='gd-jp'>は</span>　pemberi<span class='gd-jp'>に</span>／<span class='gd-jp'>から</span>　barang<span class='gd-jp'>を</span>　<span class='gd-jp'>もらいます</span><br>Bentuk lampau sama saja, ganti ます jadi ました: <span class='gd-pair'><span class='gd-jp'>くれます</span> → <span class='gd-jp'>くれました</span></span></div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Satu kejadian yang sama: <b>temanku memberiku sebuah buku</b>.<br>・<span class='gd-jp'>友達が本をくれました。</span>（Temanku memberiku sebuah buku）Tokoh utamanya teman, bukunya datang ke pihakku.<br>・<span class='gd-jp'>友達に本をもらいました。</span>（Aku menerima sebuah buku dari temanku）Tokoh utamanya aku, aku yang menerima.<br>Kedua kalimat ini artinya sama, dua-duanya boleh dipakai.<br>・<span class='gd-jp'>友達が私に本をあげました。</span>　Kalimat ini <b>salah</b>, あげます tidak bisa dipakai untuk \"memberi kepadaku\".<br><br>Sebaliknya, kalau <b>aku memberi temanku sebuah buku</b>, hanya bisa bilang:<br>・<span class='gd-jp'>友達に本をあげました。</span>（Aku memberi temanku sebuah buku）</div><div class='gd-warn'>Trik cepat: tanya dulu pada dirimu, \"Apakah barangnya datang ke pihakku?\" Kalau ya, pakai くれます atau もらいます; kalau barangnya keluar, pakai あげます.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kalau mengikuti intuisi bahasa Indonesia, \"Ibu memberiku\" sering ditulis jadi <span class='gd-jp'>母があげました</span>, itu salah. Memberi kepadaku atau keluargaku selalu pakai <b>くれます</b>.<br>・Tokoh utama くれます tidak pernah \"aku\": <span class='gd-jp'>私が友達にくれました</span> itu salah, harusnya <span class='gd-jp'>友達にあげました</span>.<br>・<span class='gd-jp'>に</span> sebelum もらいます artinya \"<b>dari</b>\", bukan \"kepada\": <span class='gd-jp'>友達にもらいました</span> artinya \"menerima dari teman\", bukan \"memberikan kepada teman\". Kalau takut tertukar, pakai saja <span class='gd-jp'>から</span>, artinya sama.<br>・Keluarga dianggap \"orang di pihakku\", jadi kalau temanmu memberi sesuatu kepada adikmu, tetap pakai くれます.<br>・Kalau memberi kepada guru atau atasan, langsung bilang あげます terdengar agak merendahkan. Nanti kamu akan belajar ungkapan yang lebih sopan.<br>・Kadang kamu akan dengar <span class='gd-jp'>花に水をやります</span>（menyirami bunga）. やります dipakai untuk memberi kepada hewan atau tanaman; kalau dipakai untuk orang terdengar agak kasar, jadi untuk pemula pakai あげます saja.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Di N4, ketiga kata kerja ini akan dipasang setelah bentuk て untuk berarti \"melakukan sesuatu untuk orang lain\": <span class='gd-jp'>友達が駅まで送ってくれました。</span>（Temanku mengantarku sampai stasiun）Cara menilai arahnya persis sama seperti di sini, jadi kalau sekarang sudah paham, nanti jadi mudah.</div>","n5-38":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「だけ」dan「しか」sama-sama berarti \"hanya\". <b>だけ</b> seperti \"hanya ～\" dalam bahasa Indonesia, sekadar menyebut batasan; <b>しか〜ません</b> lebih seperti \"cuma ～ saja\" atau \"baru ～ saja\", dengan nuansa <b>\"sedikit sekali, tidak cukup\"</b>. Ciri terbesarnya: <b>しか harus diikuti bentuk negatif</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>だけ</b>: langsung ditaruh setelah kata benda atau jumlah.<br><span class='gd-pair'><span class='gd-jp'>水</span> → <span class='gd-jp'>水だけ</span></span><span class='gd-pair'><span class='gd-jp'>一つ</span> → <span class='gd-jp'>一つだけ</span></span><br>Kata kerja juga bisa, pakai bentuk kamus (bentuk yang kamu temukan di kamus): <span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るだけ</span></span>（hanya melihat）</div><div class='gd-sec'><b>しか</b>: ditaruh setelah kata benda atau jumlah, dan kata kerja di akhir kalimat harus diubah jadi negatif.<br><span class='gd-pair'><span class='gd-jp'>水を飲みます</span> → <span class='gd-jp'>水しか飲みません</span></span>（hanya minum air）</div><div class='gd-sec'><b>「を」「が」yang tadinya ada harus dibuang</b>: <span class='gd-jp'>水を</span> menjadi <span class='gd-jp'>水だけ</span>、<span class='gd-jp'>水しか</span>. (Setelah だけ, を boleh dipertahankan, tapi biasanya dibuang saja.)<br>Partikel seperti「に」「で」「へ」<b>tetap dipertahankan</b> dan ditaruh sebelum しか:</div><div class='gd-ex-line'>・<span class='gd-jp'>友達にしか言いませんでした。</span>（Aku hanya bilang ke temanku）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>だけ：sekadar menyebut batasan</span>Tidak ada perasaan banyak atau sedikit, hanya menyatakan \"cuma ini\".</div><div class='gd-ex-line'>・<span class='gd-jp'>サラダだけ注文します。</span>（Aku hanya pesan salad）</div><div class='gd-ex-line'>・<span class='gd-jp'>見ているだけです。</span>（Aku cuma lihat-lihat）</div><div class='gd-sec'>Kalimat kedua sangat berguna saat jalan-jalan belanja di Jepang. Kalau pegawai toko menyapa, kamu tinggal jawab begitu.</div><div class='gd-sec'><span class='gd-tag'>しか：terasa sedikit, tidak cukup</span>Di hati terasa \"terlalu sedikit\" atau \"lebih sedikit dari dugaan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>10分しか残っていません。</span>（Tinggal 10 menit lagi）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は3時間しか寝ませんでした。</span>（Kemarin aku cuma tidur tiga jam）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>しか harus diikuti negatif</b>: bilang <span class='gd-jp'>千円しかありません</span>, tidak bisa bilang 「千円しかあります」.<br>・<b>Kebalikan dari intuisi bahasa Indonesia</b>: melihat「ません」jangan langsung mengira artinya \"tidak ada\". <span class='gd-jp'>千円しかありません</span> artinya \"hanya punya seribu yen\", bukan \"tidak punya seribu yen\"; <span class='gd-jp'>肉しか食べません</span> artinya \"hanya makan daging\", bukan \"tidak makan daging\". Bayangkan saja artinya \"selain seribu yen itu, tidak ada apa-apa\".<br>・<b>Sebelum しか tidak boleh ada を dan が</b>: tidak bisa bilang 「水をしか」, harus <span class='gd-jp'>水しか</span>.<br>・<b>だけ tidak berarti \"cukup\"</b>: だけ hanyalah \"hanya\" yang netral, tidak mengandung makna \"cukup\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal yang sama, だけ itu melaporkan, sedangkan しか itu menyatakan keluhan \"sedikit banget\".</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人だけ来ました。</span>（Hanya satu orang yang datang ke pesta: sekadar melaporkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人しか来ませんでした。</span>（Cuma satu orang yang datang ke pesta: sedikit banget）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しだけ分かります。</span>（Aku mengerti sedikit bahasa Jepang: cara sopan bilang bisa sedikit）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少ししか分かりません。</span>（Aku cuma mengerti sedikit sekali bahasa Jepang: menekankan kemampuan yang terbatas, minta lawan bicara tidak bicara terlalu sulit）</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia kamu ingin bilang \"cuma ～ saja\" atau \"baru ～ saja\" karena terasa sedikit, pakai 「しか＋ません」; kalau sekadar menyebut batasan, pakai 「だけ」. Ingat, しか selalu berpasangan dengan ません.</div>","n5-56":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たり〜たりします」mirip dengan <b>「baca buku, nonton film, dan sebagainya」</b>. Dari sekian banyak kegiatan, kamu ambil dua atau tiga saja sebagai contoh. Artinya, \"ini cuma contoh, aku juga melakukan hal lain\". Pola ini punya satu pemakaian lagi: <b>「sebentar begini, sebentar begitu」</b>, seperti \"kadang panas kadang dingin\" atau \"hujannya turun-berhenti, turun-berhenti\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memberi contoh</span>Kalau ada yang bertanya kamu biasanya ngapain, kamu tidak perlu menyebut semuanya. Cukup sebut beberapa kegiatan yang mewakili.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日は、本を読んだり映画を見たりします。</span>（Di hari libur, aku baca buku, nonton film, dan semacamnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除したり、買い物に行ったりします。</span>（Akhir pekan aku beres-beres, pergi belanja, dan semacamnya）</div><div class='gd-sec'><span class='gd-tag'>Sebentar begini, sebentar begitu</span>Dua tindakan atau keadaan yang berlawanan muncul bergantian.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、暑かったり寒かったりします。</span>（Akhir-akhir ini cuacanya kadang panas, kadang dingin）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は雨が降ったりやんだりしています。</span>（Hari ini hujannya turun lalu berhenti, turun lagi lalu berhenti）</div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'>Ada tiga langkah: <b>ubah kata kerja ke bentuk た → tambahkan り di belakangnya → tutup dengan します</b>.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだり</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったり</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たり</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たり</span></span><br>Kalau bentuk た belum lancar, bayangkan saja: <b>ganti「て」pada bentuk て dengan「た」, dan「で」dengan「だ」</b>:<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>Kata sifat い</b>: buang「い」, lalu ganti dengan「かったり」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かったり</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったり</span></span>（<span class='gd-jp'>いい</span> berubah menjadi <span class='gd-jp'>よかったり</span>）<br><b>Kata benda dan kata sifat な</b>: tambahkan「だったり」di belakangnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ごはんはパンだったりご飯だったりします。</span>（Sarapanku kadang roti, kadang nasi）</div><div class='gd-sec'>Bentuk lampau dan tingkat kesopanan, semuanya diatur oleh <b>する di bagian akhir</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は友達と話したり、ゲームをしたりしました。</span>（Kemarin aku ngobrol dengan teman, main game, dan semacamnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家で寝たり、テレビを見たりする。</span>（Akhir pekan aku tidur-tiduran di rumah, nonton TV, dan semacamnya: bentuk santai untuk bicara dengan teman）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Sambungkan dengan <b>bentuk た</b>, bukan bentuk ます: yang benar <span class='gd-jp'>行ったり</span>, bukan 行きたり; yang benar <span class='gd-jp'>読んだり</span>, bukan 読みたり。<br>・Jangan lupa <span class='gd-jp'>します</span> (atau <span class='gd-jp'>する</span>) di akhir kalimat. Tanpa itu, kalimatnya terdengar menggantung.<br>・Bentuk lampau hanya mengubah bagian paling belakang: yang benar <span class='gd-jp'>行ったりしました</span>, tidak pernah dibilang 行きましたり。<br>・Kalau ada dua kegiatan atau lebih, setiap kegiatan diberi たり. Dalam percakapan, kadang たり yang kedua dihilangkan, tapi untuk ujian dan tulisan, tulis lengkap ya. Menyebut satu kegiatan saja juga boleh, misalnya <span class='gd-jp'>映画を見たりします</span>（kadang nonton film dan semacamnya）。<br>・たり <b>tidak menunjukkan urutan</b>. Kalau mau bilang \"A dulu, baru B\", pakai bentuk て.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bercerita \"kemarin ngapain aja\":<br><b>て</b> = menceritakan sesuai urutan, dan hanya itu saja kegiatannya: <span class='gd-jp'>昨日は本を読んで、映画を見ました。</span>（Kemarin aku baca buku, lalu nonton film）<br><b>たり</b> = memilih beberapa kegiatan sebagai contoh, masih ada yang lain, urutan tidak penting: <span class='gd-jp'>昨日は本を読んだり、映画を見たりしました。</span>（Kemarin aku baca buku, nonton film, dan semacamnya）<br><b>や</b> = juga untuk memberi contoh, tapi menyambung <b>benda (kata benda)</b>: <span class='gd-jp'>昨日は本や漫画を読みました。</span>（Kemarin aku membaca buku, komik, dan semacamnya）</div><div class='gd-warn'>Trik cepat: kalau menceritakan semuanya sesuai urutan, pakai「て」; kalau memberi contoh beberapa <b>kegiatan</b>, pakai「たり」; kalau memberi contoh beberapa <b>benda</b>, pakai「や」.</div>","n5-1":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「Kata benda＋です」kira-kira berarti <b>「adalah ～」</b>, dan「kata benda＋じゃありません」berarti <b>「bukan ～」</b>. <span class='gd-jp'>私は学生です。</span> artinya \"Saya mahasiswa/pelajar\". Ini kalimat paling dasar dalam bahasa Jepang, dan akan kamu pakai di kalimat pertama saat perkenalan diri.</div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'>Gampang sekali: tambahkan <b>langsung</b> di belakang kata benda, dan kata bendanya sama sekali tidak berubah.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生です</span></span>（adalah pelajar）<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃありません</span></span>（bukan pelajar）<br>Pola kalimatnya「A<span class='gd-jp'>は</span>B<span class='gd-jp'>です</span>」= A adalah B.</div><div class='gd-ex-line'>・<span class='gd-jp'>林です。よろしくお願いします。</span>（Saya Lin. Mohon bantuannya）</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>（Ini payungku）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは先生じゃありません。</span>（Pak Tanaka bukan guru）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みじゃありません。</span>（Besok bukan hari libur）</div><div class='gd-sec'>Tambahkan <span class='gd-jp'>か</span> di belakangnya, maka jadi kalimat tanya: <span class='gd-jp'>学生ですか。</span>（Apakah kamu pelajar?）</div><div class='gd-h'>Beberapa cara bilang \"bukan\"</div><div class='gd-sec'>Artinya sama, bedanya di situasi pemakaian:<br><span class='gd-tag'>Paling umum</span><span class='gd-jp'>学生じゃありません</span>: cara bilang yang sopan untuk sehari-hari.<br><span class='gd-tag'>Lebih formal</span><span class='gd-jp'>学生ではありません</span>: untuk tulisan dan situasi formal.「じゃ」itu bentuk「では」yang diucapkan cepat.<br><span class='gd-tag'>Lebih santai</span><span class='gd-jp'>学生じゃないです</span>: tetap sopan, tapi nadanya lebih lembut, dan sekarang sangat sering dipakai orang Jepang.</div><div class='gd-h'>Saat bicara dengan teman</div><div class='gd-sec'>Dengan keluarga atau teman dekat, です tidak dipakai, diganti <b>だ／じゃない</b>:<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><br>Tapi dalam obrolan sungguhan,「だ」sering dihilangkan, atau ditambah「よ」supaya lebih natural. Kalau tidak, terdengar agak kaku:</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、学生だよ。</span>（Iya, aku pelajar kok）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・<span class='gd-jp'>は</span> dalam「AはB」dibaca <b>wa</b>, bukan ha.<br>・「す」di akhir <span class='gd-jp'>です</span> biasanya diucapkan sangat ringan, sehingga terdengar seperti \"des\".<br>・です tidak selalu diterjemahkan jadi \"adalah\": <span class='gd-jp'>今日は雨です。</span> artinya \"Hari ini hujan\". Dalam bahasa Indonesia kita tidak bilang \"hari ini adalah hujan\".<br>・です tidak boleh ditempelkan setelah kata kerja: cukup <span class='gd-jp'>食べます</span>, tidak bisa bilang「食べるです」.<br>・Kamu tidak perlu mengucapkan <span class='gd-jp'>私は</span> di setiap kalimat. Kalau lawan bicara sudah tahu kamu sedang membicarakan dirimu sendiri, orang Jepang biasanya menghilangkannya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Negatif kata benda dan kata sifat な sama-sama memakai じゃありません, tapi <b>kata sifat い berbeda</b>. Ini yang paling gampang tertukar.<br><b>Kata benda</b>: <span class='gd-jp'>ここは駅じゃありません。</span>（Ini bukan stasiun）<br><b>Kata sifat な</b>: <span class='gd-jp'>ここは静かじゃありません。</span>（Tempat ini tidak tenang）<br><b>Kata sifat い</b>: <span class='gd-jp'>ここは高くないです。</span>（Tempat ini tidak mahal）<br>Tidak bisa bilang「高いじゃありません」. Ganti い dengan <b>くない</b>.</div><div class='gd-warn'>Trik cepat: kata benda dan kata sifat な langsung ditambah「じゃありません」; kata sifat い ganti い menjadi「くないです」. Hati-hati, <span class='gd-jp'>きれい</span> memang berakhiran い, tapi sebenarnya kata sifat な, jadi bilangnya <span class='gd-jp'>きれいじゃありません</span>.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk lampau: <span class='gd-jp'>学生でした</span>（dulu pelajar）, <span class='gd-jp'>学生じゃありませんでした</span>（dulu bukan pelajar）.</div>","n5-54":"<div class='gd-h'>Satu kalimat langsung paham</div><div class='gd-sec'>Tiga pola kalimat ini dipakai untuk menyusun <b>urutan melakukan sesuatu</b>, dan gampang dipahami seperti di bahasa Indonesia:<br><span class='gd-jp'>〜てから</span>＝「dulu ～, baru ～」<br><span class='gd-jp'>〜たあとで</span>＝「setelah ～」<br><span class='gd-jp'>〜まえに</span>＝「sebelum ～」<br>Bayangkan kamu sedang menceritakan harimu ke teman: sikat gigi dulu baru tidur, nonton TV setelah makan, cek cuaca sebelum keluar rumah.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Dulu ～, baru ～</span>Verba <b>bentuk te</b> + から。<br><span class='gd-pair'><span class='gd-jp'>磨く</span> → <span class='gd-jp'>磨いて</span> → <span class='gd-jp'>磨いてから</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてから</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してから</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>歯を磨いてから、寝ます。</span>（Sikat gigi dulu, baru tidur）</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってから、食べてください。</span>（Cuci tangan dulu, baru makan ya）</div><div class='gd-sec'><span class='gd-tag'>Setelah ～</span>Verba <b>bentuk ta</b> + あとで。Bentuk ta didapat dengan mengganti 「て」 pada bentuk te menjadi 「た」, dan 「で」 menjadi 「だ」.<br><span class='gd-pair'><span class='gd-jp'>見て</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たあとで</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだあとで</span></span><br>Kalau di depannya kata benda, sisipkan 「の」 di tengah：<span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のあとで</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見たあとで、ご飯を食べました。</span>（Setelah nonton film, aku makan）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のあとで、ビールを飲みます。</span>（Setelah pulang kerja, aku minum bir）</div><div class='gd-sec'><span class='gd-tag'>Sebelum ～</span>Verba <b>bentuk kamus</b> (bentuk dasar yang kamu temukan di kamus) + まえに。<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝るまえに</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまえに</span></span><br>Kalau di depannya kata benda, tetap tambahkan 「の」：<span class='gd-pair'><span class='gd-jp'>食事</span> → <span class='gd-jp'>食事のまえに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寝るまえに、シャワーを浴びます。</span>（Mandi sebentar sebelum tidur）</div><div class='gd-ex-line'>・<span class='gd-jp'>食事のまえに、手を洗います。</span>（Cuci tangan sebelum makan）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depan まえに <b>selalu bentuk kamus</b>, bahkan saat membicarakan hal yang sudah lewat：<span class='gd-jp'>日本へ来るまえに、英語を勉強しました。</span>（Sebelum datang ke Jepang, aku sudah belajar bahasa Inggris）. Tidak boleh bilang 「来たまえに」.<br>・Di depan あとで <b>selalu bentuk ta</b>, bahkan saat membicarakan hal yang belum terjadi：<span class='gd-jp'>食べたあとで、歯を磨きます。</span>（Setelah makan, aku akan sikat gigi）. Tidak boleh bilang 「食べるあとで」.<br>・Apakah seluruh kalimat bermakna lampau atau sekarang, <b>itu ditentukan di akhir kalimat</b> (磨きます／磨きました). Bagian depan tidak perlu ikut berubah.<br>・Kalau kata benda disambung langsung, 「の」 sering terlupa: yang benar <span class='gd-jp'>授業のあとで</span>, bukan 「授業あとで」.<br>・Kalau <span class='gd-jp'>あとで</span> berdiri sendiri tanpa apa pun di depannya, artinya 「nanti, sebentar lagi」：<span class='gd-jp'>あとで電話します。</span>（Nanti aku telepon kamu）</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>てから dan あとで sama-sama berarti 「setelah A selesai, baru B」. Sering kali keduanya bisa dipakai, bedanya ada di nuansa:<br><span class='gd-jp'>お風呂に入ってから、ご飯を食べます。</span>（Mandi <b>dulu</b>, <b>baru</b> makan: menekankan urutan, terasa seperti 「baru makan setelah mandi」）<br><span class='gd-jp'>お風呂に入ったあとで、ご飯を食べます。</span>（Setelah mandi, aku makan: hanya menyebutkan bahwa waktu makannya ada di belakang）<br>Kalau kamu ingin lawan bicara 「harus menyelesaikan A dulu」, てから paling alami：<br><span class='gd-jp'>電話してから来てください。</span>（Telepon dulu, baru datang ya）</div><div class='gd-warn'>Tips cepat: mau bilang 「dulu ～, baru ～」 pakai <b>てから</b>; sekadar 「setelah ～」 pakai <b>たあとで</b>; 「sebelum ～」 pakai <b>まえに</b>, dan di depannya pasti bentuk kamus.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau てから diikuti keterangan jangka waktu, artinya jadi 「sejak ～ sudah ...」：<span class='gd-jp'>日本に来てから、もう三年です。</span>（Sudah tiga tahun sejak aku datang ke Jepang）</div>","n5-58":"<div class='gd-h'>Satu kalimat langsung paham</div><div class='gd-sec'>「〜ながら」 sama dengan <b>「sambil ～」</b> dalam bahasa Indonesia. Tapi bahasa Jepang punya kebiasaan: <b>hal yang lebih penting ditaruh di belakang</b>. Misalnya 「belajar sambil dengar musik」: kegiatan utamamu belajar, musik hanya pendamping, jadi dalam bahasa Jepang dibilang <span class='gd-jp'>音楽を聞きながら勉強します。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke bentuk ます dulu, lalu <b>buang 「ます」</b> dan langsung tambahkan 「ながら」. Berlaku sama untuk ketiga golongan verba.<br><span class='gd-pair'><span class='gd-jp'>聞きます</span> → buang ます → <span class='gd-jp'>聞きながら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べながら</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見ながら</span></span><span class='gd-pair'><span class='gd-jp'>運転します</span> → <span class='gd-jp'>運転しながら</span></span><br>Setelah itu sambungkan dengan aksi utamanya. 「ながら」 sendiri <b>tidak pernah berubah</b>; soal lampau, negatif, dan sopan atau tidak, semuanya diserahkan ke verba terakhir.</div><div class='gd-ex-line'>・<span class='gd-jp'>歌を歌いながら、料理しました。</span>（Aku memasak sambil bernyanyi）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dua hal di waktu yang sama</span>Tanganmu mengerjakan yang ini, sekaligus mengerjakan yang itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビを見ながら、ご飯を食べます。</span>（Makan sambil nonton TV）</div><div class='gd-ex-line'>・<span class='gd-jp'>歩きながらスマホを見るのは危ないです。</span>（Melihat HP sambil jalan itu berbahaya）</div><div class='gd-sec'><span class='gd-tag'>Dua hal dikerjakan dalam periode ini</span>Tidak harus di detik yang sama. Bisa juga dua hal berjalan paralel dalam beberapa waktu terakhir, seperti 「kerja sambil kuliah」.</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトをしながら、日本語を勉強しています。</span>（Aku belajar bahasa Jepang sambil kerja paruh waktu）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk ます tanpa ます</b>, bukan bentuk kamus：<span class='gd-jp'>聞きながら</span> yang benar, tidak boleh 「聞くながら」；<span class='gd-jp'>食べながら</span> yang benar, tidak boleh 「食べるながら」.<br>・Kedua hal itu harus dilakukan oleh <b>orang yang sama</b>. 「Saat ibu memasak, aku menonton TV」 melibatkan dua orang, jadi tidak bisa pakai ながら. Ganti dengan 「とき」：<span class='gd-jp'>母が料理をしているとき、私はテレビを見ていました。</span><br>・Jangan menukar urutan seenaknya seperti di bahasa Indonesia. Di bahasa Indonesia, 「sambil A, B」 kalau ditukar maknanya hampir sama, tapi dalam bahasa Jepang <b>yang di belakang adalah yang utama</b>. <span class='gd-jp'>勉強しながら音楽を聞きます</span> terdengar seperti 「utamanya mendengarkan musik, sambil belajar」.<br>・Bentuk lampau dan sopan hanya mengubah verba terakhir; jangan menambahkan ました sebelum ながら. Tidak boleh bilang 「聞きましたながら」, yang benar <span class='gd-jp'>聞きながら勉強しました</span>.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>Sambungan bentuk te</b> = selesaikan satu hal, <b>baru</b> lanjut ke hal berikutnya, ada urutannya.<br><b>ながら</b> = dua hal berjalan <b>bersamaan</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べて、テレビを見ます。</span>（Selesai makan, lalu nonton TV）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べながら、テレビを見ます。</span>（Nonton TV sambil makan）</div><div class='gd-sec'><b>〜たり〜たりします</b> = menyebut beberapa contoh hal yang dilakukan, bukan dilakukan bersamaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は本を読んだり、映画を見たりします。</span>（Akhir pekan biasanya baca buku, nonton film, dan semacamnya）</div><div class='gd-warn'>Tips cepat: dilakukan bersamaan pakai ながら, selesai satu baru lanjut pakai bentuk te, dan menyebut beberapa contoh kegiatan pakai たり〜たり.</div>","n5-62":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, 'pintu terbuka' dan 'aku membuka pintu' sama-sama berasal dari kata dasar 'buka', hanya imbuhannya yang berbeda. Di bahasa Jepang, <b>kata kerjanya diganti dengan kata lain</b>. Untuk 'pintu terbuka' kita pakai <span class='gd-jp'>開く</span>, sedangkan untuk 'seseorang membuka pintu' kita pakai <span class='gd-jp'>開ける</span>. Yang pertama disebut <b>kata kerja intransitif (自動詞)</b>, yang kedua <b>kata kerja transitif (他動詞)</b>. Partikel di depannya juga ikut berganti.</div><div class='gd-h'>Kenali dua namanya dulu</div><div class='gd-sec'><span class='gd-tag'>Intransitif＋が</span>Hanya menyatakan 'sesuatu menjadi begini', tanpa peduli siapa yang melakukannya. Di depannya dipakai <b>が</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開きます。</span>(Pintunya akan terbuka: pengumuman yang sering kamu dengar di kereta)</div><div class='gd-sec'><span class='gd-tag'>Transitif＋を</span>Menyatakan 'seseorang melakukan sesuatu pada benda'. Benda yang dikenai tindakan diikuti <b>を</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアを開けます。</span>(Aku membuka pintu)</div><div class='gd-sec'>Cara gampang menebaknya: coba lihat bentuk Indonesianya. Kalau ada pelaku yang 'me-kan' atau 'me-' sesuatu (membuka pintu, menyalakan lampu), pakai transitif＋を. Kalau bendanya yang 'ter-' atau 'jadi begitu' dengan sendirinya (pintu terbuka, lampu menyala), pakai intransitif＋が.</div><div class='gd-h'>Pasangan yang paling sering muncul</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がつきました。</span>(Lampunya menyala)</div><div class='gd-ex-line'>・<span class='gd-jp'>電気をつけてください。</span>(Tolong nyalakan lampunya)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業が始まります。</span>(Pelajaran akan dimulai)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業を始めます。</span>(Kita mulai pelajarannya)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布が落ちました。</span>(Dompetnya jatuh)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を落としました。</span>(Aku menjatuhkan dompetku)</div><div class='gd-sec'>Ada juga pasangan berikut. Di kiri intransitif, di kanan transitif:<br><span class='gd-jp'>閉まる</span>／<span class='gd-jp'>閉める</span>(tertutup / menutup)<br><span class='gd-jp'>消える</span>／<span class='gd-jp'>消す</span>(padam / mematikan)<br><span class='gd-jp'>入る</span>／<span class='gd-jp'>入れる</span>(masuk / memasukkan)<br><span class='gd-jp'>出る</span>／<span class='gd-jp'>出す</span>(keluar / mengeluarkan)<br>Mana yang intransitif dan mana yang transitif tidak punya satu aturan yang berlaku untuk semuanya. Cara terbaik adalah <b>menghafalnya sepasang demi sepasang bersama contoh kalimat</b>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Partikel dan kata kerja harus cocok: <span class='gd-jp'>電気を消します</span> dan <span class='gd-jp'>電気が消えます</span> sama-sama benar, tapi 「電気を消えます」 salah.<br>・Kalau meminta orang lain melakukan sesuatu, pakai transitif: <span class='gd-jp'>窓を閉めてください</span>. Kamu tidak bisa bilang 「窓が閉まってください」.<br>・<span class='gd-jp'>開く</span> di sini dibaca <b>あく</b>. Kanji yang sama juga bisa dibaca 「ひらく」 dengan penggunaan yang berbeda, jadi jangan dicampur dulu.<br>・<span class='gd-jp'>入る</span> dan <span class='gd-jp'>出る</span> sering dipakai bersama tempat: <span class='gd-jp'>部屋に入ります</span> (masuk ke kamar) memakai に. Pada <span class='gd-jp'>家を出ます</span> (keluar rumah), を menandai 'tempat yang ditinggalkan', bukan 'benda yang dikenai tindakan', jadi 出る tetap intransitif.<br>・Intransitif tidak hanya untuk hal yang terjadi 'dengan sendirinya': <span class='gd-jp'>行く</span> dan <span class='gd-jp'>寝る</span> juga intransitif, padahal itu tindakan yang dilakukan orangnya sendiri. Yang jadi kuncinya adalah <b>ada atau tidaknya benda yang dikenai tindakan</b>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kalau dua jenis kata kerja ini diberi 「〜ています」, artinya beda jauh:<br><span class='gd-jp'>窓が開いています。</span>(Jendelanya terbuka) → hanya menggambarkan keadaan yang kamu lihat<br><span class='gd-jp'>夏はいつも窓を開けています。</span>(Di musim panas aku selalu membuka jendela) → membicarakan tindakan atau kebiasaan seseorang</div><div class='gd-warn'>Trik cepat: kalau kamu cuma melihat keadaan 'terbuka, menyala, tertutup', pakai 'が＋intransitif＋ています'.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Transitif + 「〜てあります」 berarti 'seseorang sengaja melakukannya dan hasilnya dibiarkan begitu': <span class='gd-jp'>窓が開けてあります。</span>(Jendelanya sengaja dibuka oleh seseorang)</div>","n5-15":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Anggap saja 「は」 berarti <b>'Kalau bicara soal ~, ...'</b>. Kamu taruh dulu hal yang mau dibicarakan di awal kalimat, seperti bilang ke lawan bicara 'sekarang aku mau bahas ini ya', lalu setelahnya kamu jelaskan bagaimana hal itu. <span class='gd-jp'>私は学生です。</span> artinya 'Kalau soal aku, aku mahasiswa', alias 'Aku mahasiswa'.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cukup tambahkan は langsung setelah kata benda:<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私は</span></span><span class='gd-pair'><span class='gd-jp'>伊藤さん</span> → <span class='gd-jp'>伊藤さんは</span></span><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日は</span></span><br><b>Cara bacanya penting</b>: saat dipakai sebagai partikel, ditulis <span class='gd-jp'>は</span> tapi dibaca <b>wa</b>, sama dengan bunyi <span class='gd-jp'>わ</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memperkenalkan, menjelaskan</span>Ini pemakaian paling dasar: sebut dulu 'siapa/apa', lalu jelaskan 'bagaimana'.</div><div class='gd-ex-line'>・<span class='gd-jp'>伊藤さんは建築家です。</span>(Pak Ito adalah seorang arsitek)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑いですね。</span>(Hari ini panas ya)</div><div class='gd-sec'><span class='gd-tag'>Topik dulu, baru detail</span>Di depan は diletakkan 'apa yang sedang dibahas', lalu setelahnya bisa muncul tokoh lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>象は鼻が長いです。</span>(Gajah itu hidungnya panjang)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのケーキは姉が焼きました。</span>(Kue itu dipanggang oleh kakakku)</div><div class='gd-sec'>Kalimat kedua sering bikin bingung: yang memanggang kue adalah kakak, bukan kuenya. Jadi <b>yang ada di depan は belum tentu 'pelaku tindakan'</b>. は hanya bilang 'kalimat ini sedang membahas apa'. Di sini yang dibahas adalah kuenya, lalu ditambahkan 'dipanggang oleh kakak'.</div><div class='gd-sec'><span class='gd-tag'>Membandingkan dua hal</span>Kalau kedua sisi memakai は, muncul kesan kontras: 'yang ini begini, kalau yang itu lain ceritanya'.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーは好きですが、お茶はあまり飲みません。</span>(Kalau kopi aku suka, tapi kalau teh jarang kuminum)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・は sebagai partikel dibaca wa. は di akhir salam <span class='gd-jp'>こんにちは</span> dan <span class='gd-jp'>こんばんは</span> juga dibaca wa. は di dalam kata lain tetap dibaca ha, seperti <span class='gd-jp'>はい</span> dan <span class='gd-jp'>花</span>.<br>・Kalau kata tanya seperti 「誰」 atau 「どれ」 menjadi subjek kalimat tanya, di belakangnya harus が, bukan は: <span class='gd-jp'>誰は来ましたか</span> itu salah, yang benar <span class='gd-jp'>誰が来ましたか</span> (Siapa yang datang?).<br>・Topik yang sudah disebut sekali boleh dihilangkan di kalimat berikutnya. Dalam bahasa Indonesia kita kadang mengulang 'aku' atau 'saya' di tiap kalimat. Di bahasa Jepang, setelah <span class='gd-jp'>私は</span> disebut sekali, biasanya tidak diulang lagi, dan kalau terus diulang malah terdengar bertele-tele: <span class='gd-jp'>私は陳です。台湾から来ました。</span>(Aku Chen. Aku datang dari Taiwan.)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>は dan が adalah pasangan yang paling mudah tertukar. Coba lihat satu situasi yang sama: ada rekan kerja baru di kantor.<br>Orang-orang belum mengenalmu, lalu kamu memperkenalkan diri: <span class='gd-jp'>私は陳です。</span>(Aku Chen) → yang ingin diketahui orang adalah 「陳」 di <b>belakang</b>.<br>Lalu ada yang mencarimu: <span class='gd-jp'>陳さんはどちらですか。</span>(Maaf, yang mana ya Pak/Bu Chen?) Kamu mengangkat tangan dan bilang: <span class='gd-jp'>私が陳です。</span>(Akulah Chen) → kali ini intinya ada pada 「私」 di <b>depan</b>.<br>Selain itu, hal yang baru saja kamu lihat atau baru terjadi di depan mata juga memakai が: <span class='gd-jp'>あ、バスが来ました。</span>(Ah, busnya datang)</div><div class='gd-warn'>Trik cepat: kalau pakai は, intinya ada di <b>belakang は</b>. Kalau pakai が, intinya ada di <b>depan が</b>. Jawaban atas 'siapa? yang mana?' dan hal yang baru dilihat memakai が.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau は diganti dengan <b>も</b>, artinya jadi 'juga': <span class='gd-jp'>私も学生です。</span>(Aku juga mahasiswa). Perhatikan bahwa は diganti langsung, bukan ditumpuk. Tidak ada bentuk seperti 「私はも」.</div>","n5-34":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「が」itu seperti menunjuk dengan jari sambil bilang <b>“Nah, ini dia!”</b>. Kalau kamu ingin menyebut dengan jelas <b>siapa</b> yang melakukan sesuatu atau <b>apa</b> yang terjadi, taruh が setelahnya.<br>Misalnya ada yang tanya “Siapa yang datang?”, lalu kamu jawab “Tanaka-san yang datang”. “Tanaka-san” itulah jawaban yang ditunjuk, jadi pakai <span class='gd-jp'>田中さんが来ました</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tambahkan が langsung setelah kata benda, tanpa perubahan apa pun.<br><span class='gd-jp'>私が</span>、<span class='gd-jp'>雨が</span>、<span class='gd-jp'>田中さんが</span>、<span class='gd-jp'>誰が</span>、<span class='gd-jp'>何が</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menanyakan siapa / apa</span>Kalau “siapa” atau “apa” menjadi pokok kalimat, pakai が saat bertanya, dan jawabannya juga pakai が.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ましたか。</span>（Siapa yang datang?）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来ました。</span>（Tanaka-san yang datang.）</div><div class='gd-ex-line'>・<span class='gd-jp'>何が一番おいしいですか。</span>（Apa yang paling enak?）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンが一番おいしいです。</span>（Ramen inilah yang paling enak.）</div><div class='gd-sec'><span class='gd-tag'>Hal yang terlihat di depan mata</span>Untuk keadaan yang baru saja kamu lihat atau baru saja terjadi, langsung ucapkan saja pemandangannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、バスが来ました。</span>（Ah, busnya datang.）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降っています。</span>（Salju sedang turun.）</div><div class='gd-sec'><span class='gd-tag'>Disebut untuk pertama kali</span>Untuk orang atau hal yang belum diketahui lawan bicara, dan kamu memunculkannya untuk pertama kali.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、友達が家に来ました。</span>（Kemarin ada teman yang datang ke rumahku.）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Setelah “siapa, apa, di mana” tidak boleh pakai は</b>. <span class='gd-jp'>誰は来ましたか</span> itu salah, yang benar <span class='gd-jp'>誰が来ましたか</span>. Kata tanya lain juga sama, misalnya <span class='gd-jp'>どこが痛いですか</span>（Bagian mana yang sakit?）.<br>・<b>Kalau bertanya pakai が, jawabnya juga pakai が</b>. Kalau ada yang tanya <span class='gd-jp'>誰が作りましたか</span>（Siapa yang membuatnya?）, jawabnya <span class='gd-jp'>私が作りました</span>（Aku yang membuatnya）. Kalau kamu jawab “私は作りました”, nuansanya jadi “Kalau aku sih memang bikin (yang lain entah ya)”, dan itu terdengar aneh.<br>・Dalam bahasa Indonesia, subjek tidak perlu penanda apa pun, jadi gampang sekali tergoda menaruh は pada setiap subjek. Padahal kalau tiba-tiba melihat hujan turun di luar jendela, yang alami adalah <span class='gd-jp'>あ、雨が降っています</span>. Kalimat yang langsung menggambarkan pemandangan di depan mata memang pakai が.<br>・<span class='gd-jp'>日本語が好きです</span>、<span class='gd-jp'>ピアノができます</span> juga pakai が, tapi itu pola “suka apa, bisa apa”. Pola itu dibahas di kartu lain, “Partikel が (kemampuan・suka/tidak suka)”, jadi jangan dicampur dulu.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>は</b> artinya “kalau bicara soal ～ sih”. Topik ditaruh dulu, dan <b>poin pentingnya ada di belakang</b>.<br><b>が</b> artinya “justru ～ itu”, dan <b>poin pentingnya ada di kata benda di depannya</b>.<br><br>Sama-sama bilang bahwa kamu adalah Tanaka:<br>Saat perkenalan diri, kamu bilang <span class='gd-jp'>私は田中です。</span>（Saya Tanaka.）Di sini orang mendengarkan “kamu itu siapa”.<br>Kalau ada yang tanya <span class='gd-jp'>田中さんはどの人ですか。</span>（Tanaka-san yang mana ya?）, kamu jawab <span class='gd-jp'>私が田中です。</span>（Sayalah Tanaka.）Di sini Tanaka ditunjuk dari antara banyak orang.<br><br>Sama-sama bilang Tanaka datang:<br><span class='gd-jp'>田中さんが来ました。</span>（Tanaka-san datang.）Hanya melaporkan siapa yang datang.<br><span class='gd-jp'>田中さんは来ました。</span>（Tanaka-san sih datang.）Tanaka dijadikan topik dulu, dengan nuansa “kalau yang lain belum tentu”.</div><div class='gd-warn'>Trik menilai: kalau kamu menjawab “siapa / apa”, pakai が. Kalau kamu mau bilang “orang atau benda ini bagaimana”, pakai は. Kalau kata tanya menjadi pokok kalimat, selalu pakai が.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>“Ada sesuatu di suatu tempat” juga pakai が: <span class='gd-jp'>あそこに猫がいます。</span>（Di sana ada seekor kucing.）Selanjutnya kamu bisa belajar ungkapan keberadaan, serta cara pakai が untuk “suka” dan “bisa”.</div>","n5-31":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「から」artinya sama dengan <b>“karena ～, jadi ～”</b> dalam bahasa Indonesia. Bedanya, kita menaruh “karena” di depan alasan, sedangkan から ditaruh di <b>paling akhir kalimat alasan</b>. Jadi alasan disebut dulu, baru hasilnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないから、急ぎましょう。</span>（Karena tidak ada waktu, ayo cepat）</div><div class='gd-sec'>Urutannya: <b>alasan ＋ から、hasil</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan「から」ada satu kalimat utuh, bisa bentuk biasa, bisa juga bentuk sopan dengan です・ます.<br><b>Kata kerja</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くから</span></span><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますから</span></span><br><b>Kata sifat い</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いから</span></span><span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒いですから</span></span><br><b>Kata sifat な</b>：harus tambah「だ」atau「です」dulu.<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かですから</span></span><br><b>Kata benda</b>：sama, harus tambah「だ」atau「です」.<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だから</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨ですから</span></span><br>Untuk kejadian yang sudah lewat juga bisa:<span class='gd-pair'><span class='gd-jp'>寝なかった</span> → <span class='gd-jp'>寝なかったから</span></span></div><div class='gd-sec'>Bagian depan bentuk biasa dan akhir kalimat pakai ます itu sangat umum dalam percakapan sehari-hari. Kalau mau lebih sopan, pakai です・ます di depan dan belakang.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan alasan</span>Sebut penyebabnya dulu, baru hasilnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いから、よく来ます。</span>（Toko ini murah, jadi aku sering datang）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は日曜日だから、学校は休みです。</span>（Hari ini hari Minggu, jadi sekolah libur）</div><div class='gd-sec'><span class='gd-tag'>Meminta, mengingatkan, mengajak</span>Setelahnya boleh juga disambung dengan permintaan atau ajakan, dan terdengar alami.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないですから、触らないでください。</span>（Ini berbahaya, jadi tolong jangan disentuh）</div><div class='gd-sec'><span class='gd-tag'>Hanya menjawab alasannya</span>Kalau ada yang bertanya “kenapa” dan hasilnya sudah sama-sama diketahui, cukup sebut alasannya plus から.</div><div class='gd-ex-line'>・<span class='gd-jp'>「どうして食べないの？」「辛いから。」</span>（“Kenapa kamu nggak makan?” “Karena pedas.”）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat な, <b>tidak boleh langsung pakai から</b>. Yang benar <span class='gd-jp'>雨だから</span>, bukan “雨から”. Yang benar <span class='gd-jp'>静かだから</span>, bukan “静かから”.<br>・Kata sifat い justru sebaliknya, <b>tidak boleh ditambah だ</b>. Yang benar <span class='gd-jp'>高いから</span>, bukan “高いだから”.<br>・Jangan menaruh から di awal kalimat mengikuti urutan “karena” dalam bahasa Indonesia. “Karena hujan” adalah <span class='gd-jp'>雨だから</span>, から ada di belakang.<br>・Kalau <span class='gd-jp'>だから</span> berdiri sendiri di awal kalimat, artinya “jadi / makanya”: <span class='gd-jp'>雨です。だから、行きません。</span>（Hujan. Jadi aku tidak pergi）<br>・Saat menjelaskan keadaanmu kepada guru atau atasan (misalnya alasan terlambat), から terdengar agak langsung dan kadang seperti mencari-cari alasan. Dalam obrolan sehari-hari memakai から sama sekali tidak masalah.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kamu sudah belajar「から」yang menunjukkan titik awal (<b>dari ～</b>), dan bentuknya persis sama.<br><b>Titik awal</b>：<span class='gd-jp'>9時から働きます。</span>（Bekerja mulai jam 9）<br><b>Alasan</b>：<span class='gd-jp'>雨だから、働きません。</span>（Karena hujan, aku tidak bekerja）<br>Bedanya ada pada apa yang ada di depannya: から titik awal didahului langsung oleh kata benda waktu atau tempat, sedangkan から alasan didahului akhir dari satu kalimat, misalnya kata kerja, kata sifat, atau「だ」「です」.</div><div class='gd-warn'>Trik menilai: kalau di depan から hanya ada kata benda seperti <span class='gd-jp'>9時</span>、<span class='gd-jp'>駅</span>, artinya “dari”. Kalau di depannya ada bentuk utuh seperti <span class='gd-jp'>雨だ</span>、<span class='gd-jp'>寒い</span>、<span class='gd-jp'>あります</span>, artinya “karena”.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau alasan ditaruh di akhir kalimat, jadilah「〜からです」untuk menjawab “kenapa”: <span class='gd-jp'>熱があるからです。</span>（Karena demam）. Nanti kamu juga akan belajar「〜ので」yang juga berarti “karena”, tapi nadanya lebih lembut daripada から, dan lebih sering dipakai saat izin kepada atasan atau minta maaf.</div>","n5-4":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Kata yang dipakai untuk menggambarkan benda, seperti 「冷」「貴」「好吃」 (dingin, mahal, enak), disebut <b>い形容詞</b> dalam bahasa Jepang, karena huruf terakhirnya selalu 「い」, misalnya <span class='gd-jp'>寒い</span>, <span class='gd-jp'>高い</span>, <span class='gd-jp'>おいしい</span>.<br>Untuk bilang \"dingin\" dengan sopan, tinggal tambahkan <b>です</b> di belakangnya. Untuk bilang \"tidak dingin\", ganti い di akhir dengan <b>く</b>, lalu tambahkan <b>ないです</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Positif</span>Bentuk aslinya langsung ditambah です, い di akhir tidak perlu diubah.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いです</span></span></div><div class='gd-sec'><span class='gd-tag'>Negatif</span>Ganti い di akhir dengan く, lalu tambahkan ないです.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い diganti く → <span class='gd-jp'>寒く</span> → <span class='gd-jp'>寒くないです</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くないです</span></span><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしくないです</span></span><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくないです</span></span></div><div class='gd-sec'>Di buku pelajaran kamu juga akan menemukan <span class='gd-jp'>寒くありません</span>. Artinya sama, hanya terdengar sedikit lebih formal. Untuk percakapan sehari-hari, 「くないです」 sudah cukup.</div><div class='gd-h'>Coba ucapkan</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいです。</span>（Ramen ini enak）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は広くないです。</span>（Kamar ini tidak luas）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はあまり寒くないです。</span>（Hari ini tidak begitu dingin）</div><div class='gd-sec'>Dalam bahasa Indonesia kita sering bilang \"<b>sangat</b> dingin\" untuk menekankan, sedangkan <span class='gd-jp'>寒いです</span> sendiri sudah berarti \"dingin\", jadi tidak perlu dipaksa menambah 「とても」. Kalau memang dingin sekali dan mau menekankannya, baru bilang <span class='gd-jp'>とても寒いです</span>.<br>Selain itu, <span class='gd-jp'>あまり</span> yang diikuti bentuk negatif artinya \"<b>tidak begitu</b>～\", lebih halus daripada langsung bilang \"tidak ～\", dan sangat sering dipakai orang Jepang.</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・<span class='gd-jp'>いい</span> adalah pengecualian: bentuk negatifnya <b><span class='gd-jp'>よくないです</span></b>, bukan いくないです. Sebab いい berasal dari <span class='gd-jp'>よい</span>, jadi saat berubah bentuk yang dipakai adalah よ. <span class='gd-jp'>かっこいい</span> juga sama, negatifnya <span class='gd-jp'>かっこよくないです</span>.<br>・Untuk bilang \"tidak dingin\", kamu tidak boleh bilang 寒いじゃないです. Negatif い形容詞 selalu dengan mengganti い menjadi く, bukan memakai じゃない.<br>・Jangan menambahkan だ di tengah: 寒いだです itu salah. Kalau mau sopan, katakan <span class='gd-jp'>寒いです</span>, dan kalau bicara dengan teman cukup <span class='gd-jp'>寒い</span>.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>有名</span> terdengar berakhiran 「い」 juga, tetapi mereka adalah な形容詞, jadi negatifnya <span class='gd-jp'>きれいじゃないです</span>, bukan きれくないです.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bilang \"kamar ini tidak ～\", cara membuat negatifnya berbeda tergantung jenis kata di depannya:<br><b>い形容詞</b>: ganti い menjadi く, tambahkan ないです<br>・<span class='gd-jp'>この部屋は明るくないです。</span>（Kamar ini tidak terang）<br><b>な形容詞</b>: tambahkan じゃないです di belakangnya<br>・<span class='gd-jp'>この部屋は静かじゃないです。</span>（Kamar ini tidak tenang）<br><b>Kata benda</b>: juga ditambah じゃないです di belakangnya<br>・<span class='gd-jp'>ここは私の部屋じゃないです。</span>（Ini bukan kamarku）</div><div class='gd-warn'>Trik menentukan: kalau huruf terakhir aslinya 「い」, ganti い dengan く lalu tambahkan ないです. Untuk な形容詞 dan kata benda, langsung tambahkan じゃないです. Hati-hati dengan きれい, 嫌い, 有名, karena semuanya な形容詞.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk lampau: <span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒かったです</span></span>（tadinya dingin）<br>Menyatakan perubahan: <span class='gd-jp'>寒くなります</span>（akan menjadi dingin）. 「く」 yang dipakai di bentuk negatif tadi akan muncul lagi di sini.</div>","n5-5":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜です」 artinya \"adalah ～\", dan 「〜でした」 artinya <b>\"(dulu/waktu itu) adalah ～\"</b>. Dalam bahasa Indonesia, untuk cerita masa lalu kita cukup menambahkan kata seperti \"kemarin\" atau \"dulu\" dan bentuk katanya tidak berubah. Dalam bahasa Jepang tidak bisa begitu: <b>untuk masa lalu, です harus diganti menjadi でした</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Adalah</span>Tambahkan でした langsung setelah kata benda.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生でした</span></span><span class='gd-pair'><span class='gd-jp'>休みです</span> → <span class='gd-jp'>休みでした</span></span></div><div class='gd-sec'><span class='gd-tag'>Bukan</span>Pakai 「じゃありません」 bentuk sekarang dulu, lalu tambahkan でした di belakangnya.<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃありませんでした</span></span><br>Dalam tulisan, yang lebih formal adalah <span class='gd-jp'>ではありませんでした</span>, artinya sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でした。</span>（Kemarin hujan）</div><div class='gd-ex-line'>・<span class='gd-jp'>先週の月曜日は祝日でした。</span>（Senin minggu lalu hari libur nasional）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みじゃありませんでした。</span>（Kemarin bukan hari libur）</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Tanya masa lalu</span>Tambahkan か di akhir kalimat, maka jadi kalimat tanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みでしたか。</span>（Kemarin kamu libur?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、休みでした。</span>（Ya, libur）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、休みじゃありませんでした。</span>（Tidak, tidak libur）</div><div class='gd-sec'><span class='gd-tag'>Versi teman</span>Kalau bicara dengan teman dekat, ganti でした menjadi <b>だった</b>, dan じゃありませんでした menjadi <b>じゃなかった</b>.<br><span class='gd-pair'><span class='gd-jp'>雨でした</span> → <span class='gd-jp'>雨だった</span></span><span class='gd-pair'><span class='gd-jp'>休みじゃありませんでした</span> → <span class='gd-jp'>休みじゃなかった</span></span></div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・Karena terbiasa dengan bahasa Indonesia, kamu mungkin merasa kata 「昨日」 di depan sudah cukup, lalu bilang <span class='gd-jp'>昨日は休みです</span>. Dalam bahasa Jepang harus diubah menjadi <span class='gd-jp'>休みでした</span>.<br>・Bentuk lampau dari 「bukan」 paling sering salah sambung: <span class='gd-jp'>学生じゃないでした</span> dan <span class='gd-jp'>学生じゃでした</span> keduanya salah, yang benar <span class='gd-jp'>学生じゃありませんでした</span>.<br>・Dalam percakapan sehari-hari kamu juga sering mendengar <span class='gd-jp'>学生じゃなかったです</span>. Ini sama-sama sopan dan juga benar, jadi tidak perlu kaget kalau mendengarnya.<br>・でした hanya bisa dipasang setelah kata benda (dan な形容詞). い形容詞 seperti <span class='gd-jp'>寒い</span> dan <span class='gd-jp'>高い</span> tidak bisa langsung ditambah でした: <span class='gd-jp'>寒いでした</span> itu salah, yang benar <span class='gd-jp'>寒かったです</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bercerita tentang \"kemarin\", tetapi kata di depannya berbeda, maka akhirannya juga berbeda:<br><b>Kata benda</b> ＋ でした：<span class='gd-jp'>昨日は雨でした。</span>（Kemarin hujan）<br><b>Kata kerja</b>, ます diganti ました：<span class='gd-jp'>昨日は雨が降りました。</span>（Kemarin turun hujan）<br><b>い形容詞</b>, い diganti かったです：<span class='gd-jp'>昨日は寒かったです。</span>（Kemarin dingin）<br><b>な形容詞</b> sama seperti kata benda, ditambah でした：<span class='gd-jp'>昨日は静かでした。</span>（Kemarin tenang）</div><div class='gd-warn'>Trik menentukan: kalau di depannya kata benda atau な形容詞, pakai でした; kalau kata kerja, pakai ました; kalau い形容詞 (seperti 寒い, 高い), pakai かったです.<br>Perhatian: <span class='gd-jp'>きれい</span>, <span class='gd-jp'>有名</span>, <span class='gd-jp'>嫌い</span> walaupun berakhiran い, termasuk な形容詞, jadi harus pakai でした, misalnya <span class='gd-jp'>きれいでした</span>, bukan きれかったです.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk lampau kata kerja <span class='gd-jp'>〜ました・〜ませんでした</span> dan bentuk lampau い形容詞 <span class='gd-jp'>〜かったです</span>: ingat ketiganya sekaligus, maka kamu tidak akan tersendat saat bercerita tentang masa lalu.</div>","n5-6":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ました」adalah <b>bentuk lampau</b> dari「〜ます」, dan「〜ませんでした」adalah bentuk lampau dari「〜ません」. Dalam bahasa Indonesia kata kerjanya tidak berubah, cukup tambah “kemarin” atau “sudah”: “aku sudah pergi”. Di bahasa Jepang, akhiran kata kerjanya yang diubah: <span class='gd-pair'><span class='gd-jp'>行きます</span>(pergi) → <span class='gd-jp'>行きました</span>(sudah pergi)</span>. Sama seperti ます, ini bentuk sopan, jadi aman dipakai ke guru atau pegawai toko.</div><div class='gd-h'>Cara mengubahnya: asal kamu tahu bentuk ます, beres</div><div class='gd-sec'>Pakai kata “minum” sebagai contoh, ini empat bentuknya sekaligus:<br>Sekarang, melakukan: <span class='gd-jp'>飲みます</span>(minum)<br>Sekarang, tidak melakukan: <span class='gd-jp'>飲みません</span>(tidak minum)<br>Lampau, melakukan: <span class='gd-jp'>飲みました</span>(sudah minum)<br>Lampau, tidak melakukan: <span class='gd-jp'>飲みませんでした</span>(tidak minum / tadi tidak minum)<br><br>Aturannya cuma dua: <b>ます diganti ました</b>; <b>ません ditambah でした di belakangnya</b>.<br>Karena semuanya berangkat dari bentuk ます, aturannya sama persis untuk ketiga golongan kata kerja:<br><b>Golongan 1 (kata kerja godan)</b>: <span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きました</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>: <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べました</span></span><br><b>Golongan 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しました</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ました</span>(きました)</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sudah dilakukan</span>Untuk menceritakan hal yang sudah terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>先月、札幌へ行きました。</span>(Bulan lalu aku pergi ke Sapporo)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見ました。</span>(Kemarin aku nonton film)</div><div class='gd-sec'><span class='gd-tag'>Tidak dilakukan</span>Untuk hal yang tidak dilakukan pada waktu yang sudah lewat.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ご飯を食べませんでした。</span>(Tadi pagi aku tidak sarapan)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題をしませんでした。</span>(Aku tidak mengerjakan PR)</div><div class='gd-sec'><span class='gd-tag'>Bertanya ke orang lain</span>Tambahkan か di belakangnya, jadilah kalimat tanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、何をしましたか。</span>(Akhir pekan kemarin kamu ngapain?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bentuk lampau negatifnya adalah「ません＋<b>でした</b>」. Banyak yang salah mengucapkan「食べませんました」, itu salah.<br>・<span class='gd-jp'>来ました</span> dibaca <b>きました</b>, bukan こました.<br>・Bunyi「し」pada「ました」sering diucapkan sangat ringan, sehingga terdengar seperti “ma-shta”. Kalau kamu mendengarnya, jangan mengira ada satu bunyi yang hilang.<br>・Untuk “belum makan” jangan pakai ませんでした. Kalau temanmu bertanya <span class='gd-jp'>もう食べましたか。</span>(Sudah makan?) dan kamu belum makan tapi nanti mau makan, jawabnya <span class='gd-jp'>いいえ、まだです。</span>(Belum). <span class='gd-jp'>食べませんでした</span> artinya “waktu itu tidak makan”, urusannya sudah lewat.<br>・<span class='gd-jp'>分かりました</span> artinya “aku mengerti, baik”, yang dibicarakan adalah keadaan saat ini, bukan kejadian di masa lalu. Kalau pegawai toko atau rekan kerja menjawab begini, artinya “siap, dimengerti”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Saat belajar bentuk lampau, yang paling gampang tertukar adalah「ました」dan「でした」. Pakai contoh “pesta kemarin” supaya jelas:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、パーティーに行きました。</span>(Kemarin aku pergi ke pesta: kata kerja pakai ました)</div><div class='gd-ex-line'>・<span class='gd-jp'>料理は和食でした。</span>(Makanannya masakan Jepang: kata benda pakai でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>会場はきれいでした。</span>(Tempatnya bagus: kata sifat-な pakai でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(Seru sekali: kata sifat-い pakai かったです)</div><div class='gd-sec'>Kesalahan yang umum:<br>「学生ました」→ yang benar <span class='gd-jp'>学生でした</span><br>「行きでした」→ yang benar <span class='gd-jp'>行きました</span><br>「おいしいでした」→ yang benar <span class='gd-jp'>おいしかったです</span></div><div class='gd-warn'>Trik cepat: kalau di depannya kata kerja, pakai ました; kalau kata benda atau kata sifat-な, pakai でした; kalau kata sifat-い, pakai かったです.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Saat ngobrol dengan teman, bentuk lampau diganti menjadi bentuk tanpa ます, namanya「た形／なかった形」: <span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span>.</div>","n5-7":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'><span class='gd-jp'>静かです</span> artinya “sekarang tenang”. Untuk bilang “<b>dulu</b> tenang”, ganti <span class='gd-jp'>です</span> menjadi <span class='gd-jp'>でした</span>: <span class='gd-jp'>静かでした</span>. Kalau di bahasa Indonesia kita menambahkan “dulu” atau “tadi”, di bahasa Jepang akhirannya yang diubah ke bentuk lampau. Cara mengubahnya <b>persis sama</b> dengan kata benda (<span class='gd-jp'>学生でした</span>), jadi belajar satu berarti sekaligus bisa dua.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata sifat-な adalah kata sifat yang harus diberi「な」saat diletakkan di depan kata benda, seperti <span class='gd-jp'>静かな部屋</span>, <span class='gd-jp'>きれいな花</span>.<br>Langkah 1: buang「な」, sisanya disebut “batang kata” (bagian intinya).<br><span class='gd-pair'><span class='gd-jp'>静かな</span> → buang な → <span class='gd-jp'>静か</span></span><br>Langkah 2: sambungkan akhiran yang kamu butuhkan.<br>Sekarang: <span class='gd-jp'>静かです</span>(tenang) / <span class='gd-jp'>静かじゃありません</span>(tidak tenang)<br>Lampau: <span class='gd-jp'>静かでした</span>(dulu tenang) / <span class='gd-jp'>静かじゃありませんでした</span>(dulu tidak tenang)</div><div class='gd-sec'><span class='gd-tag'>Lampau positif</span>Waktu itu keadaannya begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は暇でした。</span>(Kemarin aku senggang)</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは簡単でした。</span>(Ujiannya mudah)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、野菜が嫌いでした。</span>(Waktu kecil aku tidak suka sayur)</div><div class='gd-sec'><span class='gd-tag'>Lampau negatif</span>Waktu itu keadaannya tidak begitu. Sering dipakai bersama <span class='gd-jp'>あまり</span>(tidak begitu).</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋はあまりきれいじゃありませんでした。</span>(Kamarnya tidak begitu bersih)</div><div class='gd-ex-line'>・<span class='gd-jp'>あまり有名じゃありませんでした。</span>(Waktu itu tidak begitu terkenal)</div><div class='gd-h'>Bentuk lain yang sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Lebih formal</span><span class='gd-jp'>じゃ</span> diganti <span class='gd-jp'>では</span>: <span class='gd-jp'>静かではありませんでした</span>, dipakai dalam tulisan dan situasi resmi.<br><span class='gd-tag'>Sopan, gaya lisan</span><span class='gd-jp'>静かじゃなかったです</span>, artinya sama dan sering terdengar dalam percakapan sehari-hari.<br><span class='gd-tag'>Antarteman</span>でした diganti <span class='gd-jp'>だった</span>, dan bentuk negatifnya <span class='gd-jp'>じゃなかった</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、暇だった。</span>(Kemarin aku senggang)</div><div class='gd-ex-line'>・<span class='gd-jp'>全然大変じゃなかった。</span>(Sama sekali tidak berat)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・「な」harus dibuang: yang benar <span class='gd-jp'>静かでした</span>, bukan「静かなでした」.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>有名</span> memang berakhiran「い」, tetapi semuanya <b>kata sifat-な</b>: yang benar <span class='gd-jp'>きれいでした</span>, bukan「きれいかったです」.<br>・Jangan merakit sendiri bentuk lampau negatif menjadi「静かじゃないでした」. Yang benar adalah <span class='gd-jp'>静かじゃありませんでした</span> atau <span class='gd-jp'>静かじゃなかったです</span>.<br>・<span class='gd-jp'>あまり</span> harus diikuti bentuk negatif: <span class='gd-jp'>あまり暇じゃありませんでした</span>, tidak bisa bilang「あまり暇でした」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk lampau kata sifat-い</b> caranya sama sekali berbeda: い diganti <span class='gd-jp'>かった</span> lalu ditambah です. Sama-sama membicarakan hotel yang kamu inapi kemarin:<br><span class='gd-jp'>ホテルは静かでした。</span>(Hotelnya tenang: kata sifat-な)<br><span class='gd-jp'>ホテルは高かったです。</span>(Hotelnya mahal: kata sifat-い)<br>Sebaliknya, kata sifat-い juga tidak boleh diberi でした: tidak bisa bilang「高いでした」.</div><div class='gd-sec'><b>になりました</b> artinya “<b>menjadi</b> ～”, yang dibicarakan adalah perubahan, bukan sekadar keadaan di masa lalu:<br><span class='gd-jp'>町は静かでした。</span>(Waktu itu kota ini tenang)<br><span class='gd-jp'>町は静かになりました。</span>(Kota ini jadi tenang: sebelumnya tidak tenang)</div><div class='gd-warn'>Trik cepat: pertama cek dulu apakah itu kata sifat-な; kalau iya, “buang な + でした”. Kalau kamu mau bilang “jadi ～”, pakai <span class='gd-jp'>になりました</span>.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Selanjutnya lihat bentuk lampau kata sifat-い <span class='gd-jp'>〜かったです</span>. Kalau keduanya dilatih bersama, kamu tidak akan tertukar lagi.</div>","n5-8":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Pola ini dipakai untuk bilang \"tadinya terasa bagaimana\", misalnya 「kemarin <b>dingin</b>」 atau 「ramennya <b>enak</b>」. Dalam bahasa Indonesia, kamu cukup menambah kata \"kemarin\". Di bahasa Jepang, い形容詞 (kata sifat yang berakhiran 「い」, seperti <span class='gd-jp'>暑い</span> dan <span class='gd-jp'>おいしい</span>) harus <b>berubah bentuk</b>: <span class='gd-pair'><span class='gd-jp'>暑いです</span> → <span class='gd-jp'>暑かったです</span></span>.</div><div class='gd-h'>Cara mengubahnya</div><div class='gd-sec'><span class='gd-tag'>Lampau・Positif</span>Buang 「い」 di akhir, lalu tambahkan 「かったです」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → buang い → <span class='gd-jp'>暑かったです</span></span><br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしかったです</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は寒かったです。</span>(Kemarin dingin.)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしかったです。</span>(Ramen ini enak.)</div><div class='gd-sec'><span class='gd-tag'>Lampau・Negatif</span>Ganti 「い」 dengan 「く」, lalu tambahkan 「なかったです」.<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → ganti い dengan く → <span class='gd-jp'>難しくなかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>テストは難しくなかったです。</span>(Ujiannya tidak sulit.)</div><div class='gd-sec'>Ada juga cara lain, yaitu <span class='gd-jp'>難しくありませんでした</span>. Artinya sama, hanya terdengar lebih formal. Dua-duanya benar.</div><div class='gd-sec'><span class='gd-tag'>Satu yang istimewa</span><span class='gd-jp'>いい</span> (bagus) harus dikembalikan dulu ke <span class='gd-jp'>よい</span> sebelum berubah. Langsung hafalkan saja:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかったです</span></span> (bagus), <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくなかったです</span></span> (tidak bagus)</div><div class='gd-ex-line'>・<span class='gd-jp'>天気はよくなかったです。</span>(Cuacanya kurang bagus.)</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'>Temanmu baru pulang liburan, lalu kamu menanyakan kesannya. Tanya-jawabnya seperti ini:</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行はどうでしたか。</span>(Liburannya bagaimana?)</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(Seru banget.)</div><div class='gd-sec'>Pertanyaannya memakai <span class='gd-jp'>でした</span>, tetapi jawabannya <span class='gd-jp'>楽しかったです</span>. Jangan terbawa pertanyaan sampai menjawab 「楽しいでした」.</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・<b>Tidak boleh</b> bilang <span class='gd-jp'>暑いでした</span>. Bentuk lampau い形容詞 memakai 「かった」, bukan ditambah でした.<br>・Jangan juga bilang <span class='gd-jp'>暑かったでした</span>. 「かった」 sudah bentuk lampau. です di belakangnya hanya membuat kalimat jadi sopan, jadi tidak perlu diubah jadi でした.<br>・Di tengah 「かった」 ada っ kecil yang harus ditahan satu ketukan: あつ<b>か</b>っ<b>た</b>. Kalau dibaca 「あつかた」, kedengarannya aneh.<br>・<span class='gd-jp'>いい</span> tidak bisa jadi 「いかったです」 atau 「いくなかったです」. Perubahannya selalu dimulai dari <span class='gd-jp'>よ</span>.<br>・<span class='gd-jp'>きれい</span> dan <span class='gd-jp'>有名</span> memang berbunyi 「い」 di akhir, tetapi keduanya な形容詞. Jadi tidak bisa jadi 「きれかったです」, melainkan <span class='gd-jp'>きれいでした</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bercerita tentang \"liburan minggu lalu\":<br><b>い形容詞</b>: <span class='gd-jp'>ホテルは高かったです。</span> (Hotelnya mahal.)<br><b>な形容詞</b>: <span class='gd-jp'>ホテルはきれいでした。</span> (Hotelnya bagus dan bersih.)<br><b>Kata benda</b>: <span class='gd-jp'>天気は雨でした。</span> (Cuacanya hujan.)<br>い形容詞 berubah sendiri menjadi 「かった」, sedangkan な形容詞 dan kata benda mengganti です dengan でした.</div><div class='gd-warn'>Trik cepat: lihat dulu di kamus, apakah kata itu い形容詞 yang berakhiran 「い」. Kalau ya, pakai 「〜かったです」. Kalau bukan (seperti きれい, 元気, 雨), pakai 「〜でした」.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kalau です dibuang, jadilah bentuk santai antarteman: <span class='gd-jp'>昨日、寒かった。</span> (Kemarin dingin banget.) Kamu juga bisa lanjut belajar 「〜くなります」 untuk bilang \"menjadi ~\": <span class='gd-jp'>寒くなりました。</span> (Jadi dingin.)</div>","n5-9":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ませんか」 artinya <b>\"Mau ~ bareng, nggak?\"</b>. Secara harfiah memang terlihat seperti \"Tidak ~kah?\". Tetapi saat mengajak, orang Jepang memakainya untuk bertanya dengan sopan: \"Kamu bersedia ~?\" Keputusan diserahkan ke lawan bicara, jadi lebih mudah ditolak dan terdengar sangat sopan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengajak</span>Mengajak orang pergi ke suatu tempat atau melakukan sesuatu bersama.</div><div class='gd-ex-line'>・<span class='gd-jp'>今度の日曜日、山登りに行きませんか。</span>(Hari Minggu ini mau naik gunung bareng?)</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に昼ご飯を食べませんか。</span>(Mau makan siang bareng?)</div><div class='gd-sec'><span class='gd-tag'>Menawarkan makanan/minuman, memberi saran</span>Pola ini juga sering dipakai untuk menawarkan makanan atau minuman, atau menyarankan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、食べませんか。</span>(Mau kue ini?)</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休みませんか。</span>(Istirahat sebentar, yuk?)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます dulu, lalu ganti 「ます」 dengan 「<b>ませんか</b>」.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きませんか</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べませんか</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しませんか</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ませんか</span>（きませんか）</span><br>Sebenarnya ini 「ません」 (tidak ~) ditambah 「か」 penanda pertanyaan.</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>〜でも〜ませんか</span>Menambahkan 「でも」 setelah kata benda berarti \"~ atau semacamnya\", sehingga ajakannya lebih santai dan tidak menekan.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーでも飲みませんか。</span>(Mau minum kopi atau apa gitu?)</div><div class='gd-sec'><span class='gd-tag'>Cara menjawab</span>Menerima: <span class='gd-jp'>いいですね。</span> (Boleh, tuh.), <span class='gd-jp'>ぜひ。</span> (Pasti mau!)<br>Menolak: <span class='gd-jp'>すみません、その日はちょっと…。</span> (Maaf, hari itu agak...)</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Jangan tertipu arti harfiahnya. Saat mengajak, <span class='gd-jp'>行きませんか</span> artinya \"Mau pergi?\", bukan \"Kamu tidak pergi?\".<br>・Kalau menolak dengan langsung bilang <span class='gd-jp'>いいえ、行きません。</span> (Tidak, aku tidak pergi.), kesannya sangat kaku dan menyakitkan. Orang Jepang biasa bilang 「<span class='gd-jp'>ちょっと…</span>」 dengan kalimat menggantung, dan lawan bicara pun paham.<br>・Untuk bilang \"Mau <b>aku</b> bantu ~?\", jangan pakai ませんか. <span class='gd-jp'>持ちませんか</span> berarti meminta lawan bicara yang membawa. Untuk \"Aku bawakan, ya?\", bilang <span class='gd-jp'>持ちましょうか</span>.<br>・Dengan teman dekat, tidak perlu sesopan itu. Pakai saja bentuk biasa dengan nada naik: <span class='gd-jp'>行かない？</span> (Mau pergi, nggak?)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Dalam situasi yang sama, coba lihat percakapan mengajak nonton film:<br><b>ませんか</b> = belum diputuskan, baru menanyakan keinginan lawan bicara: <span class='gd-jp'>一緒に映画を見ませんか。</span> (Mau nonton film bareng?)<br><b>ましょう</b> = sudah sepakat, atau dua-duanya memang mau, tinggal mendorong: <span class='gd-jp'>いいですね。見ましょう。</span> (Boleh, tuh. Ayo kita nonton.)<br><b>ましょうか</b> = menawarkan diri untuk membantu, \"Biar aku ~, ya?\": <span class='gd-jp'>チケット、買いましょうか。</span> (Tiketnya biar aku yang beli, ya?)</div><div class='gd-sec'>Jadi urutan yang paling umum: ajak dulu dengan 「ませんか」, lalu setelah lawan bicara setuju, putuskan bersama dengan 「ましょう」. Kalau langsung membuka dengan 「ましょう」, kesannya seperti memutuskan untuk orang lain tanpa bertanya.</div><div class='gd-warn'>Trik cepat: masih menanyakan \"mau atau tidak\" → ませんか. Sudah sepakat \"ya sudah, begitu saja\" → ましょう. Mau bilang \"biar aku bantu\" → ましょうか.</div>","n5-2":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜ます」adalah <b>bentuk sopan</b> dalam bahasa Jepang. Bentuk ini dipakai untuk guru, pelayan toko, dan orang yang baru kamu kenal. Dengan keluarga dan teman dekat, baru dipakai bentuk tanpa ます. Untuk bilang \"tidak (melakukan)\", ganti ます dengan <b>ません</b>. Saat baru mulai belajar, <b>pakai ます dulu adalah yang paling aman</b> dan tidak akan terdengar kurang sopan.</div><div class='gd-h'>Satu bentuk, untuk sekarang dan masa depan</div><div class='gd-sec'>Bahasa Jepang tidak punya \"bentuk masa depan\" tersendiri. Kebiasaan sehari-hari dan hal yang akan dilakukan sama-sama memakai 「〜ます」. Waktunya ditunjukkan lewat kata seperti 「毎日」「明日」「来週」.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日コーヒーを飲みます。</span>（Aku minum kopi setiap hari: kebiasaan）</div><div class='gd-ex-line'>・<span class='gd-jp'>来週、京都へ行きます。</span>（Minggu depan aku akan pergi ke Kyoto: masa depan）</div><div class='gd-ex-line'>・<span class='gd-jp'>田村先生はお酒を飲みません。</span>（Guru Tamura tidak minum alkohol）</div><div class='gd-h'>Cara mengubahnya: lihat dulu verbanya golongan mana</div><div class='gd-sec'><b>Golongan 1 (verba godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「い」 yang sama, lalu tambahkan ます.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む diganti み → <span class='gd-jp'>飲みます</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きます</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買います</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>Golongan 2 (verba ichidan)</b>: buang 「る」 di akhir, lalu tambahkan ます.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>Kata berpola \"nomina＋する\" seperti 「勉強する」「出張する」 juga sama: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'>Untuk bentuk negatif, cukup ganti ます dengan ません. Aturannya sama untuk ketiga golongan: <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べません</span></span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span> kelihatannya seperti golongan 2, padahal golongan 1. Bentuknya <span class='gd-jp'>帰ります</span>, bukan 帰ます.<br>・「ません」artinya \"tidak (melakukan)\", bukan \"tidak bisa\". <span class='gd-jp'>お酒を飲みません</span> artinya \"aku tidak minum alkohol\", bukan \"aku tidak bisa minum\".<br>・ます hanya bisa menempel pada <b>verba</b>. Untuk bilang \"aku mahasiswa\", pakai <span class='gd-jp'>学生です</span>, bukan 学生ます.<br>・Bunyi 「す」 pada ます biasanya dilafalkan sangat ringan, jadi terdengar seperti \"mas\". Kalau kamu mendengarnya begitu, tidak perlu ragu pada telingamu.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Dalam bahasa Indonesia, \"aku makan\" bisa berarti kebiasaan, rencana, atau sedang makan. Di bahasa Jepang, ます menyatakan <b>kebiasaan</b> atau <b>hal yang akan dilakukan</b>. Untuk \"sedang melakukan\", pakai <b>ています</b>.<br><span class='gd-jp'>今、ご飯を食べます。</span>（Sekarang aku mau makan: belum mulai makan）<br><span class='gd-jp'>今、ご飯を食べています。</span>（Sekarang aku sedang makan: sudah mulai makan）</div><div class='gd-warn'>Tips menentukan: kalau belum mulai atau dilakukan setiap hari, pakai ます. Kalau sedang dikerjakan saat ini, pakai ています.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Untuk menceritakan hal yang sudah lalu: <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span> (sudah minum), <span class='gd-pair'><span class='gd-jp'>飲みません</span> → <span class='gd-jp'>飲みませんでした</span></span> (tidak minum).<br>Kalau mau mengajak orang, lanjut pelajari <span class='gd-jp'>〜ませんか</span> dan <span class='gd-jp'>〜ましょう</span>.</div>","n5-3":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Kata sifat seperti <span class='gd-jp'>静か</span> (tenang), <span class='gd-jp'>きれい</span> (cantik/bersih), dan <span class='gd-jp'>親切</span> (ramah/baik hati) disebut <b>adjektiva-な</b> dalam bahasa Jepang. Untuk bilang \"tenang\", pakai <span class='gd-jp'>静かです</span>. Untuk \"tidak tenang\", pakai <span class='gd-jp'>静かじゃありません</span>. Cara pakainya hampir sama dengan kalimat nomina, hanya ada satu aturan tambahan: <b>kalau diletakkan langsung di depan nomina, harus ditambah 「な」</b>.</div><div class='gd-h'>Apa itu adjektiva-な?</div><div class='gd-sec'>Ini adalah kata-kata untuk menggambarkan keadaan atau perasaan, yang biasanya diterjemahkan sebagai kata sifat biasa dalam bahasa Indonesia. Disebut \"adjektiva-な\" karena saat bertemu nomina, kata ini mendapat tambahan な. 「語幹」 yang tertulis di kartu adalah bentuk aslinya seperti yang tertulis di daftar kosakata, misalnya <span class='gd-jp'>静か</span>, tanpa tambahan apa pun.<br>Hafalkan dulu yang paling sering dipakai ini:<br><span class='gd-jp'>静か</span> (tenang), <span class='gd-jp'>きれい</span> (cantik, bersih), <span class='gd-jp'>元気</span> (sehat, bersemangat), <span class='gd-jp'>有名</span> (terkenal), <span class='gd-jp'>便利</span> (praktis), <span class='gd-jp'>暇</span> (senggang), <span class='gd-jp'>大変</span> (berat, repot), <span class='gd-jp'>好き</span> (suka), <span class='gd-jp'>嫌い</span> (tidak suka), <span class='gd-jp'>上手</span> (pandai)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Positif</span>Bentuk aslinya langsung ditambah <span class='gd-jp'>です</span>.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この喫茶店は静かです。</span>（Kafe ini tenang）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くは便利です。</span>（Sekitar stasiun itu praktis）</div><div class='gd-sec'><span class='gd-tag'>Negatif</span>Bentuk aslinya langsung ditambah <span class='gd-jp'>じゃありません</span>. Kata di depannya sama sekali tidak perlu diubah.<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇じゃありません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暇じゃありません。</span>（Hari ini aku tidak senggang）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は有名じゃありません。</span>（Kota kecil ini tidak terkenal）</div><div class='gd-sec'>Bentuk negatif punya dua cara lain dengan arti yang sama. <span class='gd-jp'>ではありません</span> lebih formal dan sering muncul di buku pelajaran dan tulisan. <span class='gd-jp'>じゃないです</span> lebih santai, tapi tetap sopan.</div><div class='gd-sec'><span class='gd-tag'>Bertanya</span>Cukup tambahkan <span class='gd-jp'>か</span> di belakang.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変ですか。</span>（Apakah pekerjaannya berat?）</div><div class='gd-h'>Di depan nomina: tambahkan な</div><div class='gd-sec'>Untuk bilang \"kota kecil yang tenang\" atau \"orang yang ramah\", sisipkan <span class='gd-jp'>な</span> di tengah. Kamu bisa menganggapnya seperti kata \"yang\" dalam bahasa Indonesia.<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋<span class='gd-jp'>町</span> → <span class='gd-jp'>静かな町</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かな町です。</span>（Ini kota kecil yang tenang）</div><div class='gd-ex-line'>・<span class='gd-jp'>京都はきれいな所です。</span>（Kyoto adalah tempat yang indah）</div><div class='gd-ex-line'>・<span class='gd-jp'>親切な人ですね。</span>（Orangnya ramah sekali ya）</div><div class='gd-sec'>Cara mengingatnya mudah: <b>kalau diikuti です, tanpa な. Kalau diikuti nomina, baru pakai な</b>.</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span> dan <span class='gd-jp'>嫌い</span> berakhiran 「い」 sehingga kelihatan seperti adjektiva-い, padahal adjektiva-な. Negatifnya <span class='gd-jp'>きれいじゃありません</span>, bukan 「きれくないです」.<br>・Jangan tambahkan な sebelum です: yang benar <span class='gd-jp'>静かです</span>, bukan 「静かなです」.<br>・Di depan nomina, な tidak boleh hilang, dan jangan diganti の: yang benar <span class='gd-jp'>静かな町</span>, bukan 「静か町」 dan bukan 「静かの町」.<br>・Objek dari <span class='gd-jp'>好き</span> dan <span class='gd-jp'>嫌い</span> memakai <b>が</b>: <span class='gd-jp'>猫が好きです</span> (aku suka kucing). \"Suka kucing\" dalam bahasa Indonesia terasa seperti verba plus objek, jadi banyak yang menulis 「猫を好きです」. Untuk pemula, ingat saja: pakai が.<br>・Langsung bilang 「嫌いです」 terdengar agak keras. Orang Jepang sering memakai <span class='gd-jp'>あまり好きじゃありません</span> (kurang suka), yang terdengar jauh lebih lembut.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Saat membicarakan \"toko ini\", bentuk negatif ketiga jenis kata ini berbeda:<br><b>Adjektiva-い</b>: い di akhir berubah menjadi くない.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くないです。</span>（Toko ini tidak murah）</div><div class='gd-sec'><b>Adjektiva-な</b>: badan katanya tidak berubah, lalu disambung じゃありません.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店はきれいじゃありません。</span>（Toko ini tidak bersih）</div><div class='gd-sec'><b>Nomina</b>: sama seperti adjektiva-な, disambung じゃありません.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここは銀行じゃありません。</span>（Ini bukan bank）</div><div class='gd-warn'>Tips menentukan: saat menghafal kosakata, hafalkan sekalian dengan な, misalnya <span class='gd-jp'>きれいな</span> dan <span class='gd-jp'>静かな</span>. Kata yang bisa menjadi pola 「～な＋nomina」 cukup ditambah じゃありません untuk negatifnya. Hanya adjektiva-い yang mengubah い menjadi くない.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Untuk bentuk lampau, ganti です dengan でした: <span class='gd-jp'>昨日は暇でした。</span> (Kemarin aku senggang)</div>","n5-12":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ましょう」itu setara dengan <b>「Ayo ～」</b> dalam bahasa Indonesia. Misalnya kamu mengajak teman sekelas: \"Ayo pergi\" atau \"Ayo istirahat sebentar\". Dalam bahasa Jepang jadinya <span class='gd-jp'>行きましょう</span> dan <span class='gd-jp'>休みましょう</span>. Ini bentuk sopan, jadi boleh dipakai ke guru, rekan kerja, atau orang yang baru kamu kenal.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu kata kerjanya ke bentuk「〜ます」, lalu <b>ganti ます dengan ましょう</b>. Beres. Kamu tidak perlu peduli kata kerjanya termasuk golongan mana.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きましょう</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べましょう</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しましょう</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ましょう</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengajak bersama</span>Dipakai saat kalian mau melakukan sesuatu bersama-sama. Sering berpasangan dengan <span class='gd-jp'>一緒に</span> (bersama).</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に帰りましょう。</span>(Ayo pulang bareng)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休みましょう。</span>(Ayo istirahat sebentar)</div><div class='gd-sec'><span class='gd-tag'>Memimpin untuk memulai</span>Sering diucapkan guru yang membuka kelas atau orang yang memimpin rapat.</div><div class='gd-ex-line'>・<span class='gd-jp'>じゃあ、始めましょう。</span>(Kalau begitu, ayo kita mulai)</div><div class='gd-h'>Ditambah か di belakang: ましょうか</div><div class='gd-sec'><span class='gd-tag'>Biar aku bantu?</span>Menawarkan diri untuk membantu orang lain. Terdengar perhatian.</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物を持ちましょうか。</span>(Mau saya bawakan barangnya?)</div><div class='gd-sec'><span class='gd-tag'>Berunding bersama</span>Kalian sudah sepakat melakukan sesuatu bersama, lalu menanyakan detailnya. Di depannya sering ada「何」「どこ」「何時」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何時に会いましょうか。</span>(Kita bertemu jam berapa?)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・ます harus <b>diganti</b>, bukan ditambahkan di belakang. Yang benar <span class='gd-jp'>行きましょう</span>, bukan「行きますましょう」.<br>・「ましょう」dibaca panjang, <b>ましょー</b>. Jangan dibaca pendek seperti「ましょ」.<br>・Artinya <b>sudah termasuk dirimu sendiri</b>. Ini bukan menyuruh lawan bicara pergi sendiri. Kalau mau bilang \"tolong kamu pergi ke ～\", pakai「〜てください」. Tulisan di jalan seperti <span class='gd-jp'>ゴミは持ち帰りましょう</span> (Mari bawa pulang sampahnya) adalah pemakaian khusus yang lebih lembut. Saat bicara sendiri, jangan dipakai dulu.<br>・Saat pertama kali mengajak seseorang dan kamu belum tahu dia mau atau tidak, langsung bilang「行きましょう」terdengar seperti kamu sudah memutuskan untuknya. Lebih sopan tanya dulu dengan「〜ませんか」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Pakai situasi yang sama, yaitu mengajak nonton film. Ketiga bentuk ini sering muncul berurutan:<br><b>ませんか</b>＝bertanya dulu apakah dia mau: <span class='gd-jp'>映画を見ませんか。</span>(Mau nonton film bareng?)<br><b>ましょう</b>＝sudah setuju, lanjut bersama: <span class='gd-jp'>ええ、見ましょう。</span>(Iya, ayo kita nonton)<br><b>ましょうか</b>＝menanyakan pendapat: <span class='gd-jp'>何を見ましょうか。</span>(Mau nonton yang mana?)</div><div class='gd-warn'>Tips menentukan: kalau lawan bicara belum setuju, pakai「ませんか」. Kalau sudah sepakat dan mau melakukannya bersama, pakai「ましょう」. Kalau mau menanyakan pendapat atau menawarkan bantuan, pakai「ましょうか」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ke teman dekat tidak perlu seformal ini. Kamu bisa pakai bentuk yang lebih santai: <span class='gd-pair'><span class='gd-jp'>行きましょう</span> → <span class='gd-jp'>行こう</span></span>. Ini akan diajarkan di N4 sebagai「意向形」.</div>","n5-13":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Satu kalimat dalam bahasa Jepang bisa diucapkan dengan dua gaya. <b>Bentuk sopan (丁寧体)</b> adalah <b>versi sopan</b> yang memakai「です・ます」. <b>Bentuk biasa (普通体)</b> adalah <b>versi teman</b> tanpa です・ます. Artinya sama persis, hanya nadanya yang beda. Mirip seperti saat kamu menulis pesan ke atasan, \"Baik, saya akan datang besok\", tapi ke teman cukup membalas, \"Oke, besok datang\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bentuk sopan</span>Untuk guru, atasan, pelayan toko, pelanggan, orang yang baru pertama kali bertemu, dan orang yang lebih tua tapi belum akrab. Kalau bingung mau pakai yang mana, bentuk sopan pasti aman.</div><div class='gd-sec'><span class='gd-tag'>Bentuk biasa</span>Untuk keluarga, sahabat, teman sekelas, dan orang yang lebih muda. Kalau menulis buku harian, bicara sendiri, atau mencatat untuk diri sendiri, kamu juga pakai bentuk biasa karena tidak ada lawan bicara yang perlu dihormati.</div><div class='gd-h'>Satu kalimat, dua gaya</div><div class='gd-sec'>Misalnya mau bertanya \"Besok pergi nggak?\"</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行きますか。</span>(Apakah Anda akan pergi besok? : ke guru)</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、行きます。</span>(Ya, saya akan pergi)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行く？</span>(Besok pergi nggak? : ke teman)</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、行く。</span>(Iya, pergi)</div><div class='gd-sec'>Perhatikan kalimat tanya versi teman: <b>か di akhir kalimat hilang, diganti nada naik</b>. Jawaban「はい」juga berubah jadi「うん」.</div><div class='gd-h'>Cara mengubah: dari versi sopan ke versi teman</div><div class='gd-sec'><b>Kata benda dan kata sifat-na</b>: ganti です dengan だ.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かだ</span></span><br>Bentuk negatif dan lampau ikut berubah:<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><span class='gd-pair'><span class='gd-jp'>学生でした</span> → <span class='gd-jp'>学生だった</span></span></div><div class='gd-sec'><b>Kata sifat-i</b>: cukup buang です, <b>jangan tambah だ</b>.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高い</span></span><span class='gd-pair'><span class='gd-jp'>高くないです</span> → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span></div><div class='gd-sec'><b>Kata kerja</b>: kembalikan bentuk ます ke bentuk kamus (辞書形), yaitu bentuk yang kamu temukan di kamus.<br>Golongan 1 (kata kerja godan): bunyi sebelum ます diganti dengan bunyi di kolom「う」pada baris yang sama.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → き diganti く → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲む</span></span><br>Golongan 2 (kata kerja ichidan): buang ます, tambah る.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br>Golongan 3 (する・来る): langsung hafalkan.<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span><br>Contoh umum lainnya: <span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>読んでいます</span> → <span class='gd-jp'>読んでいる</span></span><br>Cara mengubah bentuk negatif dan lampau secara lengkap akan diajarkan selangkah demi selangkah di pelajaran「辞書形・ない形」dan「た形」.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-i tidak pakai だ. Cukup bilang <span class='gd-jp'>高い</span>. 「高いだ」itu salah.<br>・Saat ngobrol dengan teman, kalau cuma bilang「<span class='gd-jp'>雨だ。</span>」terdengar kaku, seperti bicara sendiri atau mengumumkan sesuatu. Biasanya ditambah よ atau ね: <span class='gd-jp'>明日、雨だよ。</span>(Besok hujan lho)<br>・Pada kalimat tanya bentuk biasa untuk kata benda dan kata sifat-na, だ dibuang: <span class='gd-jp'>学生？</span>(Kamu pelajar?). Jangan bilang「学生だ？」.<br>・Bentuk biasa itu bukan \"tidak sopan\", tapi \"sudah akrab\". Kalau dipakai ke guru, itu tidak sopan. Sebaliknya, kalau ke sahabat kamu terus-terusan pakai です・ます, dia bisa merasa kamu menjaga jarak, bahkan seperti sedang marah.<br>・Untuk lawan bicara yang sama, pemula sebaiknya pilih satu gaya dulu. Jangan campur satu kalimat ます, satu kalimat bentuk biasa, karena terdengar berantakan.<br>・<span class='gd-jp'>読んでいる</span>dalam percakapan sering dipersingkat jadi <span class='gd-jp'>読んでる</span>. Kalau mendengarnya, ketahuilah artinya sama.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk biasa tidak hanya dipakai saat ngobrol. Banyak pola tata bahasa yang wajib disambung dengan bentuk biasa, walaupun kalimat keseluruhannya sopan: <span class='gd-jp'>明日は雨だと思います。</span>(Saya rasa besok akan hujan)<br>Langkah berikutnya, lihat「Rangkuman Bentuk Biasa」. Di sana kamu bisa melihat bentuk sekarang, lampau, positif, dan negatif tiap jenis kata sekaligus.</div>","n5-21":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「で」setelah kendaraan artinya <b>「naik ~」「pakai ~」「mengendarai ~」</b>. Dalam bahasa Indonesia kata kerjanya bisa berganti-ganti (naik, mengendarai, menyetir), tapi dalam bahasa Jepang kamu naik apa pun polanya sama: 「kendaraan＋で」, lalu lanjutkan dengan <span class='gd-jp'>行きます</span>、<span class='gd-jp'>来ます</span>、<span class='gd-jp'>帰ります</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kendaraan＋で＋行きます／来ます／帰ります. Taruh saja kata bendanya di depan, tidak perlu diubah bentuknya.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で会社に行きます。</span>（Aku pergi ke kantor naik kereta）</div><div class='gd-ex-line'>・<span class='gd-jp'>自転車で学校へ行きます。</span>（Aku pergi ke sekolah naik sepeda）</div><div class='gd-ex-line'>・<span class='gd-jp'>バスで帰ります。</span>（Aku pulang naik bus）</div><div class='gd-ex-line'>・<span class='gd-jp'>飛行機で来ました。</span>（Aku datang naik pesawat）</div><div class='gd-sec'>Kamu akan sadar: 「naik」, 「pakai」, dan 「mengendarai」 dalam bahasa Indonesia semuanya diwakili oleh satu 「で」 saja. <span class='gd-jp'>車で行きます</span> juga begitu. Bisa berarti kamu menyetir sendiri, bisa juga menumpang mobil orang lain, bahasa Jepang tidak membedakannya.</div><div class='gd-h'>Mau tanya「datang dengan apa?」</div><div class='gd-sec'>Ganti kendaraannya dengan 「何」, selesai:</div><div class='gd-ex-line'>・<span class='gd-jp'>何で来ましたか。</span>（Kamu datang naik apa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>タクシーで来ました。</span>（Aku datang naik taksi）</div><div class='gd-sec'>「何で」di sini dibaca <b>なにで</b>. Kalau dibaca なんで, gampang terdengar seperti 「Kenapa datang?」.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Jalan kaki tidak pakai で</b>. Jangan bilang 「足で行きます」, tapi <span class='gd-jp'>歩いて行きます</span> (pergi dengan jalan kaki). Hafalkan saja seluruh kalimat ini dulu.<br>・Tindakan 「naik ke bus」 memakai 「に」: <span class='gd-jp'>バスに乗ります</span> (naik bus). Banyak yang bilang 「バスで乗ります」, dan itu salah.<br>・Urutannya boleh ditukar: <span class='gd-jp'>電車で東京へ行きます</span> dan <span class='gd-jp'>東京へ電車で行きます</span> sama-sama benar, asalkan 「で」 menempel tepat setelah kendaraannya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>で（kendaraan）</b>＝memakai apa untuk 「bergerak」: <span class='gd-jp'>バスで駅へ行きます。</span>（Aku pergi ke stasiun naik bus）<br><b>に＋乗ります</b>＝「naik ke」 kendaraan mana: <span class='gd-jp'>駅でバスに乗ります。</span>（Aku naik bus di stasiun）<br><b>で（tempat kegiatan）</b>＝di mana melakukan sesuatu: <span class='gd-jp'>駅で</span> pada kalimat di atas artinya 「di stasiun」. Yang ada di depannya adalah tempat, bukan kendaraan.</div><div class='gd-warn'>Trik membedakan: kalau setelahnya 「pergi, datang, pulang」, kendaraan diikuti で. Kalau setelahnya 「乗ります」, pakai に. Kalau yang di depan adalah tempat, bukan kendaraan, で itu berarti 「di ~」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>「で」ini sebenarnya berarti 「pakai ~ / dengan ~」. Bukan cuma kendaraan, makan pakai sumpit atau bicara pakai bahasa Jepang juga memakainya: <span class='gd-jp'>はしで食べます。</span>（makan pakai sumpit）. Inilah topik kartu berikutnya, 「partikel で (cara・alat)」.</div>","n5-22":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「と」artinya <b>「dengan ~」「bersama ~」</b>. Mau bilang 「Aku nonton film dengan temanku」, tambahkan と setelah 「teman」: <span class='gd-jp'>友達と映画を見ます</span>. Yang ada di depan と adalah <b>orang yang melakukan hal itu bersamamu</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang: <b>orang＋と＋hal yang dilakukan</b>. Kalau mau menekankan 「bersama」, tambahkan <span class='gd-jp'>一緒に</span> (bersama-sama) setelah と. Artinya sama, hanya terasa lebih jelas kebersamaannya.<br><span class='gd-pair'><span class='gd-jp'>友達と</span> → <span class='gd-jp'>友達と一緒に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>友達と映画を見ました。</span>（Aku nonton film dengan temanku）</div><div class='gd-ex-line'>・<span class='gd-jp'>母と一緒に料理を作ります。</span>（Aku memasak bersama ibuku）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、犬と散歩します。</span>（Setiap pagi aku jalan-jalan dengan anjingku）</div><div class='gd-sec'>Untuk bertanya 「dengan siapa」 pakai <span class='gd-jp'>誰と</span>, dan jawabannya cukup 「orang＋とです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰と行きますか。</span>（Kamu pergi dengan siapa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達とです。</span>（Dengan temanku）</div><div class='gd-sec'>Kalau 「aku」 juga mau disebut, pelakunya pakai は, orang yang menemani pakai と: <span class='gd-jp'>私は友達と京都へ行きます。</span>（Aku pergi ke Kyoto dengan temanku）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kalau melakukannya sendirian, bilang <span class='gd-jp'>一人で</span>, bukan 一人と. Untuk jumlah orang atau satu kelompok juga pakai で: <span class='gd-jp'>二人で</span>、<span class='gd-jp'>家族で</span>、<span class='gd-jp'>みんなで</span>.<br>・一緒に itu pemeran pendukung, boleh dipakai boleh tidak. と saja sudah berarti 「bersama siapa」. Sebaliknya, kalau hanya bilang 一緒に tanpa menyebut siapa, itu karena lawan bicaranya sudah jelas: <span class='gd-jp'>一緒に帰りましょう。</span>（Ayo pulang bersama）<br>・Hal yang pasti butuh dua orang seperti <span class='gd-jp'>結婚する</span> juga memakai と, dan biasanya tanpa 一緒に: <span class='gd-jp'>田中さんと結婚しました。</span>（Aku menikah dengan Pak Tanaka）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>と punya satu fungsi lain: menghubungkan dua benda, seperti 「A dan B」 (penyebutan berjajar). Lihat dua kalimat ini:<br><span class='gd-jp'>母とケーキを食べました。</span>（Aku makan kue dengan ibuku）→ ibu adalah <b>orang yang makan bersamamu</b><br><span class='gd-jp'>パンとケーキを食べました。</span>（Aku makan roti dan kue）→ roti dan kue sama-sama <b>benda yang dimakan</b></div><div class='gd-warn'>Trik membedakan: kalau di depan と adalah 「orang yang ikut melakukan」, itulah 「bersama siapa」 yang kita pelajari di sini. Kalau di depan dan belakang と ada dua benda yang berjajar, artinya 「A dan B」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Dengan 「〜ませんか」 kamu bisa mengajak orang: <span class='gd-jp'>週末、私と映画を見ませんか。</span>（Akhir pekan nanti mau nonton film denganku?）</div>","n5-19":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「に」ditaruh setelah kata waktu, artinya seperti「<b>pada</b>」jam 7 atau「<b>pada</b>」bulan Maret: ia \"memaku\" kejadian di satu titik waktu. Dalam bahasa Indonesia, \"pada\" sering dilesapkan, misalnya \"Saya bangun jam 7\". Tapi dalam bahasa Jepang, kalau ada <b>waktu berangka</b>, kamu harus menambahkan に: <span class='gd-jp'>7時に起きます。</span>(Saya bangun jam 7)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cukup tambahkan に langsung setelah kata waktu.<br><span class='gd-pair'><span class='gd-jp'>7時</span> → <span class='gd-jp'>7時に</span></span><span class='gd-pair'><span class='gd-jp'>3月</span> → <span class='gd-jp'>3月に</span></span><span class='gd-pair'><span class='gd-jp'>2025年</span> → <span class='gd-jp'>2025年に</span></span></div><div class='gd-h'>Kapan pakai に, kapan tidak</div><div class='gd-sec'>Inilah bagian terpenting dari tata bahasa ini. Kata waktu terbagi jadi tiga jenis:</div><div class='gd-sec'><span class='gd-tag'>Wajib pakai</span>Waktu berangka: jam, menit, bulan, tahun, tanggal.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝6時に散歩します。</span>(Jam 6 pagi saya jalan-jalan)</div><div class='gd-ex-line'>・<span class='gd-jp'>3月に日本へ行きます。</span>(Bulan Maret saya akan pergi ke Jepang)</div><div class='gd-sec'>Hari khusus yang jelas, walaupun tanpa angka, juga pakai に, misalnya <span class='gd-jp'>誕生日</span>, <span class='gd-jp'>クリスマス</span>, <span class='gd-jp'>夏休み</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日にケーキを食べます。</span>(Di hari ulang tahun, saya makan kue)</div><div class='gd-sec'><span class='gd-tag'>Boleh pakai, boleh tidak</span>Nama hari. Kalau ditambah に jadi lebih jelas, jadi untuk pemula <b>paling aman ditambahkan saja</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>金曜日に歓迎会があります。</span>(Hari Jumat ada acara penyambutan)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日に休みます。</span>(Hari Minggu saya libur)</div><div class='gd-sec'><span class='gd-tag'>Tidak boleh pakai</span>① Waktu yang patokannya \"sekarang\": <span class='gd-jp'>今日</span>, <span class='gd-jp'>明日</span>, <span class='gd-jp'>昨日</span>, <span class='gd-jp'>今週</span>, <span class='gd-jp'>来年</span>, <span class='gd-jp'>今</span>.<br>Cara menilainya: kata seperti ini menunjuk hari yang berbeda kalau diucapkan hari ini dibanding minggu depan. Artinya ia ikut bergerak mengikuti \"sekarang\", jadi tidak pakai に.<br>② Waktu yang berarti \"setiap ～\": <span class='gd-jp'>毎日</span>, <span class='gd-jp'>毎朝</span>, <span class='gd-jp'>毎週</span>. Kata ini menyatakan kebiasaan yang berulang, bukan satu titik waktu, jadi juga tidak pakai に.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、映画を見ます。</span>(Besok saya akan menonton film)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝コーヒーを飲みます。</span>(Setiap pagi saya minum kopi)</div><div class='gd-sec'>Dua jenis waktu juga sering muncul bersamaan:</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝7時に起きます。</span>(Setiap pagi saya bangun jam 7)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日の3時に会いましょう。</span>(Ayo bertemu besok jam 3)</div><div class='gd-warn'>Kalau satu kalimat punya dua jenis waktu, terapkan aturan masing-masing: waktu berpatokan \"sekarang\" (<span class='gd-jp'>明日</span>…) dan waktu \"setiap ～\" (<span class='gd-jp'>毎朝</span>…) tidak pakai に, sedangkan waktu berangka (<span class='gd-jp'>7時</span>, <span class='gd-jp'>3時</span>…) pakai に.</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Terbawa kebiasaan bahasa Indonesia dan melupakan に: \"7時起きます\" itu salah, yang benar <span class='gd-jp'>7時に起きます</span>.<br>・Sebaliknya, kebanyakan に: \"明日に行きます\" dan \"毎日に勉強します\" sama-sama salah. Setelah <span class='gd-jp'>明日</span> dan <span class='gd-jp'>毎日</span>, langsung sambung ke kata berikutnya.<br>・Saat bertanya waktu, <span class='gd-jp'>何時</span> pakai に, sedangkan <span class='gd-jp'>いつ</span> tidak: <span class='gd-jp'>何時に起きますか。</span>(Kamu bangun jam berapa?), <span class='gd-jp'>いつ日本へ行きますか。</span>(Kapan kamu pergi ke Jepang?)<br>・「時」dan「時間」itu beda: <span class='gd-jp'>2時に勉強します</span> artinya \"belajar jam dua\", sedangkan <span class='gd-jp'>2時間勉強します</span> artinya \"belajar selama dua jam\". Untuk <b>lamanya</b> waktu, tidak pakai に.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama \"jam 7\", tapi partikel di belakangnya mengubah arti:<br><b>に</b>＝tepat di titik waktu itu: <span class='gd-jp'>7時に起きます。</span>(Bangun jam 7)<br><b>から</b>＝mulai dari waktu itu dan berlanjut: <span class='gd-jp'>7時から勉強します。</span>(Belajar mulai jam 7)<br><b>まで</b>＝terus sampai waktu itu: <span class='gd-jp'>7時まで寝ます。</span>(Tidur sampai jam 7)</div><div class='gd-warn'>Tips cepat: dalam bahasa Indonesia, \"pada jam berapa\" pakai に, \"dari jam berapa\" pakai から, dan \"sampai jam berapa\" pakai まで.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Tugas に bukan cuma menandai waktu, ia juga bisa menandai letak sesuatu (n5-33 posisi keberadaan): <span class='gd-jp'>部屋に猫がいます。</span>(Di kamar ada kucing). Untuk に yang sama, lihat saja apakah kata di depannya waktu atau tempat.</div>","n5-20":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「へ」artinya <b>\"ke ～\" atau \"menuju ～\"</b>. Ditaruh setelah tempat untuk memberi tahu ke mana kamu bergerak: <span class='gd-jp'>日本へ行きます</span> artinya \"pergi menuju Jepang\", alias \"pergi ke Jepang\". Walaupun ditulis へ, sebagai partikel ia <b>dibaca「e」</b>, bukan「he」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tempat＋へ＋kata kerja gerak (seperti <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>).<br><span class='gd-pair'><span class='gd-jp'>学校</span> → <span class='gd-jp'>学校へ行きます</span></span>(pergi ke sekolah)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、京都へ行きます。</span>(Besok saya pergi ke Kyoto)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは去年日本へ来ました。</span>(Pak Tanaka datang ke Jepang tahun lalu)</div><div class='gd-ex-line'>・<span class='gd-jp'>6時にうちへ帰ります。</span>(Jam enam saya pulang ke rumah)</div><div class='gd-sec'>Untuk menanyakan tujuan orang lain, ganti tempatnya dengan <span class='gd-jp'>どこ</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、どこへ行きますか。</span>(Akhir pekan kamu mau pergi ke mana?)</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Cara baca: へ sebagai partikel dibaca「e」, sama seperti <span class='gd-jp'>は</span> sebagai partikel dibaca「wa」. Tapi <b>saat menulis, tetap tulis へ</b>, jangan え.<br>・Setelahnya harus kata kerja \"gerak\". Dalam bahasa Indonesia, \"belajar di perpustakaan\" memakai \"di\", sedangkan \"pergi ke perpustakaan\" memakai \"ke\". Sama seperti itu, tempat berlangsungnya kegiatan memakai <span class='gd-jp'>で</span>: <span class='gd-jp'>図書館で勉強します</span>, bukan <span class='gd-jp'>図書館へ勉強します</span>.<br>・Waktu tidak bisa memakai へ. Untuk \"pergi besok\" katakan <span class='gd-jp'>明日、行きます</span>, bukan 明日へ.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><span class='gd-tag'>へ dan に</span>Untuk \"pergi, datang, pulang\" ke suatu tempat, keduanya umumnya bisa saling menggantikan dengan arti yang sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>東京へ行きます。</span>(Pergi ke Tokyo)</div><div class='gd-ex-line'>・<span class='gd-jp'>東京に行きます。</span>(Pergi ke Tokyo)</div><div class='gd-sec'>Kalau harus dibedakan: <b>へ</b> terasa seperti \"menuju arah itu\", sedangkan <b>に</b> terasa seperti \"sampai di titik itu\". Dalam percakapan sehari-hari に lebih sering dipakai. Kalau yang ditekankan adalah \"tiba\", misalnya <span class='gd-jp'>着きます</span> (tiba), biasanya dipakai に:</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着きました。</span>(Sudah sampai di stasiun)</div><div class='gd-sec'><span class='gd-tag'>へ dan で</span>へ artinya \"pergi ke mana\", で artinya \"melakukan sesuatu di mana\".</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館へ行きます。</span>(Pergi ke perpustakaan)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館で勉強します。</span>(Belajar di perpustakaan)</div><div class='gd-warn'>Tips cepat: kalau di belakangnya ada kata kerja gerak seperti「行く、来る、帰る」, boleh pakai へ atau に; untuk \"melakukan sesuatu di suatu tempat\" pakai で. Waktu tidak bisa memakai へ: titik waktu konkret seperti 7時 atau 月曜日 pakai に, sedangkan kata waktu seperti 明日 dan 来週 tidak pakai partikel.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Dengan <span class='gd-jp'>から</span> (dari) dan <span class='gd-jp'>まで</span> (sampai), kamu bisa menyebutkan titik awal dan titik akhir perjalanan dengan lengkap. Lalu kalau belajar「で (alat transportasi)」, kamu bisa bilang <span class='gd-jp'>電車で会社へ行きます</span> (pergi ke kantor naik kereta).</div>","n5-17":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「の」menyambung <b>dua kata benda</b>. Kata di depan menjelaskan kata di belakang: <span class='gd-jp'>私の本</span>＝buku saya. Hati-hati, urutannya <b>kebalikan</b> dari bahasa Indonesia. Di bahasa Jepang, penjelasnya (「siapa punya」, 「dari mana」) disebut dulu, baru bendanya. Jadi 「saya の buku」, bukan 「buku saya」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda A＋の＋kata benda B＝「B-nya A」. B adalah tokoh utamanya, sedangkan A menjelaskan 「B yang mana」.<br><span class='gd-pair'><span class='gd-jp'>弟</span>＋<span class='gd-jp'>車</span> → <span class='gd-jp'>弟の車</span></span>（mobil adik）<br><span class='gd-pair'><span class='gd-jp'>数学</span>＋<span class='gd-jp'>教科書</span> → <span class='gd-jp'>数学の教科書</span></span>（buku pelajaran matematika）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Milik siapa</span>Menyatakan sebuah benda milik siapa.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の本です。</span>（Ini buku saya.）</div><div class='gd-sec'><span class='gd-tag'>Asal instansi</span>Menyatakan seseorang berasal dari perusahaan atau sekolah mana. Sering dipakai saat memperkenalkan diri dan menelepon.</div><div class='gd-ex-line'>・<span class='gd-jp'>さくら銀行の山田です。</span>（Saya Yamada dari Bank Sakura.）</div><div class='gd-sec'><span class='gd-tag'>Tentang apa</span>Menyatakan sebuah benda berkaitan dengan apa.</div><div class='gd-ex-line'>・<span class='gd-jp'>数学の教科書を忘れました。</span>（Saya lupa membawa buku pelajaran matematika.）</div><div class='gd-sec'><span class='gd-tag'>Dari mana</span>Menyatakan sebuah benda atau orang berasal dari mana, atau ada di mana.</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾のお茶はおいしいです。</span>（Teh Taiwan enak.）</div><div class='gd-h'>Kata benda di belakang bisa dihilangkan</div><div class='gd-sec'>Kalau semua orang sudah tahu yang dibicarakan, B boleh tidak disebut dan cukup 「A の」. <span class='gd-jp'>私の</span> berarti 「punya saya」.</div><div class='gd-ex-line'>・<span class='gd-jp'>「これは誰の傘ですか。」「私のです。」</span>（「Ini payung siapa?」「Punya saya.」）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Di bahasa Indonesia tidak ada kata penghubung, tapi di bahasa Jepang の tidak boleh dihilangkan.</b> Kita bilang 「ibu saya」, 「teman saya」, 「guru bahasa Jepang」 tanpa kata sambung apa pun. Bahasa Jepang harus bilang <span class='gd-jp'>私の母</span>, <span class='gd-jp'>私の友達</span>, <span class='gd-jp'>日本語の先生</span>. Kalau jadi 「私母」 atau 「日本語先生」, itu salah.<br>・<b>Kalau ada beberapa の berderet, tetap disambung semua.</b> 「Mobil teman saya」 di bahasa Indonesia tidak butuh kata sambung, tapi di bahasa Jepang dua-duanya harus ada: <span class='gd-jp'>私の友達の車</span>.<br>・<b>「Buku ini」 adalah <span class='gd-jp'>この本</span>, bukan 「これの本」.</b> <span class='gd-jp'>この</span> sendiri sudah berarti 「ini」, jadi langsung sambung ke kata benda tanpa の.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Di bahasa Indonesia, apa pun yang menerangkan benda tinggal ditaruh setelahnya: 「mobil Jepang」, 「mobil baru」, 「mobil bagus」. Di bahasa Jepang, kamu harus lihat jenis kata di depannya:<br><b>Kata benda</b> (orang, benda, tempat) pakai の: <span class='gd-jp'>日本の車</span>（mobil Jepang）<br><b>Kata sifat い</b> (seperti <span class='gd-jp'>新しい</span>, <span class='gd-jp'>おいしい</span>) langsung disambung tanpa の: <span class='gd-jp'>新しい車</span>（mobil baru）, bukan 「新しいの車」<br><b>Kata sifat な</b> (seperti <span class='gd-jp'>きれい</span>, <span class='gd-jp'>静か</span>) pakai な: <span class='gd-jp'>きれいな車</span>（mobil yang bagus/cantik）, bukan 「きれいの車」</div><div class='gd-warn'>Trik cepat: kalau di depannya kata benda seperti 「siapa, benda apa, tempat mana」, pakai の. Kalau di depannya kata sifat yang menggambarkan 「bagaimana」, jangan pakai の.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「の」punya peran lain: dipasang setelah kata kerja untuk mengubah sebuah kegiatan menjadi 「hal itu」, seperti <span class='gd-jp'>本を読むのが好きです。</span>（Saya suka membaca buku.）. Ini akan kamu pelajari nanti di 「の sebagai kata benda formal」, dan fungsinya berbeda dari の di pelajaran ini.</div>","n5-18":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「か」itu seperti <b>「apakah ...?」</b> dalam bahasa Jepang. Bedanya, か ditaruh di <b>akhir</b> kalimat. Dengan menambahkan か, kalimat pernyataan berubah jadi kalimat tanya: <span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですか</span></span>, dari 「(dia) mahasiswa」 menjadi 「(dia) mahasiswa?」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk sopan itu gampang: kalau kalimat berakhir dengan <b>です</b> atau <b>ます</b>, tinggal tambahkan か di belakangnya. Bagian depan tidak perlu diubah.<br><span class='gd-pair'><span class='gd-jp'>日本人です</span> → <span class='gd-jp'>日本人ですか</span></span><br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですか</span></span><br><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かですか</span></span><br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますか</span></span><br><span class='gd-pair'><span class='gd-jp'>食べました</span> → <span class='gd-jp'>食べましたか</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menanyakan ya atau bukan</span>Pertanyaan yang cukup dijawab dengan 「はい」atau「いいえ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本の本ですか。</span>（Apakah ini buku dari Jepang?）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、おいしいですか。</span>（Ramen ini enak?）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、学校へ行きますか。</span>（Besok kamu pergi ke sekolah?）</div><div class='gd-sec'>Saat menjawab, untuk kalimat kata benda biasanya pakai <span class='gd-jp'>はい、そうです。</span>（Ya, benar.）atau <span class='gd-jp'>いいえ、違います。</span>（Bukan.）. Untuk kata kerja atau kata sifat, ulangi kata aslinya: <span class='gd-jp'>はい、行きます。</span>（Ya, saya pergi.）／<span class='gd-jp'>いいえ、行きません。</span>（Tidak, saya tidak pergi.）.</div><div class='gd-sec'><span class='gd-tag'>Dengan kata tanya</span>Kalau di dalam kalimat ada kata seperti 「apa, di mana, kapan」, tetap tambahkan か.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅はどこですか。</span>（Permisi, stasiun di mana?）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、何を食べましたか。</span>（Kemarin kamu makan apa?）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Dengan kata tanya pun tetap pakai か</b>: di bahasa Indonesia kita tidak bilang 「Apakah itu apa?」, cukup 「Itu apa?」, jadi banyak orang lupa か. Tapi dalam bentuk sopan bahasa Jepang か tetap wajib. Katakan <span class='gd-jp'>何ですか</span>, jangan hanya 「何です」.<br>・<b>Nada naik di akhir</b>: か pada 「ですか」 diucapkan dengan nada naik. Misalnya <span class='gd-jp'>そうですか</span>: kalau nadanya naik artinya 「Begitukah?」, kalau nadanya turun jadi 「Oh, begitu ya」 yang menandakan kamu sudah paham. Artinya beda.<br>・<b>Dengan teman biasanya tidak pakai か</b>: pakai bentuk tanpa です／ます, lalu naikkan nada di akhir kalimat supaya jadi pertanyaan: <span class='gd-jp'>明日、行く？</span>（Besok pergi?）, <span class='gd-jp'>これ、おいしい？</span>（Ini enak?）. Kalau bentuk biasa langsung ditambah か (misalnya 「行くか」), terdengar kasar dan kurang sopan, jadi pemula sebaiknya jangan dulu pakai.<br>・Pertanyaan kata benda ke teman adalah <span class='gd-jp'>学生？</span>. Jangan jadi 「学生だか」, karena itu bukan kalimat tanya.<br>・<b>Tanda baca</b>: di buku pelajaran dan tulisan resmi, setelah か biasanya dipakai 「。」 karena か sudah menandakan pertanyaan. Di pesan LINE dan manga sering ada 「？」. Kamu akan menemukan keduanya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ますか</b>＝sekadar bertanya apakah lawan bicara akan melakukan sesuatu atau mau melakukannya:<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、パーティーに行きますか。</span>（Besok kamu datang ke pesta?）</div><b>ませんか</b>＝<b>mengajak</b> lawan bicara melakukan sesuatu bersama:<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、一緒にパーティーに行きませんか。</span>（Besok mau pergi ke pesta bareng?）</div>Dua kalimat ini hanya beda sedikit. Yang pertama menanyakan rencana lawan bicara, yang kedua mengajaknya.</div><div class='gd-warn'>Trik cepat: kalau cuma ingin tahu apakah dia akan melakukannya, pakai 「ますか」. Kalau ingin mengajaknya melakukan bersama, pakai 「ませんか」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau kamu sudah hafal kata tanya seperti 「何、どこ、いつ、だれ」, kamu bisa menanyakan berbagai hal. Lalu pelajari 「〜ませんか」, dan kamu sudah bisa mengajak orang.</div>","n5-14":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Ada dua cara sopan untuk mengatakan 「tidak ～」: <span class='gd-jp'>食べません</span> dan <span class='gd-jp'>食べないです</span>. Dua-duanya berarti 「tidak makan」. Bedanya mirip pakai jas dan pakai kemeja: <b>ません lebih formal</b>, <b>ないです lebih santai</b>. Keduanya sopan, jadi aman dipakai ke guru maupun pegawai toko.</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'>Versi <span class='gd-jp'>ません</span> gampang, tinggal ganti ます jadi ません: <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みません</span></span><br>Versi <span class='gd-jp'>ないです</span> memakai 「bentuk ない」 (bentuk 「tidak ～」 versi akrab dari kata kerja), lalu ditambah <span class='gd-jp'>です</span>:</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan / 五段)</b>: ubah bunyi terakhir jadi bunyi baris 「あ」 dari baris yang sama, tambahkan ない, lalu です.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む diganti ま → <span class='gd-jp'>飲まないです</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないです</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らないです</span></span><br>Kalau berakhiran 「う」, gantilah jadi 「わ」：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わないです</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan / 一段)</b>: buang 「る」, lalu tambahkan ないです.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないです</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ないです</span></span></div><div class='gd-sec'><b>Golongan 3 (cuma dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないです</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないです</span>（こないです）</span></div><div class='gd-h'>Kata sifat dan kata benda juga punya dua versi</div><div class='gd-sec'><b>Kata sifat-い</b>: ganti 「い」 di akhir jadi 「く」, lalu tambahkan ないです atau ありません.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くないです</span></span>＝<span class='gd-jp'>寒くありません</span><br><b>Kata sifat-な dan kata benda</b>: langsung tambahkan じゃないです atau じゃありません.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かじゃないです</span></span>＝<span class='gd-jp'>静かじゃありません</span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃないです</span></span>＝<span class='gd-jp'>学生じゃありません</span><br>Kalau mau lebih formal lagi, ganti じゃ jadi では：<span class='gd-jp'>学生ではありません</span>.</div><div class='gd-sec'>Bentuk lampau 「tidak ～」 juga ada dua: <span class='gd-jp'>食べませんでした</span>＝<span class='gd-jp'>食べなかったです</span>、<span class='gd-jp'>寒くありませんでした</span>＝<span class='gd-jp'>寒くなかったです</span>.</div><div class='gd-h'>Kapan pakai yang mana</div><div class='gd-sec'><span class='gd-tag'>Situasi formal</span>Untuk menulis email, di tempat kerja, wawancara, atau bicara dengan orang yang lebih tua, ません lebih aman.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は会社に行きません。</span>（Besok aku tidak ke kantor）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は学生ではありません。</span>（Saya bukan pelajar）</div><div class='gd-sec'><span class='gd-tag'>Obrolan sehari-hari</span>Saat ngobrol dengan pegawai toko, tetangga, atau teman sekelas yang belum terlalu akrab, ないです sering terdengar. <span class='gd-jp'>くないです</span> dan <span class='gd-jp'>じゃないです</span> pada kata sifat bahkan lebih sering dipakai daripada ありません dalam percakapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>肉はあまり食べないです。</span>（Aku jarang makan daging）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、高くないですよ。</span>（Toko ini tidak mahal, lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はそんなに寒くないですね。</span>（Hari ini tidak sedingin itu ya）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Dua versi ini tidak boleh dicampur: tidak ada <span class='gd-jp'>食べないません</span>, dan tidak ada juga <span class='gd-jp'>食べませんです</span>.<br>・「Tidak ada」 dari <span class='gd-jp'>ある</span> itu istimewa, langsung jadi <span class='gd-jp'>ない</span>. Tidak ada bentuk あらない: <span class='gd-jp'>時間がありません</span>＝<span class='gd-jp'>時間がないです</span> (tidak punya waktu).<br>・<span class='gd-jp'>いい</span> harus jadi <span class='gd-jp'>よくないです</span>, bukan いくないです.<br>・<span class='gd-jp'>買う</span> jadi <span class='gd-jp'>買わない</span>, bukan 買あない.<br>・<span class='gd-jp'>来ない</span> dibaca <b>こない</b>, bukan きない.<br>・Tidak semuanya bisa saling menggantikan: <span class='gd-jp'>すみません</span> adalah ungkapan maaf yang sudah baku, tidak diubah jadi すまないです. Ajakan <span class='gd-jp'>一緒に行きませんか</span> (Mau pergi bareng?) juga paling natural dan sopan kalau pakai ません.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Banyak orang setelah belajar ないです, saat bicara malah lupa menaruh <span class='gd-jp'>です</span>. Sama-sama 「hari ini aku tidak pergi」:<br>Ke guru: <span class='gd-jp'>今日は行きません。</span>／<span class='gd-jp'>今日は行かないです。</span> (dua-duanya boleh)<br>Ke teman: <span class='gd-jp'>今日は行かない。</span> (versi teman, kalau dipakai ke guru terlalu santai)</div><div class='gd-warn'>Trik menilai: kalau di akhir kalimat ada <span class='gd-jp'>ます</span> (ません) atau <span class='gd-jp'>です</span>, itu versi sopan. Kalau dua-duanya tidak ada, itu versi teman.</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'>Kalau kamu penasaran kapan です boleh dibuang dan langsung bilang <span class='gd-jp'>行かない</span>, lanjutkan ke 「Bentuk sopan dan bentuk biasa (丁寧体・普通体)」 dan 「Bentuk kamus・bentuk ない (辞書形・ない形)」.</div>","n5-16":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「も」 artinya <b>「juga」</b>. Tapi cara menaruhnya khas: も <b>menempel langsung di belakang hal yang mau di-「juga」-kan</b> (<span class='gd-jp'>私も</span>＝aku juga). Jadi kamu harus memutuskan dulu, siapa atau apa yang sedang 「juga」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>は・が・を</span>Ketiganya <b>dibuang dan diganti も</b>.<br><span class='gd-pair'><span class='gd-jp'>私は</span> → <span class='gd-jp'>私も</span></span><span class='gd-pair'><span class='gd-jp'>猫が</span> → <span class='gd-jp'>猫も</span></span><span class='gd-pair'><span class='gd-jp'>コーヒーを</span> → <span class='gd-jp'>コーヒーも</span></span></div><div class='gd-sec'><span class='gd-tag'>に・で・へ・と</span>Partikel ini <b>tetap dipertahankan</b>, lalu も ditambahkan di belakangnya.<br><span class='gd-pair'><span class='gd-jp'>大阪に</span> → <span class='gd-jp'>大阪にも</span></span><span class='gd-pair'><span class='gd-jp'>家で</span> → <span class='gd-jp'>家でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>大阪にも行きました。</span>（Ke Osaka juga aku pergi）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Juga</span>Tadi sudah menyebut satu hal, lalu menambahkan satu hal lain yang sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：私は学生です。B：私も学生です。</span>（A: Aku pelajar. B: Aku juga pelajar）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：コーヒーが好きです。B：私も。</span>（A: Aku suka kopi. B: Aku juga）</div><div class='gd-sec'><span class='gd-tag'>AもBも</span>Keduanya sama, artinya 「A dan B sama-sama ～」. Kalau diikuti bentuk negatif, artinya 「keduanya tidak」.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンもケーキも好きです。</span>（Aku suka roti dan juga kue）</div><div class='gd-ex-line'>・<span class='gd-jp'>肉も魚も食べません。</span>（Daging maupun ikan tidak aku makan）</div><div class='gd-sec'><span class='gd-tag'>Kata tanya＋も＋negatif</span>Artinya 「tidak ada apa pun」「tidak ada siapa pun」「tidak ke mana pun」. Di belakangnya pasti bentuk negatif.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べませんでした。</span>（Tadi pagi aku tidak makan apa-apa）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室には誰もいません。</span>（Tidak ada siapa pun di kelas）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末はどこにも行きませんでした。</span>（Akhir pekan aku tidak pergi ke mana-mana）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Tidak ada bentuk <span class='gd-jp'>はも</span>、<span class='gd-jp'>がも</span>、<span class='gd-jp'>をも</span>. は・が・を langsung diganti jadi も.<br>・も menempel di belakang siapa atau apa, maka 「juga」 merujuk ke dia, dan artinya bisa sangat berbeda:<br><span class='gd-jp'>私もコーヒーを飲みます。</span>（Orang lain minum kopi, <b>aku juga</b> minum）<br><span class='gd-jp'>私はコーヒーも飲みます。</span>（Aku minum teh, <b>kopi juga</b> kuminum）<br>Dalam bahasa Indonesia, keduanya bisa terdengar seperti 「Aku juga minum kopi」, tapi dalam bahasa Jepang kamu harus memikirkan dulu: yang 「juga」 itu orangnya atau kopinya.<br>・<span class='gd-jp'>何も</span> dan <span class='gd-jp'>誰も</span> diikuti bentuk negatif. Untuk bilang 「suka apa saja」 kamu tidak bisa pakai 何も好きです, harus pakai ungkapan lain (seperti <span class='gd-jp'>何でも好きです</span>, nanti kita pelajari).<br>・「Tidak pergi ke mana pun」 harus <span class='gd-jp'>どこにも</span>, jangan sampai に ketinggalan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>AとB</b>＝sekadar menyebut dua hal: <span class='gd-jp'>パンとケーキが好きです。</span>（Aku suka roti dan kue）<br><b>AもBも</b>＝menekankan 「kedua-duanya」: <span class='gd-jp'>パンもケーキも好きです。</span>（Roti suka, kue juga suka, dua-duanya）<br>Cara menaruhnya juga beda: と cukup sekali di tengah, sedangkan も <b>harus ditaruh di belakang setiap kata</b>.</div><div class='gd-warn'>Trik menilai: kalau cuma menyebutkan daftar benda, pakai と. Kalau mau menekankan 「dua-duanya ～」, pakai 〜も〜も.</div>","n5-27":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「と」yang ini sama seperti <b>\"dan\"</b> atau <b>\"dengan\"</b> dalam bahasa Indonesia: dipakai untuk menyebutkan benda satu per satu. Dan ada satu makna tambahannya: <b>yang kamu sebut itulah semuanya, tidak ada yang lain</b>. Misalnya kamu bilang ke temanmu \"Aku beli roti dan susu\", berarti kamu hanya beli dua barang itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンと牛乳を買いました。</span>（Aku membeli roti dan susu）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina＋と＋Nomina, <b>kedua sisinya harus nomina</b>. Setelah daftarnya selesai, baru di paling akhir kamu pasang partikel yang dibutuhkan kalimat itu (を、が、は…).<br><span class='gd-pair'><span class='gd-jp'>鍵</span>＋<span class='gd-jp'>財布</span> → <span class='gd-jp'>鍵と財布を持ってきました</span></span>（Aku membawa kunci dan dompet）<br>Kalau ada tiga atau lebih, taruh と di antara setiap benda:</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日と水曜日と金曜日に授業があります。</span>（Hari Senin, Rabu, dan Jumat ada kelas）</div><div class='gd-ex-line'>・<span class='gd-jp'>父と母は台北に住んでいます。</span>（Ayah dan ibuku tinggal di Taipei）</div><div class='gd-sec'>Waktu memesan makanan pun sering dipakai:</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーとケーキをお願いします。</span>（Tolong kopi dan kue）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Partikel hanya diletakkan setelah nomina terakhir</b>. Yang benar <span class='gd-jp'>鍵と財布を持ってきました</span>, jangan bilang \"鍵を財布を持ってきました\" atau \"鍵をと財布を持ってきました\".<br>・と <b>hanya bisa menyambung nomina</b>. Kata \"dan\" dalam bahasa Indonesia sangat serbaguna: \"murah dan enak\" atau \"makan dan nonton TV\" semuanya bisa. Tapi dalam bahasa Jepang, と tidak bisa dipakai untuk menyambung kata sifat atau kata kerja. Untuk itu nanti kamu akan belajar bentuk て.<br>・と artinya \"hanya itu saja\". Kalau masih ada hal lain yang belum disebut, pakai や.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><span class='gd-tag'>と vs や</span>Sama-sama bicara tentang apa yang dibawa di tas:<br><span class='gd-jp'>鍵と財布を持ってきました。</span>（Aku membawa kunci dan dompet: hanya dua itu）<br><span class='gd-jp'>鍵や財布を持ってきました。</span>（Aku membawa kunci, dompet, dan semacamnya: masih ada yang lain）</div><div class='gd-sec'><span class='gd-tag'>\"dan\" vs \"bersama\"</span>と punya satu fungsi lagi, yaitu \"melakukan sesuatu bersama siapa\".<br><b>と untuk menyusun daftar</b>: A dan B diikat jadi satu kelompok, lalu diikuti partikel seperti は、が、を dan keduanya bersama-sama menjadi bagian kalimat.<br><span class='gd-jp'>友達と私は映画を見ました。</span>（Temanku dan aku menonton film: 「友達と私」 satu kelompok, lalu diikuti は）<br><b>と untuk \"bersama\"</b>: \"orang＋と\" menjelaskan dengan siapa kamu melakukan tindakan berikutnya. Meskipun setelahnya ada nomina, nomina itu adalah unsur lain dan tidak terikat dengan orang di depan と.<br><span class='gd-jp'>友達と映画を見ました。</span>（Aku menonton film dengan temanku: 「友達と」 menjelaskan dengan siapa, 「映画を」 adalah yang ditonton, bukan \"teman dan film\"）<br>Kalau ingin menekankan \"bersama\", sering diucapkan <span class='gd-jp'>友達と一緒に映画を見ました</span>.</div><div class='gd-warn'>Trik membedakan: coba taruh nomina di depan と sendirian ke dalam kalimat. <span class='gd-jp'>鍵を持ってきました</span> dan <span class='gd-jp'>財布を持ってきました</span> keduanya masuk akal, berarti itu \"A dan B\". Tapi kalau 「友達と映画を見ました」 diubah jadi 「友達を見ました」, artinya jadi salah, jadi と itu berarti \"bersama siapa\".</div>","n5-28":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「や」mirip dengan <b>\"seperti A, B, dan sebagainya\"</b> dalam bahasa Indonesia. Barangnya banyak, tapi kamu hanya memilih beberapa sebagai contoh, sambil memberi tahu lawan bicara bahwa <b>masih ada yang lain, tidak semuanya disebut</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina＋<b>や</b>＋Nomina, di akhir sering ditambah 「<b>など</b>」 (dan lain-lain). Partikel yang dibutuhkan (を、が、に…) tetap dipasang di paling belakang.<br><span class='gd-pair'><span class='gd-jp'>牛乳</span>＋<span class='gd-jp'>卵</span> → <span class='gd-jp'>牛乳や卵</span></span><br><span class='gd-pair'><span class='gd-jp'>牛乳や卵</span> → <span class='gd-jp'>牛乳や卵など</span></span>（Dengan など, kesan \"masih ada yang lain\" jadi lebih terasa）</div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>（Di kulkas ada susu, telur, dan semacamnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除や洗濯をします。</span>（Akhir pekan aku bersih-bersih, mencuci baju, dan sebagainya）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で寿司やラーメンなどを食べました。</span>（Di Jepang aku makan sushi, ramen, dan lain-lain）</div><div class='gd-sec'>Kalau mau menyebut tiga contoh juga boleh, taruh や di antara setiap benda:</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上にペンやノートや辞書などがあります。</span>（Di atas meja ada pulpen, buku catatan, kamus, dan lain-lain）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「と」juga menyambung nomina, tapi artinya sangat berbeda. Sama-sama bicara tentang isi tas:<br><b>と</b>＝<b>hanya itu semuanya</b>: <span class='gd-jp'>かばんに財布と鍵があります。</span>（Di tas ada dompet dan kunci, hanya dua itu）<br><b>や</b>＝<b>contoh, masih ada yang lain</b>: <span class='gd-jp'>かばんに財布や鍵があります。</span>（Di tas ada dompet, kunci, dan semacamnya, masih ada barang lain）</div><div class='gd-warn'>Trik membedakan: kalau kamu bisa bilang \"hanya itu\", pakai と. Kalau hanya memberi beberapa contoh dan di hati masih ada \"…dan semacamnya\", pakai や.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・や <b>hanya bisa menyambung nomina</b>. Untuk memberi contoh tindakan, tidak bisa bilang \"食べるや飲む\", harus pakai 「〜たり〜たりします」: <span class='gd-jp'>食べたり飲んだりします</span> (makan, minum, dan sebagainya).<br>・<b>Jangan taruh や lagi</b> setelah nomina terakhir. Jangan berhenti di \"ペンやノートや\". Kalau ingin menyatakan \"dan lain-lain\", tambahkan など: <span class='gd-jp'>ペンやノートなど</span>.<br>・Kata \"dan\" dalam bahasa Indonesia kadang bisa berarti \"bersama siapa\", tapi や tidak punya arti itu. \"Aku pergi dengan temanku\" adalah <span class='gd-jp'>友達と行きます</span>, tidak bisa 友達や行きます.<br>・Kamu tidak perlu menunggu bendanya banyak untuk memakai や. Hanya menyebut dua pun boleh, yang penting ada kesan \"tidak semuanya disebut\".</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Versi contoh untuk tindakan adalah 「〜たり〜たりします」: <span class='gd-jp'>休みの日は映画を見たり、買い物をしたりします。</span>（Di hari libur aku menonton film, berbelanja, dan semacamnya）</div>","n5-23":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「を」itu seperti label kecil yang ditempel di belakang kata benda. Artinya: <b>「benda ini adalah sasaran dari tindakannya」</b>. Dalam bahasa Indonesia, \"makan roti\" sudah jelas dari urutan katanya, yaitu yang dimakan adalah roti. Di bahasa Jepang, kata kerja ada di akhir kalimat, jadi kamu butuh 「を」 untuk menandai <b>apa yang dimakan, apa yang dilihat</b>.</div><div class='gd-h'>Cara memakainya</div><div class='gd-sec'>Kata benda＋を＋kata kerja. Urutan bahasa Jepang itu \"bendanya dulu, tindakannya terakhir\":<br><span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンを食べます</span></span> (makan roti)</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲みます。</span> (minum air)</div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見ます。</span> (menonton film)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日日本語を勉強します。</span> (Setiap hari aku belajar bahasa Jepang)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sasaran tindakan</span>Ini fungsi yang paling utama dan paling sering dipakai: makan apa, minum apa, beli apa, melakukan apa. Latih yang ini sampai lancar dulu.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニで傘を買いました。</span> (Aku beli payung di minimarket)</div><div class='gd-sec'><span class='gd-tag'>Tempat yang dilewati</span>Dipakai dengan kata kerja gerak seperti \"berjalan, jalan-jalan, menyeberang (jembatan, jalan)\". Artinya <b>melewati atau menyusuri tempat itu</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園を散歩します。</span> (jalan-jalan di taman)</div><div class='gd-ex-line'>・<span class='gd-jp'>橋を渡ります。</span> (menyeberangi jembatan)</div><div class='gd-sec'><span class='gd-tag'>Tempat yang ditinggalkan</span>Dipakai dengan kata kerja seperti \"keluar, turun (dari kendaraan)\". Artinya <b>pergi meninggalkan tempat itu</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に家を出ます。</span> (berangkat dari rumah jam 8)</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span> (turun dari kereta di stasiun berikutnya)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・「を」dibaca <b>o</b>, sama seperti 「お」, jangan dibaca wo. Tapi kalau mengetik di komputer atau ponsel, kamu harus mengetik <b>wo</b> supaya karakternya muncul.<br>・Bunyinya sama, tapi saat menulis tetap harus 「を」, tidak boleh diganti 「お」.<br>・\"Suka, mengerti, ingin\" tidak memakai を. Bentuk standar di buku pelajaran adalah <span class='gd-jp'>猫が好きです</span> dan <span class='gd-jp'>英語がわかります</span>, jangan dibuat menjadi 猫を好きです.<br>・Dalam bahasa Indonesia kita bilang \"bertemu teman\" atau \"naik kereta\" seolah langsung ke objeknya, tapi di bahasa Jepang harus pakai に: <span class='gd-jp'>友達に会います</span>, <span class='gd-jp'>電車に乗ります</span>. Sebaliknya, \"turun dari kereta\" adalah <span class='gd-jp'>電車を降ります</span>. Naik pakai に, turun pakai を, jadi hafalkan terpisah.<br>・<b>Satu kata kerja jangan membawa dua を</b>. <span class='gd-jp'>日本語を勉強をします</span> terdengar tidak natural (勉強します hanya boleh punya satu を). Katakan <span class='gd-jp'>日本語を勉強します</span> atau <span class='gd-jp'>日本語の勉強をします</span>. Kalau kata kerjanya berbeda, masing-masing boleh punya を, misalnya <span class='gd-jp'>本を読んで、ご飯を食べます。</span> (membaca buku, lalu makan)<br>・Dalam obrolan dengan teman, を sering dihilangkan: <span class='gd-jp'>ご飯、食べた？</span> (Sudah makan?). Ini bahasa lisan. Saat menulis kalimat sendiri, tetap pasang を dulu.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>を vs が</b>: sama-sama soal bahasa Jepang, tapi tindakan pakai を, sedangkan perasaan dan kemampuan pakai が.<br><span class='gd-jp'>日本語を勉強します。</span> (belajar bahasa Jepang: tindakan)<br><span class='gd-jp'>日本語が好きです。</span> (suka bahasa Jepang: perasaan)<br><span class='gd-jp'>日本語がわかります。</span> (mengerti bahasa Jepang: kemampuan)</div><div class='gd-sec'><b>を vs で</b>: sama-sama soal jembatan, tapi \"menyeberangi jembatan\" pakai を, sedangkan \"melakukan hal lain di jembatan\" pakai で.<br><span class='gd-jp'>橋を渡ります。</span> (menyeberangi jembatan: berjalan melewatinya)<br><span class='gd-jp'>橋で写真を撮ります。</span> (memotret di jembatan: jembatan hanya tempat kejadian, yang dipotret, yaitu「写真」, yang pakai を)</div><div class='gd-warn'>Trik menentukan: tanyakan pada dirimu, \"apakah tindakannya langsung dilakukan pada benda ini?\" Kalau ya, pakai を. \"Suka, mengerti, ingin\" pakai が. Kalau hanya menyebut \"di mana\" sesuatu dilakukan, pakai で.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Ada kata kerja yang berpasangan, satu pakai を dan satu pakai が: <span class='gd-jp'>ドアを開けます</span> (aku membuka pintu), <span class='gd-jp'>ドアが開きます</span> (pintunya terbuka). Inilah yang disebut 自動詞・他動詞 (kata kerja intransitif・transitif). Setelah paham を, topik ini akan terasa jauh lebih mudah.</div>","n5-24":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「で」kurang lebih berarti <b>\"di (mana) melakukan (apa)\"</b>. Bayangkan tempat itu sebagai panggung. 「で」memberi tahu lawan bicara bahwa tindakan ini dimainkan di panggung tersebut.<br><span class='gd-jp'>カフェで仕事をします。</span> (bekerja di kafe)</div><div class='gd-h'>Cara memakainya</div><div class='gd-sec'>Tambahkan 「で」langsung setelah tempat, lalu sebutkan tindakanmu.<br><span class='gd-pair'><span class='gd-jp'>図書館</span> → <span class='gd-jp'>図書館で勉強します</span></span> (belajar di perpustakaan)<br><span class='gd-pair'><span class='gd-jp'>家</span> → <span class='gd-jp'>家で晩ご飯を食べます</span></span> (makan malam di rumah)<br>Tempatnya mau besar atau kecil boleh: negara, kota, toko, ruangan, bahkan \"di sini\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Melakukan sesuatu di suatu tempat</span>Makan, minum, membeli, menonton, belajar, bekerja, bermain, menunggu orang… selama itu tindakan yang \"dilakukan\", pakai で setelah tempatnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で友達を待ちます。</span> (menunggu teman di stasiun)</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートで靴を買いました。</span> (membeli sepatu di mal)</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってもいいですか。</span> (Boleh foto di sini?)</div><div class='gd-sec'><span class='gd-tag'>Menanyakan tempat tindakan</span>Pakai 「どこで」untuk bertanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、どこで買いましたか。</span> (Tas itu kamu beli di mana?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこで昼ご飯を食べますか。</span> (Mau makan siang di mana?)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>「で」dan「に」: tempatnya sama, lihat kata kerja di belakangnya</b><br>Dalam bahasa Indonesia, keduanya cukup \"di perpustakaan\". Di bahasa Jepang, kamu harus melihat apakah kamu \"berada di sana\" atau \"melakukan sesuatu di sana\".<br><span class='gd-jp'>図書館にいます。</span> (Aku ada di perpustakaan: orangnya berada di sana, pakai に)<br><span class='gd-jp'>図書館で勉強します。</span> (Aku belajar di perpustakaan: melakukan sesuatu di sana, pakai で)<br>Kalau di belakangnya kata \"keberadaan\" seperti <b>いる、ある</b> (ada), pakai に. Kalau di belakangnya <b>suatu tindakan</b>, pakai で.</div><div class='gd-sec'><b>「で」dan「へ」: akan pergi ke sana, atau sudah ada di sana</b><br><span class='gd-jp'>図書館へ行きます。</span> (pergi ke perpustakaan: bergerak ke arah sana, pakai へ)<br><span class='gd-jp'>図書館で本を読みます。</span> (membaca buku di perpustakaan: sudah sampai dan melakukan sesuatu di sana, pakai で)</div><div class='gd-sec'><b>「で」yang lain: kendaraan dan alat</b><br>「で」punya tugas lain juga, yaitu yang di depannya adalah benda, bukan tempat.<br><span class='gd-jp'>バスで行きます。</span> (pergi naik bus: kendaraan)<br><span class='gd-jp'>公園で遊びます。</span> (bermain di taman: tempat)<br>Lihat saja kata di depannya itu \"tempat\" atau \"alat\", maka kamu bisa membedakannya.</div><div class='gd-warn'>Trik menentukan: <b>orang atau benda \"ada\" di sana → に; \"pergi\" ke sana → へ; \"melakukan\" sesuatu di sana → で.</b></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata \"di\" dalam bahasa Indonesia tidak selalu menjadi で. \"Aku di rumah\" adalah <span class='gd-jp'>家にいます</span>, bukan 家でいます.<br>・\"Tinggal di Tokyo\" harus pakai に: <span class='gd-jp'>東京に住んでいます</span>, bukan 東京で住んでいます. \"Tinggal\" artinya berada di sana, bukan melakukan suatu tindakan di sana. Ini kesalahan yang paling sering dibuat pelajar Indonesia karena kita juga bilang \"di\".<br>・\"Bekerja\" aman pakai で: <span class='gd-jp'>銀行で働いています</span> (bekerja di bank). Jangan karena 住む pakai に, 働く ikut diganti jadi に.<br>・Untuk kata kerja \"gerak\" seperti 行く、来る、帰る, tujuannya tidak pakai で. Katakan <span class='gd-jp'>日本へ行きます</span>, bukan 日本で行きます.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau 「で」dan「を」digabung, kamu sudah bisa membuat satu kalimat utuh: <b>tempat＋で＋benda＋を＋tindakan</b>.<br><span class='gd-jp'>コンビニでお茶を買いました。</span> (Aku membeli teh di minimarket)<br>Selanjutnya pelajari 「に」(posisi keberadaan). Kalau keduanya dibandingkan sekaligus, に dan で tidak akan tertukar lagi.</div>","n5-25":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「から」itu sama dengan <b>「dari」</b> dalam bahasa Indonesia. Dari jam berapa, dari mana, dari siapa, semuanya pakai から. Kata ini sering muncul bersama 「まで」（sampai）, jadi <span class='gd-jp'>AからBまで</span> artinya 「dari A sampai B」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang: <b>tambahkan から langsung di belakang kata benda</b>, tanpa perubahan apa pun.<br><span class='gd-pair'><span class='gd-jp'>9時</span> → <span class='gd-jp'>9時から</span></span>（dari jam 9）<span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅から</span></span>（dari stasiun）<span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達から</span></span>（dari teman）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Titik awal waktu</span>Dimulai dari waktu tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は9時からです。</span>（Kerja mulai jam 9）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日から夏休みです。</span>（Mulai besok libur musim panas）</div><div class='gd-sec'><span class='gd-tag'>Titik awal tempat</span>Berangkat dari suatu tempat, atau datang dari mana.</div><div class='gd-ex-line'>・<span class='gd-jp'>どこから来ましたか。</span>（Kamu datang dari mana?）</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾から来ました。</span>（Saya datang dari Taiwan）</div><div class='gd-sec'><span class='gd-tag'>Dari siapa</span>Siapa yang memberi barang atau kabar.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達から電話がありました。</span>（Ada telepon dari teman）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar: AからBまで</div><div class='gd-sec'>Untuk menyebut rentang, 「から」dan「まで」sering dipakai berpasangan, baik untuk waktu maupun tempat.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日から金曜日まで働きます。</span>（Kerja dari Senin sampai Jumat）</div><div class='gd-ex-line'>・<span class='gd-jp'>家から駅まで歩きます。</span>（Jalan kaki dari rumah sampai stasiun）</div><div class='gd-ex-line'>・<span class='gd-jp'>何時から何時までですか。</span>（Dari jam berapa sampai jam berapa?）</div><div class='gd-sec'>Kalimat terakhir ini berguna banget untuk menanyakan jam buka toko atau jam acara. Kalau kamu ke Jepang, pasti terpakai. Kalau tidak perlu menyebut rentang, memakai 「から」saja juga tidak masalah.</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・<b>Posisinya terbalik dari bahasa Indonesia</b>: dalam bahasa Indonesia 「dari」ada di depan kata benda, sedangkan 「から」ada di <b>belakang</b> kata benda. 「Dari stasiun」itu <span class='gd-jp'>駅から</span>, bukan から駅.<br>・Dalam bahasa Indonesia kita bisa bilang 「<b>mulai</b> besok libur」, tapi dalam bahasa Jepang <span class='gd-jp'>明日から夏休みです</span> sudah cukup. 「から」sendiri sudah berarti 「mulai dari ～」, jadi kata 「mulai」tidak perlu diterjemahkan lagi.<br>・Untuk 「melakukan sesuatu pada jam tertentu」pakai 「に」, bukan 「から」. Ini dibahas lebih rinci di bawah.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>① から (titik awal) vs に (titik waktu)</b><br><span class='gd-jp'>9時に起きます。</span>（Bangun jam 9: hanya di satu titik waktu itu）<br><span class='gd-jp'>9時から勉強します。</span>（Belajar mulai jam 9: setelah itu berlangsung selama beberapa waktu）<br>「Bangun」adalah aksi yang selesai seketika, jadi kalau dibilang 9時から起きます akan terdengar aneh.</div><div class='gd-warn'>Trik membedakan: kalau hanya menyebut 「jam berapa melakukannya」pakai に; kalau mau bilang 「mulai saat itu dan berlanjut terus」pakai から.</div><div class='gd-sec'><b>② から (titik awal) vs から (alasan)</b><br>Di N5 kamu juga akan belajar 「から」lain yang berarti 「karena」. Bentuknya persis sama, jadi lihat <b>apa yang ada di depannya</b>.<br>Titik awal: <b>kata benda langsung + から</b>, misalnya <span class='gd-jp'>駅から</span>（dari stasiun）.<br>Alasan: di depannya ada <b>satu kalimat utuh</b>. Kata benda harus diberi だ atau です dulu（<span class='gd-jp'>雨だから</span>、<span class='gd-jp'>雨ですから</span>）, atau kata kerja dan kata sifat い dalam bentuk biasa atau bentuk sopan（<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>、<span class='gd-jp'>高いですから</span>）.<br>Coba bandingkan dengan 「besok ujian」yang sama:<br><span class='gd-jp'>明日からテストです。</span>（Ujiannya mulai besok）<br><span class='gd-jp'>明日テストだから、勉強します。</span>（Karena besok ada ujian, aku belajar）</div><div class='gd-warn'>Trik membedakan: kalau di depan から hanya ada kata benda seperti waktu, tempat, atau orang, artinya 「dari」. Kalau di depannya だ／です, atau kata kerja dan kata sifat dalam bentuk biasa atau sopan（<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>）, artinya 「karena」. （「Bentuk て kata kerja + から」adalah pola tata bahasa lain yang berarti 「setelah melakukan ～」, jangan dicampur.）</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Pasangannya 「まで」（sampai）bisa dipelajari bersamaan. Nanti kamu juga akan belajar 「bentuk て kata kerja + から」＝ setelah melakukan ～ baru ～: <span class='gd-jp'>ご飯を食べてから、出かけます。</span>（Setelah makan, baru berangkat）</div>","n5-26":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「まで」itu sama dengan <b>「sampai ～」</b> dalam bahasa Indonesia, menunjukkan di mana <b>titik akhirnya</b>. Bisa titik akhir waktu（sampai jam 5）, bisa juga titik akhir tempat（sampai stasiun）. Kata ini sering berpasangan dengan 「から」（dari ～）: <span class='gd-jp'>から</span> adalah titik awal, <span class='gd-jp'>まで</span> adalah titik akhir.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Waktu</span>Suatu hal dilakukan terus-menerus, lalu berhenti pada titik waktu itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（Saya menunggu sampai jam 5）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は11時まで寝ました。</span>（Kemarin saya tidur sampai jam 11）</div><div class='gd-sec'><span class='gd-tag'>Tempat</span>Bergerak sampai ke suatu tempat.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩きます。</span>（Saya jalan kaki sampai stasiun）</div><div class='gd-ex-line'>・<span class='gd-jp'>空港までバスで行きます。</span>（Saya naik bus sampai bandara）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang, tambahkan まで langsung di belakang kata benda, tanpa perubahan.<br><span class='gd-pair'><span class='gd-jp'>6時</span> → <span class='gd-jp'>6時まで</span></span><span class='gd-pair'><span class='gd-jp'>金曜日</span> → <span class='gd-jp'>金曜日まで</span></span><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京まで</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>から～まで</span>Dari mana sampai mana, dari jam berapa sampai jam berapa. Rentangnya jadi jelas dalam sekali ucap.</div><div class='gd-ex-line'>・<span class='gd-jp'>9時から5時まで働きます。</span>（Saya kerja dari jam 9 sampai jam 5）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京から大阪まで新幹線で行きます。</span>（Dari Tokyo sampai Osaka naik Shinkansen）</div><div class='gd-sec'><span class='gd-tag'>～までです</span>Langsung diikuti です. Sering banget dipakai untuk jam buka atau jam pelajaran.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は夜10時までです。</span>（Toko ini buka sampai jam 10 malam）</div><div class='gd-sec'><span class='gd-tag'>いつまで・どこまで</span>Untuk bertanya 「sampai kapan」「sampai mana」.</div><div class='gd-ex-line'>・<span class='gd-jp'>いつまで日本にいますか。</span>（Kamu di Jepang sampai kapan?）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・まで berarti aksi <b>berlangsung terus</b> sampai titik itu. Dalam bahasa Indonesia 「sampai」kadang bisa berarti 「tiba」, tapi まで tidak bisa dipakai begitu. 「5時まで来てください」terdengar sangat aneh, karena artinya seperti 「teruslah datang sampai jam 5」. Untuk 「datanglah jam 5」pakai <span class='gd-jp'>5時に来てください</span>.<br>・「金曜日まで休みです」biasanya <b>termasuk</b> hari Jumat, jadi Jumat juga libur.<br>・まで hanya menandai titik akhir dan tidak membawa arti 「pergi」sendiri. Di belakangnya tetap perlu kata kerja, seperti <span class='gd-jp'>駅まで歩きます</span>、<span class='gd-jp'>駅まで行きます</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>に（titik waktu）</b>＝<b>terjadi sekali</b> pada titik waktu itu: <span class='gd-jp'>11時に寝ました。</span>（Saya tidur jam 11）<br><b>まで</b>＝<b>terus dilakukan sampai</b> waktu itu: <span class='gd-jp'>11時まで寝ました。</span>（Saya tidur terus sampai jam 11）<br>Bedanya cuma satu huruf, tapi yang satu naik ke tempat tidur jam 11, yang satu baru bangun jam 11.</div><div class='gd-sec'><b>までに</b>＝<b>selesai sebelum</b> waktu itu（tenggat）: <span class='gd-jp'>5時までに帰ります。</span>（Saya akan pulang sebelum jam 5）<br><b>まで</b>＝berlangsung terus sampai waktu itu: <span class='gd-jp'>5時まで待ちます。</span>（Saya menunggu terus sampai jam 5）</div><div class='gd-warn'>Trik membedakan: 「terus ～ sampai jam sekian」pakai まで; 「harus selesai sebelum jam sekian」pakai までに; 「melakukan sesuatu pada jam sekian」pakai に.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Kalau まで ditambah に, jadi <span class='gd-jp'>までに</span>, dipakai untuk menyebut tenggat: <span class='gd-jp'>金曜日までに出してください。</span>（Tolong kumpulkan sebelum hari Jumat）</div>","n5-29":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「で」yang ini setara dengan <b>「pakai ～ / dengan ～」</b>. Makan pakai sumpit, bicara dalam bahasa Jepang, menghubungi lewat telepon: semuanya cukup menambahkan 「で」 di belakang bendanya. <span class='gd-jp'>はしで食べます</span>（makan pakai sumpit）.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Alat</span>Benda yang dipegang untuk mengerjakan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>はしで食べます。</span>（makan pakai sumpit）</div><div class='gd-ex-line'>・<span class='gd-jp'>ボールペンで書いてください。</span>（tolong tulis pakai bolpoin）</div><div class='gd-sec'><span class='gd-tag'>Bahasa</span>Bahasa yang dipakai untuk berbicara atau menulis.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話しましょう。</span>（ayo kita ngobrol dalam bahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>これは英語で何と言いますか。</span>（kalau ini dalam bahasa Inggris, bilangnya apa?）</div><div class='gd-sec'><span class='gd-tag'>Cara</span>Lewat cara apa sesuatu dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>母と電話で話しました。</span>（aku bicara dengan ibu lewat telepon）</div><div class='gd-ex-line'>・<span class='gd-jp'>ネットでチケットを買いました。</span>（aku beli tiket lewat internet）</div><div class='gd-sec'><span class='gd-tag'>Bahan</span>Bahan untuk membuat sesuatu, dan setelah jadi bahan aslinya masih kelihatan.</div><div class='gd-ex-line'>・<span class='gd-jp'>紙で花を作りました。</span>（aku membuat bunga dari kertas）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang, <b>tinggal tambahkan 「で」 langsung setelah kata benda</b>, tanpa perubahan bentuk.<br><span class='gd-pair'><span class='gd-jp'>スプーン</span> → <span class='gd-jp'>スプーンで</span></span><span class='gd-pair'><span class='gd-jp'>英語</span> → <span class='gd-jp'>英語で</span></span><br>Hal yang dikerjakan tetap dihubungkan ke kata kerja dengan 「を」: <span class='gd-jp'>スプーンでスープを飲みます。</span>（minum sup pakai sendok）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Dalam bahasa Indonesia, \"pakai\" atau \"dengan\" ada di depan, sedangkan 「で」 ada di <b>belakang</b>. Kita bilang \"pakai sumpit\", tapi bahasa Jepang bilang 「はしで」. Urutannya terbalik.<br>・Pemula sering menganggap alat sebagai objek dan bilang 「はしを食べます」, yang artinya jadi \"makan sumpit\". Setelah alat, pakai <b>で</b>.<br>・Untuk bertanya \"pakai apa\", katakan <span class='gd-jp'>何で</span> yang dibaca <b>なにで</b>: <span class='gd-jp'>何で書きますか。</span>（mau menulis pakai apa?）Kalau dibaca なんで, dalam percakapan sering terdengar seperti \"kenapa\".</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>で (tempat)</b>: di mana sesuatu dilakukan: <span class='gd-jp'>教室で書きます。</span>（menulis di kelas）<br><b>で (alat)</b>: pakai apa sesuatu dilakukan: <span class='gd-jp'>ペンで書きます。</span>（menulis pakai pena）<br>Keduanya bisa ada dalam satu kalimat: <span class='gd-jp'>教室でペンで書きます。</span>（menulis di kelas pakai pena）<br>Oh ya, 「で」 pada <span class='gd-jp'>バスで行きます</span>（pergi naik bus）sebenarnya juga berarti \"dengan cara apa\", jadi konsepnya sama dengan kartu ini.</div><div class='gd-warn'>Trik membedakan: kalau di depannya \"sebuah tempat\", artinya \"di ～\"; kalau di depannya \"benda yang dipakai, bahasa, atau cara\", artinya \"pakai ～\".</div><div class='gd-sec'><b>日本語を話します</b>: bisa berbahasa Jepang, bahasa Jepang adalah kemampuan yang kamu punya.<br><b>日本語で話します</b>: berbicara dalam bahasa Jepang, bahasa Jepang adalah alat komunikasi.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話します。</span>（aku bisa berbahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>店員と日本語で話しました。</span>（aku bicara dengan pegawai toko dalam bahasa Jepang）</div><div class='gd-warn'>Trik membedakan: untuk bilang \"aku bisa bahasa apa\", pakai を; untuk bilang \"kali ini berkomunikasi pakai bahasa apa\", pakai で.</div>","n5-30":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「に」dipasang setelah <b>orang</b> untuk menunjukkan bahwa tindakan itu dilakukan <b>kepada siapa</b>. Dalam bahasa Indonesia kata yang dipakai berbeda-beda: \"menelepon\" atau \"memberi <b>kepada</b> teman\", \"bertanya <b>pada</b> guru\", \"bilang <b>ke</b> ibu\". Bahasa Jepang lebih simpel: semuanya cukup menambahkan satu 「に」 setelah orangnya.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Urutan dasarnya: <b>orang＋に</b>　<b>benda＋を</b>　<b>kata kerja</b>.<br>Sebut dulu kepada siapa, lalu bendanya, terakhir tindakannya:<br><span class='gd-jp'>母に</span>（kepada ibu）＋<span class='gd-jp'>花を</span>（bunga）＋<span class='gd-jp'>あげます</span>（memberi）→ <span class='gd-jp'>母に花をあげます。</span><br>Kalau tindakannya tidak punya \"benda\", langsung saja \"orang＋に＋kata kerja\": <span class='gd-jp'>友達に電話します。</span>（menelepon teman）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Memberikan benda kepada seseorang</span>Memberi, meminjamkan, menunjukkan kepada orang.</div><div class='gd-ex-line'>・<span class='gd-jp'>母に花をあげます。</span>（memberi bunga kepada ibu）</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を貸しました。</span>（aku meminjamkan buku kepada adikku）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に写真を見せます。</span>（menunjukkan foto kepada teman）</div><div class='gd-sec'><span class='gd-tag'>Berbicara atau menghubungi seseorang</span>Menelepon, menulis surat, bertanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に電話します。</span>（menelepon teman）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に聞きます。</span>（bertanya kepada guru）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに手紙を書きました。</span>（aku menulis surat untuk Pak Tanaka）</div><div class='gd-sec'><span class='gd-tag'>Mengajari seseorang</span></div><div class='gd-ex-line'>・<span class='gd-jp'>弟に英語を教えます。</span>（mengajari adik bahasa Inggris）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Dalam bahasa Indonesia kita sering bilang \"tanya guru\" atau \"temui teman\", jadi orangnya langsung di belakang kata kerja, dan banyak orang refleks memakai を. <span class='gd-jp'>先生を聞きます</span> itu salah, yang benar <span class='gd-jp'>先生に聞きます</span>; <span class='gd-jp'>友達を会います</span> juga salah, yang benar <span class='gd-jp'>友達に会います</span>. Tapi ada juga kata kerja yang memakai を untuk orang, misalnya <span class='gd-jp'>友達を待ちます</span>（menunggu teman）, jadi hafalkan tiap kata kerja bersama contoh kalimatnya, jangan hanya menebak dari bahasa Indonesia.<br>・Orang setelah に <b>belum tentu orang yang menerima benda</b>. Pada tindakan seperti \"meminjam (dari orang)\" dan \"belajar\", orang yang diberi に justru sumber bendanya: <span class='gd-jp'>友達に本を借りました。</span>（aku meminjam buku dari temanku）、<span class='gd-jp'>先生に日本語を習います。</span>（belajar bahasa Jepang dari guru）.<br>・「に」punya penggunaan lain, seperti waktu (<span class='gd-jp'>7時に</span>) dan tempat (<span class='gd-jp'>東京に</span>). Lihat apa yang ada di depannya: kalau di depannya <b>orang</b>, biasanya itulah penggunaan di kartu ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kata \"dengan\" atau \"sama\" dalam bahasa Indonesia gampang bikin bingung antara <b>に</b> dan <b>と</b>:<br><span class='gd-jp'>友達に話します。</span>（memberi tahu teman: aku bicara, dia mendengarkan, jadi <b>searah</b>）<br><span class='gd-jp'>友達と話します。</span>（ngobrol dengan teman: dua orang saling bergantian bicara, jadi dilakukan <b>bersama</b>）<br>Sama-sama \"bicara dengan teman\", tapi kalau pakai に artinya aku berbicara kepadanya, kalau pakai と artinya kita ngobrol bersama.</div><div class='gd-warn'>Trik membedakan: kalau \"dengan/sama\" dalam bahasa Indonesia bisa diganti \"bersama\", pakai と; kalau hanya bisa diganti \"kepada\", \"ke\", atau \"untuk\", pakai に.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Ungkapan \"siapa memberi benda kepada siapa\", seperti <span class='gd-jp'>あげます</span>、<span class='gd-jp'>もらいます</span>、<span class='gd-jp'>くれます</span>, akan terus memakai 「に」 ini, jadi kamu bisa lanjut belajar kata kerja pemberian dan penerimaan.</div>","n5-32":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang 「suka anjing」 atau 「paham bahasa Korea」. Anjing dan bahasa Korea terasa seperti objek dari kata kerjanya, jadi nalurimu pasti ingin pakai <span class='gd-jp'>を</span>. Tapi dalam bahasa Jepang, kata-kata untuk <b>suka, tidak suka, jago, kurang jago, paham, bisa, ingin</b> memakai <b>が</b> setelah bendanya. Anggap saja ini pasangan kata yang harus dihafal, beres.</div><div class='gd-h'>Kata apa saja yang memakai が</div><div class='gd-sec'><span class='gd-tag'>Suka・Tidak suka</span><span class='gd-jp'>好き</span> (suka), <span class='gd-jp'>嫌い</span> (tidak suka)</div><div class='gd-ex-line'>・<span class='gd-jp'>チョコレートが好きです。</span>(Aku suka cokelat.)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は野菜が嫌いです。</span>(Aku tidak suka sayur.)</div><div class='gd-sec'><span class='gd-tag'>Jago・Kurang jago</span><span class='gd-jp'>上手</span> (jago, pandai), <span class='gd-jp'>下手</span> (kurang jago)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは歌が上手です。</span>(Pak Tanaka jago menyanyi.)</div><div class='gd-sec'><span class='gd-tag'>Paham・Bisa</span><span class='gd-jp'>わかります</span> (paham), <span class='gd-jp'>できます</span> (bisa)</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語がわかります。</span>(Aku paham bahasa Korea.)</div><div class='gd-ex-line'>・<span class='gd-jp'>テニスができます。</span>(Aku bisa main tenis.)</div><div class='gd-sec'><span class='gd-tag'>Ingin</span><span class='gd-jp'>ほしい</span> (ingin punya)</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいかばんがほしいです。</span>(Aku ingin tas baru.)</div><div class='gd-h'>Cara menyusunnya</div><div class='gd-sec'>Benda (kata benda) ＋ が ＋ kata-kata di atas.<br>Kalau mau menyebut siapa yang suka, taruh 「orang＋は」 di paling depan: <span class='gd-jp'>私は犬が好きです。</span>(Aku suka anjing.)<br>Di kalimat ini, <span class='gd-jp'>は</span> berarti 「yang sedang dibicarakan adalah aku」, sedangkan <span class='gd-jp'>が</span> berarti 「yang disukai adalah anjing」. Keduanya punya tugas sendiri-sendiri.<br>Mau tanya lawan bicara suka apa? Ganti bendanya dengan <span class='gd-jp'>何</span>: <span class='gd-jp'>何が好きですか。</span>(Kamu suka apa?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Jangan ikuti naluri bahasa Indonesia dengan memakai を. Yang benar <span class='gd-jp'>韓国語がわかります</span>, bukan 韓国語をわかります. Untuk 「suka」 juga sama, hafalkan saja <span class='gd-jp'>犬が好きです</span>.<br>・<span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>上手</span>, <span class='gd-jp'>下手</span> bukan kata kerja. Setelahnya pakai <span class='gd-jp'>です</span>, tidak bisa ditambah ます.<br>・Saat bilang 「tidak suka」, orang Jepang sering mengganti が dengan は: <span class='gd-jp'>魚は好きじゃありません。</span>(Kalau ikan, aku tidak suka.) Nuansanya 「yang lain sih oke, tapi yang ini tidak」, dan ini sangat natural.<br>・<span class='gd-jp'>上手</span> dipakai untuk memuji orang lain. Kalau kamu bilang 「aku jago ～」 tentang dirimu sendiri, kedengarannya seperti menyombongkan diri, jadi orang Jepang biasanya tidak memakainya begitu.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Yang paling gampang tertukar adalah <b>を</b> (objek). Lihat benda yang sama di depan kata yang berbeda:<br><span class='gd-jp'>日本語を勉強します。</span>(Aku belajar bahasa Jepang.): 「belajar」 adalah tindakan yang kamu lakukan, jadi pakai を.<br><span class='gd-jp'>日本語がわかります。</span>(Aku paham bahasa Jepang.): 「paham」 adalah kemampuanmu sendiri, jadi pakai が.<br><span class='gd-jp'>料理を作ります。</span>(Aku memasak.): tindakan, pakai を.<br><span class='gd-jp'>料理が上手です。</span>(Jago memasak.): kemampuan, pakai が.</div><div class='gd-warn'>Trik cepat: kalau itu tindakan yang 「dilakukan」 (makan, baca, buat, beli), pakai を. Kalau itu perasaan di hati atau kemampuan yang dimiliki (suka, tidak suka, jago, paham, bisa, ingin), pakai が.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Untuk pemakaian <span class='gd-jp'>ほしい</span>, lanjutkan ke 「<span class='gd-jp'>〜が欲しいです・〜たいです</span>」 untuk belajar cara bilang 「ingin punya ～」 dan 「ingin melakukan ～」.</div>","n5-33":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「に」 yang ini sama seperti <b>「di」</b> dalam bahasa Indonesia, untuk memberi tahu <b>di mana</b> ada orang atau benda. Dalam bahasa Indonesia kita bilang 「Di kulkas ada susu」. Dalam bahasa Jepang, tambahkan に setelah 「kulkas」, lalu tutup kalimat dengan あります atau います.</div><div class='gd-h'>Cara menyusunnya</div><div class='gd-sec'>Pola: <b>tempat＋に＋orang／benda＋が＋あります／います</b></div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳があります。</span>(Di kulkas ada susu.)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に先生がいます。</span>(Di kelas ada guru.)</div><div class='gd-sec'><b>Pakai あります atau います?</b> Lihat apakah benda itu bisa bergerak sendiri: manusia dan hewan pakai <span class='gd-jp'>います</span>; benda mati dan tumbuhan pakai <span class='gd-jp'>あります</span>.</div><div class='gd-h'>Cara menyebut posisi</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang 「di atas meja」, 「di dalam kotak」, 「di depan stasiun」. Dalam bahasa Jepang, posisi disambung dengan 「の」 dan urutannya terbalik, lalu ditambah に:<br><span class='gd-jp'>机の上に</span> (di atas meja), <span class='gd-jp'>箱の中に</span> (di dalam kotak), <span class='gd-jp'>駅の前に</span> (di depan stasiun), <span class='gd-jp'>机の下に</span> (di bawah meja)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前にコンビニがあります。</span>(Di depan stasiun ada minimarket.)</div><div class='gd-h'>Dua bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Di sana ada apa</span>Tempat di depan, lalu hal yang mau dibicarakan pakai が.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園に子供がいます。</span>(Di taman ada anak-anak.)</div><div class='gd-sec'><span class='gd-tag'>Benda itu ada di mana</span>Kalau mau bilang 「sesuatu ada di mana」, taruh bendanya di depan dengan は, dan に tetap mengikuti tempat.</div><div class='gd-ex-line'>・<span class='gd-jp'>猫は机の下にいます。</span>(Kucing ada di bawah meja.)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>(Toilet di mana?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・あります／います di sini berarti orang atau benda 「berada」 di tempat itu. Kalau あります berarti acara atau kejadian 「berlangsung」 (contoh: <span class='gd-jp'>パーティーがあります</span>), tempatnya pakai で: <span class='gd-jp'>明日、学校で試験があります。</span>(Besok di sekolah ada ujian.)<br>・Dalam bahasa Indonesia semuanya pakai 「di」, tapi 「bermain di taman」 adalah tindakan, jadi pakai で: <span class='gd-jp'>公園で遊びます</span>, bukan 公園に遊びます.<br>・Manusia dan hewan tidak bisa pakai あります: yang benar <span class='gd-jp'>先生がいます</span>, bukan 先生があります.<br>・Tempat untuk 「tinggal di」 juga pakai に: <span class='gd-jp'>姉は大阪に住んでいます。</span>(Kakak perempuanku tinggal di Osaka.)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Yang paling gampang tertukar adalah <b>で (tempat melakukan tindakan)</b>. Tempatnya sama-sama taman, jadi lihat apa yang dibicarakan kalimatnya:<br><span class='gd-jp'>公園に子供がいます。</span>(Di taman ada anak-anak: hanya bilang anak-anak ada di sana)<br><span class='gd-jp'>公園で子供が遊んでいます。</span>(Anak-anak bermain di taman: melakukan tindakan di sana)<br><span class='gd-jp'>公園でお祭りがあります。</span>(Di taman ada festival: acara diadakan di sana)</div><div class='gd-warn'>Trik cepat: lihat akhir kalimatnya dulu. Kalau あります／います (juga 住んでいます) menyatakan orang atau benda 「berada di sana」, pakai に. Kalau tindakan seperti makan, bermain, membeli, bekerja, atau あります untuk acara yang 「diadakan」 (contoh: <span class='gd-jp'>ホテルでパーティーがあります</span>), pakai で.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>「Ungkapan keberadaan」 akan mengajarkan cara bilang 「tidak ada apa-apa」 dan 「tidak ada siapa pun」: <span class='gd-jp'>部屋に誰もいません。</span>(Di kamar tidak ada siapa pun.)</div>","n5-35":"<div class='gd-h'>Pahami dalam Satu Kalimat</div><div class='gd-sec'>Kalau kamu taruh 「が」 di akhir sebuah kalimat, artinya sama dengan <b>「……, tetapi/tapi……」</b> dalam bahasa Indonesia. Sebutkan satu hal dulu, lalu sambung dengan hal lain yang tidak sesuai harapan. Misalnya 「Toko ini mahal, tapi enak」, dalam bahasa Jepang jadi <span class='gd-jp'>この店は高いですが、おいしいです。</span></div><div class='gd-h'>Cara Menyambungnya</div><div class='gd-sec'>Kalimat di depan harus <b>diucapkan lengkap sampai selesai</b>, di N5 biasanya diakhiri 「です」 atau 「ます」. Setelah itu tambahkan が, beri koma, lalu sambung dengan kalimat berikutnya.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>雨です</span> → <span class='gd-jp'>雨ですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたいですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強しました</span> → <span class='gd-jp'>勉強しましたが、</span></span><br>Kalau bagian depan memakai 「です・ます」, bagian belakang juga harus memakai 「です・ます」. Tingkat kesopanan satu kalimat harus sama.</div><div class='gd-h'>Kapan Dipakai</div><div class='gd-sec'><span class='gd-tag'>Pertentangan</span>Dua hal yang arahnya berlawanan, atau hasilnya berbeda dari yang kamu harapkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいですが、おもしろいです。</span>(Bahasa Jepang itu sulit, tapi menarik)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でしたが、出かけました。</span>(Kemarin hujan, tapi aku tetap pergi keluar)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲みましたが、まだ頭が痛いです。</span>(Sudah minum obat, tapi kepalaku masih sakit)</div><div class='gd-sec'><span class='gd-tag'>Pembuka</span>Sebelum meminta tolong atau bertanya, ucapkan dulu 「すみませんが」 atau 「失礼ですが」 sebagai pembuka. Di sini が tidak berarti 「tapi」. Fungsinya cuma membuat nada lebih sopan, mirip 「Permisi, boleh tanya……」 dalam bahasa Indonesia.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみませんが、駅はどこですか。</span>(Permisi, stasiunnya di mana ya?)</div><div class='gd-ex-line'>・<span class='gd-jp'>失礼ですが、お名前は？</span>(Maaf, boleh tahu nama Anda?)</div><div class='gd-h'>Bagian yang Sering Salah</div><div class='gd-warn'>・Dalam bahasa Indonesia, 「meskipun/walaupun」 diletakkan di <b>awal kalimat</b>, sedangkan が dalam bahasa Jepang justru ada di <b>akhir klausa pertama</b>. Jangan mencari kata di awal kalimat yang cocok dengan 「meskipun」.<br>・Dalam satu kalimat bisa muncul dua が: <span class='gd-jp'>雨が降っていますが、行きます。</span>(Meskipun sedang hujan, aku tetap akan pergi). が pertama menempel setelah kata benda 「雨」, jadi itu が penanda subjek. が kedua menempel setelah klausa lengkap 「降っています」, nah itu yang berarti 「tapi」. Cara membedakannya gampang: lihat apakah di depan が ada <b>satu kata benda</b> atau <b>satu klausa yang sudah selesai</b>.<br>・Kalau sudah pakai が, kamu tidak perlu menambah でも. Cukup bilang <span class='gd-jp'>高いですが、おいしいです。</span><br>・Kalau mengobrol dengan teman lalu bilang 「高いが、おいしい」, yaitu langsung menyambung が tanpa です・ます, kedengarannya kaku seperti bahasa tulis. Antar teman, けど lebih natural.</div><div class='gd-h'>Bedakan dari yang Mirip</div><div class='gd-sec'>Untuk 「mahal, tapi enak」 yang sama, ada tiga cara ucap yang umum:<br><b>が</b>: <span class='gd-jp'>高いですが、おいしいです。</span>Lebih formal, cocok untuk bicara dengan tamu atau orang yang lebih tua, juga untuk menulis surat.<br><b>けど</b>: <span class='gd-jp'>高いけど、おいしい。</span>Ini bahasa lisan dan paling sering terdengar dalam obrolan sehari-hari. Boleh juga ditambah です: <span class='gd-jp'>高いですけど、おいしいです。</span><br><b>でも</b>: <span class='gd-jp'>高いです。でも、おいしいです。</span>Kalimat pertama diakhiri dengan titik dulu, baru kalimat berikutnya dibuka dengan でも.</div><div class='gd-warn'>Tips membedakan: kalau disambung di belakang kalimat dan ingin terdengar agak formal, pakai が. Kalau ngobrol dengan teman, pakai けど. Kalau kalimat sebelumnya sudah selesai dan kamu mau membuat kontras di awal kalimat baru, pakai でも.</div><div class='gd-h'>Setelah Ini Belajar Apa?</div><div class='gd-sec'>Lanjut ke 「けど」. Artinya sama dengan が, tapi lebih santai, dan hampir selalu dipakai saat bicara dengan teman.</div>","n5-36":"<div class='gd-h'>Pahami dalam Satu Kalimat</div><div class='gd-sec'>「けど」 kurang lebih sama dengan 「..., tapi...」 dalam bahasa Indonesia. Ada dua cara pakainya. Pertama, <b>dua bagian yang artinya berlawanan</b>, misalnya 「Kecil, tapi praktis」. Kedua, <b>sebagai pembuka</b> untuk memunculkan topik, seperti 「Maaf, aku mau tanya sebentar……」. Orang Jepang memakainya terus dalam percakapan sehari-hari.</div><div class='gd-h'>Kapan Dipakai</div><div class='gd-sec'><span class='gd-tag'>Berlawanan</span>Bagian depan menyebutkan satu hal, bagian belakang menyebutkan hal yang berlawanan atau tak terduga.</div><div class='gd-ex-line'>・<span class='gd-jp'>小さいけど、使いやすいです。</span>(Kecil, tapi mudah dipakai)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いけど、おいしいです。</span>(Toko ini murah, tapi enak)</div><div class='gd-sec'><span class='gd-tag'>Pembuka</span>Kamu jelaskan dulu latar belakangnya, baru mengajukan pertanyaan, ajakan, atau permintaan. Di sini けど <b>tidak berarti 「tapi」</b>, lebih mirip 「Jadi begini……」. Kalimat berikutnya juga sering tidak diucapkan sama sekali, dan lawan bicara yang melanjutkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日映画を見に行くけど、一緒に行かない？</span>(Besok aku mau nonton film, mau ikut nggak?)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですけど…</span>(Permisi, saya mau ke stasiun……)</div><div class='gd-ex-line'>・<span class='gd-jp'>もしもし、田中ですけど…</span>(Halo, ini Tanaka……)</div><div class='gd-h'>Cara Menyambungnya</div><div class='gd-sec'>けど menempel di <b>akhir kalimat sebelumnya</b>, jadi bagian depannya harus berupa kalimat yang lengkap.<br><b>Untuk bicara dengan teman (tanpa です・ます)</b>:<br>Kata kerja dan kata sifat-い langsung ditambah けど: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くけど</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いけど</span></span><br>Kata benda dan kata sifat-な harus ditambah 「だ」 dulu: <span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だけど</span></span><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいだけど</span></span></div><div class='gd-sec'><b>Cara bicara yang sopan</b>: pakai です・ます di depan, lalu tambahkan けど.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますけど</span></span><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですけど</span></span><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですけど</span></span><br>Hafalkan 「<span class='gd-jp'>〜たいんですけど…</span>」 sebagai satu frasa tetap. Kamu akan memakainya saat bertanya jalan, meminta tolong, atau bicara di konter.</div><div class='gd-h'>Bagian yang Sering Salah</div><div class='gd-warn'>・Lupa menambah だ pada kata benda dan kata sifat-な: <span class='gd-jp'>学生けど</span>×, yang benar <span class='gd-jp'>学生だけど</span>. Begitu juga <span class='gd-jp'>静かけど</span>×, yang benar <span class='gd-jp'>静かだけど</span>. Sebaliknya, kata sifat-い <b>tidak boleh</b> ditambah だ: <span class='gd-jp'>高いだけど</span>×, langsung saja <span class='gd-jp'>高いけど</span>.<br>・Dalam bahasa Indonesia, 「tetapi」 bisa diletakkan di awal kalimat kedua, sedangkan けど dalam bahasa Jepang menempel di <b>ujung kalimat pertama</b>. Kalau mau membuka kalimat kedua dengan 「tapi」, pakai <span class='gd-jp'>でも</span> (dibandingkan di bawah).<br>・Kalimat yang berhenti di 「〜けど…」 bukan berarti omongannya belum selesai. Itu cara orang Jepang bersikap <b>sopan dan tidak menyudahi kalimat dengan tegas</b>. Saat diterjemahkan, jangan dipaksa jadi 「tetapi」.<br>・けど itu bahasa lisan, natural untuk mengobrol atau bicara dengan pegawai toko. Untuk laporan atau situasi formal, 「が」 lebih aman.<br>・<span class='gd-jp'>けれど</span> dan <span class='gd-jp'>けれども</span> artinya sama, makin panjang makin formal.</div><div class='gd-h'>Bedakan dari yang Mirip</div><div class='gd-sec'>Untuk hal yang sama: bajunya mahal, tapi tetap dibeli.<br><b>けど</b> = nada bicara sehari-hari: <span class='gd-jp'>高いけど、買いました。</span><br><b>が</b> = lebih formal, untuk tulisan atau situasi resmi: <span class='gd-jp'>高いですが、買いました。</span><br><b>でも</b> = kalimat pertama diselesaikan dulu, baru kalimat kedua dibuka dengan 「tapi」: <span class='gd-jp'>高いです。でも、買いました。</span></div><div class='gd-sec'>Untuk pemakaian sebagai pembuka juga sama. Kalau bicara dengan atasan atau orang yang lebih tua dan ingin lebih sopan, ganti けど dengan が: <span class='gd-jp'>ちょっと聞きたいんですが…</span>(Saya mau bertanya sedikit……)</div><div class='gd-warn'>Tips membedakan: untuk bicara sehari-hari pakai けど. Untuk situasi formal atau tulisan pakai が. Kalau mau memisahkan jadi dua kalimat dan membuka kalimat kedua dengan 「tapi」, pakai でも.</div>","n5-37":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「に」yang ini dipakai untuk menjelaskan <b>tujuan kamu pergi／datang／pulang, yaitu untuk melakukan apa</b>. Dalam bahasa Indonesia kita bilang “pergi membeli sesuatu” atau “datang untuk main”. Dalam bahasa Jepang, kegiatan yang mau dilakukan ditaruh di depan, lalu disambung dengan 「に行きます」「に来ます」: <span class='gd-jp'>買いに行きます</span> (pergi membeli), <span class='gd-jp'>遊びに来ます</span> (datang untuk main).</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Ubah dulu kata kerja ke bentuk ます, buang 「ます」-nya, lalu tambahkan 「に」.<br><span class='gd-pair'><span class='gd-jp'>買います</span> → buang ます → <span class='gd-jp'>買いに行きます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べに行きます</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見に行きます</span></span><span class='gd-pair'><span class='gd-jp'>会います</span> → <span class='gd-jp'>会いに行きます</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>お土産を買いに行きます。</span>(Pergi membeli oleh-oleh)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、友達に会いに行きます。</span>(Akhir pekan ini aku mau menemui temanku)</div><div class='gd-ex-line'>・<span class='gd-jp'>昼ごはんを食べに家へ帰ります。</span>(Pulang ke rumah untuk makan siang)</div><div class='gd-ex-line'>・<span class='gd-jp'>書類を届けに来ました。</span>(Aku datang untuk mengantarkan dokumen)</div><div class='gd-sec'><span class='gd-tag'>Kata benda</span>Kata benda yang artinya sudah berupa “satu kegiatan”, seperti <span class='gd-jp'>買い物</span>, <span class='gd-jp'>散歩</span>, <span class='gd-jp'>旅行</span>, <span class='gd-jp'>食事</span>, bisa langsung diberi 「に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートへ買い物に行きます。</span>(Pergi belanja ke pusat perbelanjaan)</div><div class='gd-ex-line'>・<span class='gd-jp'>公園へ散歩に行きませんか。</span>(Mau jalan-jalan ke taman?)</div><div class='gd-h'>Kalau ada tempat dan tujuan dalam satu kalimat</div><div class='gd-sec'>Urutannya biasanya: <b>tempat＋へ　→　tujuan＋に　→　行きます</b>.<br><span class='gd-jp'>図書館へ本を借りに行きます。</span>(Pergi ke perpustakaan untuk meminjam buku)<br>Kalau setelah tempat kamu pakai 「へ」, tidak akan ada dua に yang berdekatan dengan tujuan 「に」, jadi kalimatnya terdengar lebih jelas.</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Di depan harus <b>bentuk ます tanpa ます</b>, tidak boleh bentuk kamus: yang benar <span class='gd-jp'>買いに行きます</span>, bukan 「買うに行きます」.<br>・Di belakang hanya bisa <b>kata kerja perpindahan</b>, yang paling umum <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>. Kalimat yang tidak ada hubungannya dengan perpindahan, misalnya “membaca buku untuk belajar bahasa Jepang”, tidak bisa memakai に ini.<br>・Dalam bahasa Indonesia kita bilang “pergi + beli”, sedangkan dalam bahasa Jepang “beli + pergi (買い＋に行く)”, jadi <b>urutannya terbalik</b>. Jangan sampai bilang 「行きに買います」.<br>・Partikel 「を」 di depan kata kerja aslinya tetap dipertahankan: <span class='gd-jp'>お土産を買いに行きます</span>.<br>・<span class='gd-jp'>遊びに来てください。</span>(Main ke sini ya) adalah ajakan yang sering sekali diucapkan orang Jepang, jadi hafalkan saja satu kalimat utuh.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama 「に行きます」, tetapi <b>apa yang ada di depan に</b> menentukan artinya:<br><b>tempat＋に</b> = pergi <b>ke mana</b>: <span class='gd-jp'>デパートに行きます。</span>(Pergi ke pusat perbelanjaan)<br><b>kegiatan＋に</b> = pergi <b>untuk apa</b>: <span class='gd-jp'>買い物に行きます。</span>(Pergi belanja)<br>Kalau digabung: <span class='gd-jp'>デパートへ買い物に行きます。</span>(Pergi belanja ke pusat perbelanjaan)</div><div class='gd-warn'>Trik menilai: kalau di depan に ada “tempat”, artinya pergi ke mana; kalau di depan に ada “kata kerja tanpa ます” atau kegiatan seperti 買い物, 散歩, artinya pergi untuk melakukan apa.</div>","n5-39":"<div class='gd-h'>Inti dalam satu kalimat</div><div class='gd-sec'>「ね」mirip dengan <b>“ya?” “kan?” “ya kan”</b> dalam bahasa Indonesia: dipakai untuk hal yang <b>lawan bicara juga tahu dan rasakan</b>, untuk mencari kesamaan perasaan atau memastikan sesuatu.<br>「よ」mirip dengan <b>“lho” “tahu”</b>: dipakai untuk hal yang <b>belum diketahui lawan bicara</b>, saat kamu ingin memberi tahu atau mengingatkan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>ね: merasakan hal yang sama</span>Kalian berdua sama-sama melihat, merasakan, atau mencicipi hal yang sama, lalu kamu mengucapkannya untuk mencari kesamaan perasaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>いい天気ですね。</span>(Cuacanya bagus ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいですね。</span>(Kue ini enak ya)</div><div class='gd-sec'><span class='gd-tag'>ね: memastikan</span>Kamu kira-kira tahu, tetapi ingin memastikan pada lawan bicara bahwa ingatanmu tidak salah. Pelayan toko yang mengonfirmasi pesananmu juga memakainya begini.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みですね。</span>(Besok libur, kan?)</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒー二つですね。</span>(Kopi dua, ya?)</div><div class='gd-sec'><span class='gd-tag'>よ: memberi tahu</span>Hal yang kamu tahu tapi lawan bicara belum tahu, seperti rekomendasi atau berbagi kabar.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、安いですよ。</span>(Toko ini murah lho)</div><div class='gd-ex-line'>・<span class='gd-jp'>この番組、面白いですよ。</span>(Acara ini seru lho)</div><div class='gd-sec'><span class='gd-tag'>よ: mengingatkan</span>Hal yang belum disadari lawan bicara, supaya dia memperhatikannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう始まりますよ。</span>(Sudah mau mulai lho)</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が来ましたよ。</span>(Keretanya sudah datang lho)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang sekali: setelah kalimat selesai, <b>langsung taruh di paling belakang</b>.<br>Bentuk sopan: <span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいですね</span></span><span class='gd-pair'><span class='gd-jp'>始まります</span> → <span class='gd-jp'>始まりますよ</span></span><br>Bentuk santai ke teman juga sama, tinggal ditambahkan: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>いいね</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くよ</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨だね</span></span></div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・<b>Untuk hal yang mustahil diketahui lawan bicara, jangan pakai ね</b>. Kalau saat perkenalan diri kamu bilang 「私は台湾人ですね」, kedengarannya seperti bertanya “Aku orang Taiwan, kan?” pada lawan bicara, aneh sekali. Cukup katakan <span class='gd-jp'>私は台湾人です。</span><br>・<b>Nada よ lebih kuat</b>. Kalau kamu memakai よ saat mengoreksi guru atau atasan, misalnya 「それは違いますよ」, terdengar seperti kamu sedang menggurui. Saat bicara dengan orang yang lebih tua, lebih aman jangan terlalu sering memakai よ.<br>・Intonasi ね: <b>nada naik di akhir</b> berarti memastikan “kan?”; <b>datar atau turun</b> berarti berseru, seperti “wah, ～ banget ya”.<br>・Dalam bahasa Indonesia kita suka menambahkan “sih”, “dong”, “lho”, “deh”, tetapi dalam bahasa Jepang tidak perlu menambahkan di setiap kalimat. Saat sekadar menjelaskan sesuatu, tanpa tambahan apa pun juga sangat natural; kalau setiap kalimat diakhiri ね atau よ, justru terdengar berisik.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama “di luar sedang hujan”, pilihannya tergantung apakah lawan bicara sudah tahu atau belum:<br><b>ね</b> = lawan bicara juga melihatnya, kalian sama-sama berseru: <span class='gd-jp'>雨ですね。</span>(Hujan ya)<br><b>よ</b> = lawan bicara di dalam rumah dan tidak sadar, kamu memberi tahu: <span class='gd-jp'>雨ですよ。</span>(Di luar hujan lho)<br><b>か</b> = kamu sendiri sama sekali tidak tahu dan bertanya: <span class='gd-jp'>雨ですか。</span>(Apakah hujan?)</div><div class='gd-sec'>「ね」dan「か」sama-sama bisa menjadi kalimat tanya; bedanya ada atau tidaknya jawaban di benakmu:<br><span class='gd-jp'>明日は休みですか。</span>(Apakah besok libur?: tidak tahu, bertanya saja)<br><span class='gd-jp'>明日は休みですね。</span>(Besok libur, kan?: kira-kira tahu, memastikan)</div><div class='gd-warn'>Trik menilai: lawan bicara juga tahu → ね; lawan bicara belum tahu dan kamu ingin memberi tahu → よ; kamu sendiri tidak tahu → か.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Keduanya bisa digabung menjadi 「よね」, urutannya tetap よ di depan, tidak boleh 「ねよ」. Artinya “seingatku begitu, benar kan?”: <span class='gd-jp'>テストは明日ですよね。</span>(Ujiannya besok, kan?)</div>","n5-40":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Partikel bahasa Jepang mirip kata depan seperti “di” atau “pada” dalam bahasa Indonesia: <b>satu kata sering punya beberapa arti</b>. Kamu sudah belajar penggunaan paling dasar を、に、で、は、か. Di pelajaran ini kita kumpulkan <b>penggunaan umum lainnya</b>. Saat bertemu partikel, jangan hanya hafal satu arti. Lihat kata apa yang ada di depan dan belakangnya untuk menentukan artinya.</div><div class='gd-h'>を：tempat yang ditinggalkan, jalur yang dilalui</div><div class='gd-sec'><span class='gd-tag'>Tempat yang ditinggalkan</span>Untuk keluar dari suatu tempat, turun dari kendaraan, atau lulus, tempatnya memakai を. Biasanya muncul bersama <span class='gd-jp'>出る</span>、<span class='gd-jp'>降りる</span>、<span class='gd-jp'>卒業する</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に家を出ます。</span>（Aku keluar rumah jam 7）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（Aku turun dari kereta di stasiun berikutnya）</div><div class='gd-sec'><span class='gd-tag'>Jalur yang dilalui</span>Untuk gerakan yang berpindah tempat seperti berjalan, berlari, jalan-jalan, atau menyeberangi jembatan, jalur atau area yang dilalui memakai を.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、公園を散歩します。</span>（Setiap pagi aku jalan-jalan di taman）</div><div class='gd-ex-line'>・<span class='gd-jp'>この橋を渡ってください。</span>（Tolong seberangi jembatan ini）</div><div class='gd-h'>に：frekuensi, tempat jatuhnya sesuatu, menjadi</div><div class='gd-sec'><span class='gd-tag'>Frekuensi</span>Jangka waktu＋に＋jumlah kali＝berapa kali dalam sekian waktu.</div><div class='gd-ex-line'>・<span class='gd-jp'>1日に3回、薬を飲みます。</span>（Aku minum obat tiga kali sehari）</div><div class='gd-ex-line'>・<span class='gd-jp'>週に1回、プールへ行きます。</span>（Aku pergi ke kolam renang seminggu sekali）</div><div class='gd-sec'><span class='gd-tag'>Tempat jatuhnya sesuatu</span>Untuk menulis di atas sesuatu, duduk di atas sesuatu, atau memasukkan sesuatu, tempat yang akhirnya “disentuh atau menjadi tempat sesuatu berada” memakai に.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（Tolong tulis namamu di sini）</div><div class='gd-ex-line'>・<span class='gd-jp'>椅子に座ります。</span>（Duduk di kursi）</div><div class='gd-sec'><span class='gd-tag'>Menjadi</span>Kata benda＋になる＝menjadi ～.</div><div class='gd-ex-line'>・<span class='gd-jp'>将来、先生になりたいです。</span>（Di masa depan aku ingin jadi guru）</div><div class='gd-h'>で：cakupan, total</div><div class='gd-sec'><span class='gd-tag'>Cakupan</span>Untuk makna “paling ～ di antara ...”, cakupannya memakai で.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はクラスでいちばん背が高いです。</span>（Kakakku yang paling tinggi di kelas）</div><div class='gd-sec'><span class='gd-tag'>Total</span>Jumlah＋で＝dijumlahkan, totalnya. Sangat sering dipakai saat belanja.</div><div class='gd-ex-line'>・<span class='gd-jp'>全部でいくらですか。</span>（Totalnya berapa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごは3つで500円です。</span>（Apelnya tiga buah 500 yen）</div><div class='gd-h'>は：untuk kontras</div><div class='gd-sec'><span class='gd-tag'>Kontras</span>Saat dua hal dibandingkan, masing-masing diberi は. Artinya “kalau A begini, B lain ceritanya”.</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司は好きですが、刺身は苦手です。</span>（Aku suka sushi, tapi sashimi kurang cocok）</div><div class='gd-sec'>Meski hanya menyebut satu sisi, は tetap memberi kesan “yang lain beda lagi”:</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は飲みません。</span>（Kalau alkohol, aku tidak minum）</div><div class='gd-h'>か：memilih salah satu</div><div class='gd-sec'><span class='gd-tag'>Pilihan</span>AかB＝A atau B, pilih salah satu.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日か火曜日に来てください。</span>（Tolong datang hari Senin atau Selasa）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Naik kendaraan pakai に, turun pakai を: <span class='gd-jp'>電車に乗ります</span>、<span class='gd-jp'>電車を降ります</span>. Banyak orang memakai partikel yang sama untuk keduanya.<br>・“Jalur yang dilalui” pada を hanya cocok dengan gerakan yang berpindah tempat. Untuk hal yang dilakukan di satu tempat, seperti bermain di taman atau makan bekal, pakai で: <span class='gd-jp'>公園で遊びます</span>.<br>・Dalam bahasa Indonesia kita bilang “tulis di sini”, jadi refleksnya memakai で. Tapi menulis di kertas atau duduk di kursi berarti sesuatu “mendarat” di tempat itu, jadi pakai に: <span class='gd-jp'>ここに書いてください</span>.<br>・は untuk kontras tetap dibaca wa, bukan ha.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>か、と、や semuanya bisa menghubungkan dua benda, tapi artinya sangat berbeda. Contohnya saat membeli minuman:<br><span class='gd-jp'>コーヒーと紅茶を買いました。</span>（Aku beli kopi dan teh: dua-duanya dibeli）<br><span class='gd-jp'>コーヒーや紅茶を買いました。</span>（Aku beli kopi, teh, dan semacamnya: masih ada yang lain）<br><span class='gd-jp'>コーヒーか紅茶を買います。</span>（Aku akan beli kopi atau teh: hanya salah satu）</div><div class='gd-warn'>Trik cepatnya: kalau semuanya ada, pakai と. Kalau hanya menyebut beberapa contoh, pakai や. Kalau hanya memilih satu, pakai か.</div><div class='gd-h'>Bisa lanjut belajar setelah ini</div><div class='gd-sec'>で untuk cakupan bisa dipakai untuk bertanya “mana yang paling ～”: <span class='gd-jp'>果物の中で何がいちばん好きですか。</span>（Di antara buah-buahan, kamu paling suka apa?）</div>","n5-41":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「Bentuk ます」adalah verba yang sedang memakai <b>jaket sopan</b>. Di kamus kamu menemukan <span class='gd-jp'>飲む</span>, tapi kepada guru, pegawai toko, atau orang yang baru dikenal, kamu bilang <span class='gd-jp'>飲みます</span>. Pelajaran ini hanya melatih satu hal: <b>mengubah verba apa pun menjadi 〜ます</b>.</div><div class='gd-h'>Cara mengubahnya: lihat dulu verbanya kelompok berapa</div><div class='gd-sec'><span class='gd-tag'>Langkah 1</span><b>Pisahkan dulu kelompok 3 (する・来る)</b>. Hanya ada dua, langsung hafalkan:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>「Kata benda＋する」juga termasuk kelompok ini: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'><span class='gd-tag'>Langkah 2</span><b>Sisanya, tentukan kelompok 1 atau kelompok 2</b>:<br>・Kalau huruf terakhirnya <b>bukan る</b> (seperti <span class='gd-jp'>書く</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>会う</span>、<span class='gd-jp'>待つ</span>): pasti kelompok 1.<br>・Kalau berakhir る dan <b>bunyi sebelum る berakhir dengan a, u, o</b> (seperti か pada <span class='gd-jp'>分かる</span>, く pada <span class='gd-jp'>作る</span>, の pada <span class='gd-jp'>乗る</span>): pasti kelompok 1 (する dan 来る sudah dipisahkan di langkah 1, jadi tidak dihitung di sini).<br>・Kalau berakhir る dan <b>bunyi sebelum る berakhir dengan i, e</b> (seperti み pada <span class='gd-jp'>見る</span>, べ pada <span class='gd-jp'>食べる</span>, き pada <span class='gd-jp'>起きる</span>): sebagian besar kelompok 2. Tapi ada beberapa pengecualian yang sebenarnya kelompok 1 dan harus dihafal: <span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>.</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: ganti bunyi terakhir dengan bunyi baris 「い」 di baris yang sama, lalu tambahkan ます.<br>Lihat tabel gojūon: geser satu kotak dari baris う ke baris い (di tabel vertikal naik satu kotak, di tabel horizontal ke kiri satu kotak): う→い、く→き、ぐ→ぎ、す→し、つ→ち、ぬ→に、ぶ→び、む→み、る→り.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti き → <span class='gd-jp'>書きます</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会います</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話します</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぎます</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊びます</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: buang 「る」 di akhir, lalu tambahkan ます.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span><span class='gd-pair'><span class='gd-jp'>着る</span> → <span class='gd-jp'>着ます</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Kebiasaan sehari-hari dan hal yang akan dilakukan besok sama-sama memakai bentuk ます.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝パンを食べます。</span>（Setiap pagi aku makan roti）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日、日本語を勉強します。</span>（Setiap hari aku belajar bahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、友達が家に来ます。</span>（Besok temanku datang ke rumahku）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kamu tidak boleh langsung menambahkan ます setelah bentuk kamus: <span class='gd-jp'>飲むます</span> dan <span class='gd-jp'>行くます</span> itu salah. Ganti dulu bunyi terakhirnya.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span> kelihatannya seperti kelompok 2, padahal kelompok 1: yang benar <span class='gd-jp'>帰ります</span>, bukan 帰ます.<br>・<span class='gd-jp'>来ます</span> dibaca <b>きます</b>, bukan くます, dan juga bukan 来ります. <span class='gd-jp'>する</span> juga tidak menjadi すります.<br>・「す」 pada 「ます」 sering dibaca sangat ringan sehingga terdengar seperti “mas”. Ini pelafalan yang wajar, bukan salah dengarmu.</div><div class='gd-h'>Bisa lanjut belajar setelah ini</div><div class='gd-sec'>Bagian yang tersisa setelah ます dibuang (<span class='gd-jp'>飲み</span>、<span class='gd-jp'>食べ</span>、<span class='gd-jp'>し</span>) akan terus kamu pakai. Tinggal ganti ekornya, jadilah pola kalimat baru:<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>（sudah minum）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みましょう</span></span>（ayo minum）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたいです</span></span>（aku ingin minum）</div>","n5-42":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Bentuk て adalah <b>“sambungan”</b> kata kerja, seperti tonjolan di balok LEGO yang bisa disambung lagi dengan balok lain. Dalam bahasa Indonesia kita bilang “bangun, <b>lalu</b> cuci muka”. Dalam bahasa Jepang, kata “bangun” diubah ke bentuk て, lalu disambung dengan tindakan berikutnya. Banyak pola kalimat penting juga baru bisa dipakai kalau kata kerjanya sudah diubah ke bentuk て, misalnya “tolong ～” dan “sedang ～”. Makanya bentuk ini disebut <b>perubahan yang paling penting</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Merangkai tindakan</span>Menyambung beberapa tindakan sesuai urutannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、顔を洗います。</span>（Pagi hari bangun, lalu cuci muka）</div><div class='gd-sec'><span class='gd-tag'>Disambung pola kalimat</span>Diikuti kata lain, sehingga artinya jadi baru.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（Tolong tulis namamu di sini）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べています。</span>（Sekarang aku sedang makan）</div><div class='gd-sec'><span class='gd-tag'>Minta tolong ke teman</span>Saat ngobrol dengan teman, cukup pakai bentuk て untuk meminta dengan santai, seperti “tolong ～ dong”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと待って。</span>（Tunggu sebentar ya）</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: yang paling mudah. Hilangkan 「る」, lalu tambahkan 「て」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, langsung hafalkan)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span><br>Pola “kata benda + する” seperti <span class='gd-jp'>勉強する</span> juga sama：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強して</span></span></div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: lihat <b>huruf terakhirnya</b>, ada lima kelompok.<br><b>う・つ・る → って</b><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br><b>む・ぶ・ぬ → んで</b>（perhatikan で yang pakai tanda titik dua／dakuten）<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んで</span></span><br><b>く → いて</b><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span></span><br><b>ぐ → いで</b><br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いで</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br><b>す → して</b><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span></span><br><b>Satu-satunya pengecualian</b>：menurut aturan, <span class='gd-jp'>行く</span> seharusnya jadi 「行いて」, tetapi kenyataannya <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span>.</div><div class='gd-sec'>Rumus singkat, hafalkan sampai lancar：<b>うつる って、むぶぬ んで、く いて、ぐ いで、す して，行く是行って</b>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span> tampak seperti golongan 2, padahal golongan 1: bentuknya <span class='gd-jp'>帰って</span>, bukan 帰て.<br>・<span class='gd-jp'>行って</span> adalah pengecualian, tapi kata berakhiran く seperti <span class='gd-jp'>書いて</span> dan <span class='gd-jp'>聞いて</span> tetap mengikuti aturan. Jangan diubah semuanya jadi って.<br>・ぐ harus jadi <b>いで</b>, dan む・ぶ・ぬ harus jadi <b>んで</b>. Banyak yang salah menulis 泳いて atau 飲んて, jadi jangan lupa tanda dakuten-nya.<br>・「っ」kecil harus ditahan satu ketukan: <span class='gd-jp'>来て</span>（きて, datang）dan <span class='gd-jp'>切って</span>（きって, memotong）hanya beda satu ketukan itu, tapi artinya sama sekali berbeda.<br>・<span class='gd-jp'>来て</span> dibaca <b>きて</b>, bukan こて atau くて.<br>・Bentuk て sendiri tidak menunjukkan lampau atau sekarang. Yang menentukan adalah <b>kata kerja terakhir</b>：<span class='gd-jp'>シャワーを浴びて、寝ました。</span>（Aku mandi, lalu tidur）</div><div class='gd-h'>Setelah ini belajar apa?</div><div class='gd-sec'>Kalau bentuk て sudah lancar, <b>bentuk た (bentuk lampau biasa) hampir gratis</b>: aturannya persis sama, tinggal ganti て jadi た dan で jadi だ.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>Selanjutnya kamu bisa belajar 「～てください」（tolong ～）、「～ています」（sedang ～）、「～てから」（setelah ～）. Semuanya bergantung pada perubahan di materi ini.</div>","n5-43":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Bentuk kamus adalah <b>versi santai</b> dari 「〜ます」, dan itulah bentuk yang kamu temukan di kamus. Bentuk ない adalah <b>versi santai</b> dari 「〜ません」. Ke guru kamu bilang <span class='gd-jp'>行きます</span>／<span class='gd-jp'>行きません</span>, ke teman cukup <span class='gd-jp'>行く</span>／<span class='gd-jp'>行かない</span>. Artinya sama, hanya lebih santai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Ngobrol dengan teman dan keluarga</span>Sama seperti ます, dipakai untuk kebiasaan sekarang dan hal yang belum terjadi. Untuk bertanya, cukup naikkan nada di akhir kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、何時に起きる？</span>（Besok bangun jam berapa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に起きる。</span>（Bangun jam 7）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は学校に行かない。</span>（Hari ini aku tidak pergi ke sekolah）</div><div class='gd-ex-line'>・<span class='gd-jp'>私はお酒を飲まない。</span>（Aku tidak minum alkohol）</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Pertama, dari bentuk ます kembali ke bentuk kamus</b><br><b>Golongan 1 (kata kerja godan)</b>: huruf sebelum ます diganti dengan huruf baris う (deretan u) di baris yang sama.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → み diganti む → <span class='gd-jp'>飲む</span></span><span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span></span><span class='gd-pair'><span class='gd-jp'>歌います</span> → <span class='gd-jp'>歌う</span></span><span class='gd-pair'><span class='gd-jp'>帰ります</span> → <span class='gd-jp'>帰る</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>: ganti ます dengan る.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>起きます</span> → <span class='gd-jp'>起きる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br><b>Golongan 3 (hanya dua, langsung hafalkan)</b>：<span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span></div><div class='gd-sec'><b>Lalu, dari bentuk kamus ke bentuk ない</b><br><b>Golongan 1 (kata kerja godan)</b>: ganti huruf terakhir dengan huruf baris あ (deretan a) di baris yang sama, lalu tambahkan ない.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かない</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たない</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らない</span></span><br>Kalau berakhiran 「う」, <b>diganti 「わ」</b>, bukan 「あ」：<br><span class='gd-pair'><span class='gd-jp'>買う</span> → う diganti わ → <span class='gd-jp'>買わない</span></span><span class='gd-pair'><span class='gd-jp'>歌う</span> → <span class='gd-jp'>歌わない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>: hilangkan る, lalu tambahkan ない.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きない</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>Golongan 3 (langsung hafalkan)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>Pola “kata benda + する” juga sama：<span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話しない</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata berakhiran 「う」 tidak boleh jadi 「あない」: bentuknya <span class='gd-jp'>買わない</span>, bukan 買あない.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span> tampak seperti golongan 2, padahal golongan 1: bentuknya <span class='gd-jp'>帰らない</span>, bukan 帰ない.<br>・来る punya tiga cara baca yang harus dibedakan：<span class='gd-jp'>来る</span> dibaca くる, <span class='gd-jp'>来ます</span> dibaca きます, <span class='gd-jp'>来ない</span> dibaca こない.<br>・Bentuk negatif dari <span class='gd-jp'>ある</span>（ada, berada）adalah <span class='gd-jp'>ない</span>, bukan あらない：<span class='gd-jp'>お金がない。</span>（Tidak punya uang）<br>・Bentuk ない artinya “tidak (melakukan)”, bukan “tidak bisa”：<span class='gd-jp'>食べない</span> artinya “aku tidak makan”, bukan “aku tidak bisa makan”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk kalimat yang sama, “Besok aku tidak datang”, pilihannya tergantung kamu bicara dengan siapa：<br>Ke guru atau atasan：<span class='gd-jp'>明日は来ません。</span><br>Ke teman atau keluarga：<span class='gd-jp'>明日は来ない。</span><br>Artinya sama persis, bedanya hanya tingkat kesopanan. Memakai <span class='gd-jp'>来ない</span> ke orang yang lebih tua bisa dianggap tidak sopan. Sebaliknya, terus memakai <span class='gd-jp'>来ません</span> ke teman dekat akan terasa kaku dan berjarak.</div><div class='gd-warn'>Tips menentukan: <span class='gd-jp'>ます</span> berpasangan dengan bentuk kamus, <span class='gd-jp'>ません</span> berpasangan dengan bentuk ない. Pikirkan dulu lawan bicaramu siapa, baru pilih pasangan yang cocok.</div><div class='gd-h'>Setelah ini belajar apa?</div><div class='gd-sec'>Bentuk kamus dan bentuk ない masih bisa disambung dengan banyak tata bahasa lain, misalnya untuk meminta orang lain tidak melakukan sesuatu：<span class='gd-jp'>ここで写真を撮らないでください。</span>（Tolong jangan memotret di sini）. Langkah berikutnya, kamu bisa belajar bentuk lampau：<span class='gd-jp'>行った</span>／<span class='gd-jp'>行かなかった</span>.</div>","n5-44":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bentuk た adalah <b>versi santai</b> dari 「〜ました」, dan bentuk なかった adalah <b>versi santai</b> dari 「〜ませんでした」. Ke guru kamu bilang 「<span class='gd-jp'>昨日、映画を見ました</span>」, ke teman cukup 「<span class='gd-jp'>昨日、映画を見た</span>」. Artinya sama-sama \"kemarin aku nonton film\", hanya saja yang ini lebih santai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Ngobrol soal masa lalu dengan orang dekat</span>Untuk menceritakan hal yang sudah terjadi di antara teman atau keluarga.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、渋谷で友達に会った。</span>(Kemarin aku bertemu temanku di Shibuya)</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べなかった。</span>(Tadi pagi aku tidak makan apa-apa)</div><div class='gd-sec'><span class='gd-tag'>Bicara sendiri, menulis buku harian</span>Saat tidak ada lawan bicara yang perlu dihormati.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、傘を忘れた。</span>(Ah, payungku ketinggalan)</div><div class='gd-sec'><span class='gd-tag'>Dipakai dalam pola tata bahasa lain</span>Banyak pola tata bahasa yang harus diawali bentuk た, jadi bagian ini wajib kamu kuasai.</div><div class='gd-h'>Cara membentuk bentuk た: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Kalau kamu sudah hafal bentuk て, ini paling gampang</b>: ganti 「て」 pada bentuk て dengan 「た」, dan 「で」 dengan 「だ」. Selesai.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: lihat bunyi terakhirnya, lalu ubah seperti di bawah ini.<br>Berakhiran う・つ・る → った：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待った</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰った</span></span><br>Berakhiran ぬ・む・ぶ → んだ：<span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んだ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んだ</span></span><br>Berakhiran く → いた：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><br>Berakhiran ぐ → いだ：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><br>Berakhiran す → した：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>Satu-satunya pengecualian: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span> (meski berakhiran く, bentuknya bukan 行いた)</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「た」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きた</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, langsung hafalkan)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>Cara membentuk bentuk なかった</div><div class='gd-sec'>Ubah dulu ke bentuk ない, lalu ganti 「ない」 dengan 「なかった」. Trik ini berlaku untuk ketiga golongan.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span> → <span class='gd-jp'>会わなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span> → <span class='gd-jp'>しなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない） → <span class='gd-jp'>来なかった</span>（こなかった）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はどこにも行かなかった。</span>(Kemarin aku tidak pergi ke mana-mana)</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Bentuk た dari <span class='gd-jp'>行く</span> adalah <span class='gd-jp'>行った</span>, bukan 行いた.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>知る</span> tampak seperti golongan 2, padahal golongan 1: bentuknya <span class='gd-jp'>帰った</span>, <span class='gd-jp'>走った</span>, bukan 帰た atau 走た.<br>・<span class='gd-jp'>来た</span> dibaca <b>きた</b>, sedangkan <span class='gd-jp'>来なかった</span> dibaca <b>こなかった</b>. Kanji yang sama, bacaannya berbeda.<br>・Bentuk negatif <span class='gd-jp'>ある</span> langsung <span class='gd-jp'>ない</span> (tidak ada 「あらない」), dan bentuk lampaunya <span class='gd-jp'>なかった</span>: <span class='gd-jp'>時間がなかった。</span>(Waktu itu tidak ada waktu)<br>・\"Belum makan\" dalam bahasa Indonesia bukan <span class='gd-jp'>食べなかった</span>. なかった berarti \"waktu itu tidak melakukannya\", urusannya sudah lewat. Untuk \"sampai sekarang belum\", katakan <span class='gd-jp'>まだ食べていない</span>.<br>・Bentuk た dan なかった adalah gaya bicara antarteman. Kepada orang yang lebih tua, akhiri kalimat masa lalu dengan 「〜ました」 atau 「〜ませんでした」.</div><div class='gd-h'>Bedakan dari bentuk yang mirip</div><div class='gd-sec'><b>Bentuk た vs ました</b>: artinya persis sama, bedanya hanya pada siapa kamu bicara.<br><span class='gd-jp'>昨日、映画を見ました。</span>(Ke guru: kemarin saya nonton film)<br><span class='gd-jp'>昨日、映画を見た。</span>(Ke teman: kemarin aku nonton film)<br>Negatifnya juga sama: <span class='gd-jp'>行きませんでした</span> dan <span class='gd-jp'>行かなかった</span> sama-sama berarti \"tidak pergi\"; yang pertama sopan, yang kedua lebih santai.</div><div class='gd-sec'><b>た vs て</b>: beda satu bunyi saja, tapi fungsinya sama sekali berbeda. 「た」 mengakhiri kalimat dan menyatakan sesuatu sudah dilakukan; 「て」 berarti kalimat belum selesai dan masih akan disambung, atau dipakai untuk meminta tolong.<br><span class='gd-jp'>ご飯を食べた。</span>(Aku sudah makan)<br><span class='gd-jp'>ご飯を食べて、すぐ寝た。</span>(Setelah makan, aku langsung tidur)</div><div class='gd-warn'>Tips menentukan: kalimat berhenti di sini dan kejadiannya sudah lewat → た; masih ada lanjutan kalimat → て; bicara dengan orang yang lebih tua atau tamu → kembali ke ました, ませんでした.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Tambahkan 「り」 setelah bentuk た, jadi 「〜たり〜たりします」 (melakukan ini dan itu secara bergantian): <span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>(Akhir pekan biasanya aku nonton film, belanja, dan sebagainya)<br>Bentuk た + 「あとで」 = setelah melakukan ～: <span class='gd-jp'>ご飯を食べたあとで、散歩します。</span>(Setelah makan, aku jalan-jalan)</div>","n5-45":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bentuk biasa (普通形) adalah <b>gaya santai</b> yang didapat dengan membuang 「です・ます」, sekaligus bentuk dasar yang harus ada di depan banyak pola kalimat. Setiap kata punya empat wujud, kira-kira seperti \"pergi / tidak pergi / sudah pergi / tidak pergi (waktu itu)\": <b>positif sekarang, negatif sekarang, positif lampau, negatif lampau</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bicara dengan orang dekat</span>Antara keluarga atau teman, kamu tidak memakai ます, langsung pakai bentuk biasa.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見た。</span>(Kemarin aku nonton film)</div><div class='gd-sec'><span class='gd-tag'>Dipakai dalam pola kalimat</span>Meski seluruh kalimatnya sopan, bagian tengahnya sering harus diubah dulu ke bentuk biasa sebelum disambung dengan pola berikutnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>(Kurasa besok akan hujan)</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b><br>Negatif: ubah bunyi terakhir ke baris 「あ」 yang sama, lalu tambahkan ない.<span class='gd-pair'><span class='gd-jp'>行く</span> → く jadi か → <span class='gd-jp'>行かない</span></span><br>Lampau: caranya sama dengan bentuk て, hanya saja て diganti た.<span class='gd-pair'><span class='gd-jp'>行って</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>Negatif lampau: ganti 「い」 pada ない dengan 「かった」.<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかった</span></span><br>Lihat satu set lengkap: <span class='gd-jp'>買う／買わない／買った／買わなかった</span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: paling mudah, buang 「る」 lalu tambahkan ない, た, なかった.<br><span class='gd-jp'>食べる／食べない／食べた／食べなかった</span><br><span class='gd-jp'>見る／見ない／見た／見なかった</span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, langsung hafalkan)</b><br><span class='gd-jp'>する／しない／した／しなかった</span><br><span class='gd-jp'>来る／来ない／来た／来なかった</span>（くる／こない／きた／こなかった）<br>Pola 「kata benda + する」 seperti <span class='gd-jp'>勉強する</span> berubah mengikuti する: <span class='gd-jp'>勉強しない</span>, <span class='gd-jp'>勉強した</span>, <span class='gd-jp'>勉強しなかった</span>.</div><div class='gd-h'>Cara mengubah kata sifat dan kata benda</div><div class='gd-sec'><b>Kata sifat-い</b>: untuk negatif, ganti い terakhir dengan くない; untuk lampau, ganti い dengan かった.<br><span class='gd-jp'>高い／高くない／高かった／高くなかった</span></div><div class='gd-sec'><b>Kata sifat-な</b>: ditambah だ, じゃない, だった, じゃなかった.<br><span class='gd-jp'>静かだ／静かじゃない／静かだった／静かじゃなかった</span></div><div class='gd-sec'><b>Kata benda</b>: cara ubahnya persis sama dengan kata sifat-な.<br><span class='gd-jp'>学生だ／学生じゃない／学生だった／学生じゃなかった</span></div><div class='gd-warn'>Temuan kecil: baik kata kerja, kata sifat, maupun kata benda, bentuk negatifnya selalu berakhir 「ない」, dan semuanya berubah ke lampau dengan trik yang sama: <span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかった</span></span>. Kalau trik ini sudah kamu pegang, bentuk keempat (negatif lampau) hampir tidak perlu dihafal terpisah.</div><div class='gd-h'>Hafalkan sambil dibandingkan dengan ます・です</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><br><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span><br>Kata sifat-い paling gampang, cukup buang です: <span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span><br>Untuk kata sifat-な dan kata benda, です diganti だ: <span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span></div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Pada kata kerja golongan 1 yang berakhiran う, bentuk negatifnya berubah jadi 「わ」: <span class='gd-jp'>買わない</span>, bukan 買あない.<br>・Negatif dari <span class='gd-jp'>ある</span> adalah <span class='gd-jp'>ない</span>, bukan あらない.<br>・Lampau dari <span class='gd-jp'>行く</span> adalah <span class='gd-jp'>行った</span>, bukan 行いた.<br>・Begitu berubah bentuk, <span class='gd-jp'>いい</span> harus diganti jadi awalan よ: <span class='gd-jp'>よくない</span>, <span class='gd-jp'>よかった</span>, <span class='gd-jp'>よくなかった</span>.<br>・<span class='gd-jp'>きれい</span> dan <span class='gd-jp'>有名</span> tampak seperti kata sifat-い, padahal kata sifat-な: katakan <span class='gd-jp'>きれいじゃない</span>, bukan きれくない.<br>・Kata sifat-い tidak boleh ditambah だ: cukup <span class='gd-jp'>高い</span>, jangan 高いだ.<br>・Kata benda dan kata sifat-な yang diakhiri 「だ」 langsung terdengar agak kaku. Saat ngobrol dengan teman, だ sering dibuang atau ditambah よ di belakangnya, misalnya <span class='gd-jp'>学生だよ</span>.<br>・Saat bertanya ke teman dengan bentuk biasa, biasanya か tidak dipakai; cukup naikkan intonasi di akhir kalimat: <span class='gd-jp'>明日、来る？</span>(Kamu datang besok?)</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Saat bentuk biasa dipakai dalam pola kalimat, perhatikan 「だ」 pada kata benda dan kata sifat-な: kadang dipertahankan, kadang dibuang, kadang diganti な.<br><span class='gd-jp'>静かだと思う。</span>(Kurasa tempatnya tenang: だ dipertahankan)<br><span class='gd-jp'>静かでしょう。</span>(Pasti tenang, ya: だ dibuang)<br><span class='gd-jp'>学生なの？</span>(Kamu mahasiswa, ya?: だ diganti な)<br>Satu per satu akan dibahas di pelajaran 「～でしょう」 dan kata benda formal 「の」.</div>","n5-46":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kata sifat ada <b>di belakang</b> kata benda: 「gunung tinggi」「bunga cantik」. Dalam bahasa Jepang, kata sifat justru <b>di depan</b> kata benda. Caranya ada dua: <b>kata sifat tipe い langsung ditempel di depan kata benda</b>, sedangkan <b>kata sifat tipe な harus disisipi 「な」</b>. Posisi 「な」 ini mirip dengan 「yang」 sebagai penghubung.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata sifat tipe い</b> (yang berakhiran い): tidak perlu diubah apa-apa, langsung taruh di depan kata benda.<br><span class='gd-pair'><span class='gd-jp'>高い</span>＋<span class='gd-jp'>山</span> → <span class='gd-jp'>高い山</span></span>(gunung yang tinggi)<br><span class='gd-pair'><span class='gd-jp'>新しい</span>＋<span class='gd-jp'>靴</span> → <span class='gd-jp'>新しい靴</span></span>(sepatu baru)</div><div class='gd-sec'><b>Kata sifat tipe な</b>: tambahkan 「な」 di belakangnya, lalu sambung dengan kata benda.<br><span class='gd-pair'><span class='gd-jp'>きれい</span>＋な＋<span class='gd-jp'>花</span> → <span class='gd-jp'>きれいな花</span></span>(bunga yang cantik)<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋な＋<span class='gd-jp'>部屋</span> → <span class='gd-jp'>静かな部屋</span></span>(kamar yang tenang)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい靴を買いました。</span>(Aku membeli sepatu baru.)</div><div class='gd-ex-line'>・<span class='gd-jp'>これはおいしいケーキですね。</span>(Ini kue yang enak, ya.)</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな部屋がいいです。</span>(Aku mau kamar yang tenang.)</div><div class='gd-ex-line'>・<span class='gd-jp'>好きな食べ物は何ですか。</span>(Makanan kesukaanmu apa?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span> memang berakhiran い, tapi sebenarnya <b>kata sifat tipe な</b>. Jadi katakan <span class='gd-jp'>きれいな花</span>、<span class='gd-jp'>きらいな食べ物</span>, bukan きれい花.<br>・Karena ingin menyisipkan penghubung seperti 「yang」, banyak orang menyelipkan 「の」: 「高いの山」「静かの部屋」 itu salah semua. Kata sifat い tidak ditambah apa-apa, kata sifat な ditambah 「な」.<br>・「Banyak orang」 tidak bisa langsung dikatakan 「多い人」, melainkan <span class='gd-jp'>たくさんの人</span>.<br>・Kamu mungkin melihat <span class='gd-jp'>大きな家</span>、<span class='gd-jp'>小さな店</span>. Ini bukan salah tulis, tapi bentuk lain dari <span class='gd-jp'>大きい</span>、<span class='gd-jp'>小さい</span> yang hanya dipakai di depan kata benda. <span class='gd-jp'>大きい家</span> dan <span class='gd-jp'>大きな家</span> sama-sama benar.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat vs di depan kata benda</span>「な」 pada kata sifat tipe な <b>hanya muncul saat diikuti kata benda</b>. Kalau di akhir kalimat, langsung diikuti です.<br><span class='gd-jp'>この部屋は静かです。</span>(Kamar ini tenang.)<br><span class='gd-jp'>静かな部屋です。</span>(Ini kamar yang tenang.)<br>Kamu tidak bisa mengatakan 「この部屋は静かなです」.</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋の</span>Kalau yang ada di depan adalah <b>kata benda</b>, penghubungnya 「の」, bukan 「な」.<br><span class='gd-jp'>日本の車</span>(mobil Jepang: kata benda＋の)<br><span class='gd-jp'>新しい車</span>(mobil baru: kata sifat い langsung disambung)<br><span class='gd-jp'>きれいな車</span>(mobil yang bagus/cantik: kata sifat な＋な)</div><div class='gd-warn'>Trik cepat: tanyakan dulu pada dirimu, kata di depan itu jenis apa. Kata sifat い langsung ditempel, kata sifat な disisipi な, kata benda disisipi の.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kata sifat juga bisa menerangkan kata kerja, misalnya <span class='gd-jp'>早く起きます</span> (bangun pagi-pagi). Ini disebut 「penggunaan kata sifat sebagai kata keterangan」.</div>","n5-47":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Untuk menjelaskan sebuah tindakan dilakukan 「bagaimana」, bahasa Indonesia memakai kata seperti 「dengan」 atau mengulang kata: 「bangun pagi-pagi」「membersihkan dengan bersih」. Bahasa Jepang juga begitu: cukup <b>ubah akhiran</b> kata sifat, lalu taruh di depan kata kerja untuk menjelaskan bagaimana tindakan itu dilakukan.</div><div class='gd-h'>Cara mengubahnya: lihat dulu tipe kata sifatnya</div><div class='gd-sec'><b>Kata sifat tipe い (berakhiran 「い」)</b>: ganti 「い」 di akhir dengan 「く」.<br><span class='gd-pair'><span class='gd-jp'>早い</span> → い diganti く → <span class='gd-jp'>早く</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きく</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>明日は早く起きます。</span>(Besok aku bangun pagi.)</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を大きく書いてください。</span>(Tolong tulis namanya lebih besar.)</div><div class='gd-sec'><b>Kata sifat tipe な (yang perlu 「な」 saat di depan kata benda)</b>: langsung tambahkan 「に」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → tambah に → <span class='gd-jp'>静かに</span></span><br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいに</span></span><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部屋をきれいに掃除しました。</span>(Aku membersihkan kamar sampai bersih.)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館では静かに話してください。</span>(Di perpustakaan, tolong bicara dengan pelan.)</div><div class='gd-sec'><b>Pengecualian yang harus dihafal</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よく</span></span>, bukan いく. Kata yang berakhiran いい juga sama, misalnya <span class='gd-pair'><span class='gd-jp'>かっこいい</span> → <span class='gd-jp'>かっこよく</span></span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(Kemarin aku tidur nyenyak.)</div><div class='gd-ex-line'>・<span class='gd-jp'>かっこよく踊りたいです。</span>(Aku ingin menari dengan keren.)</div><div class='gd-h'>Urutannya terbalik dari bahasa Indonesia</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang 「menari dengan baik」「menulis dengan indah」, jadi bagian penjelasnya ada <b>setelah</b> kata kerja. Bahasa Jepang kebalikannya: <b>sebutkan dulu bagaimana, baru tindakannya</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは上手に踊ります。</span>(Pak Tanaka menari dengan baik.)</div><div class='gd-ex-line'>・<span class='gd-jp'>字をきれいに書きます。</span>(Menulis huruf dengan indah.)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span> memang tampak berakhiran い, tapi sebenarnya kata sifat tipe な: katakan <span class='gd-jp'>きれいに</span>, bukan きれく.<br>・Bentuk asli kata sifat tidak bisa langsung ditaruh di depan kata kerja: tidak boleh 早い起きます, harus <span class='gd-jp'>早く起きます</span>; tidak boleh 静かな話します, harus <span class='gd-jp'>静かに話します</span>.<br>・<span class='gd-jp'>よく</span> selain berarti 「dengan baik」, juga sering berarti 「sering」: <span class='gd-jp'>よく行きます</span> artinya 「sering pergi」. Lihat konteksnya untuk memastikan.<br>・<span class='gd-jp'>早く</span> dan <span class='gd-jp'>速く</span> sama-sama dibaca はやく, tapi 「早く」 berarti awal waktunya, sedangkan 「速く」 berarti kecepatannya tinggi: <span class='gd-jp'>早く起きます</span> (bangun pagi), <span class='gd-jp'>速く走ります</span> (berlari cepat).</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>Kata sifat yang menerangkan kata benda</b> dari pelajaran sebelumnya gampang tertukar dengan pelajaran ini. Bedanya hanya pada <b>apa yang ada di belakangnya</b>:<br>Diikuti kata benda (orang, benda): kata sifat い tidak berubah, kata sifat な ditambah 「な」.<br>Diikuti kata kerja (tindakan): kata sifat い berubah jadi 「く」, kata sifat な ditambah 「に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな人です。</span>(Dia orang yang pendiam.)</div><div class='gd-ex-line'>・<span class='gd-jp'>静かに話します。</span>(Bicara dengan pelan.)</div><div class='gd-ex-line'>・<span class='gd-jp'>早い電車に乗ります。</span>(Naik kereta yang lebih pagi.)</div><div class='gd-ex-line'>・<span class='gd-jp'>早く来てください。</span>(Tolong datang lebih awal.)</div><div class='gd-warn'>Trik cepat: kalau di belakangnya 「benda」, pakai 「〜い／〜な」; kalau di belakangnya 「tindakan」, pakai 「〜く／〜に」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>く／に yang sama, kalau diikuti <span class='gd-jp'>なります</span> artinya 「menjadi ～」, dan kalau diikuti <span class='gd-jp'>します</span> artinya 「membuatnya jadi ～」: <span class='gd-jp'>寒くなりました。</span>(Jadi dingin.)、<span class='gd-jp'>静かにしてください。</span>(Tolong tenang.)</div>","n5-48":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kita bilang「buku <b>yang kupinjam minggu lalu</b>」atau「sekolah <b>yang sedang dipelajari adikku</b>」. Keterangannya ada <b>sesudah</b> kata benda dan disambung dengan \"yang\". Dalam bahasa Jepang, keterangan itu <b>diletakkan sebelum kata benda</b>, dan <b>tidak ada kata \"yang\"</b> sama sekali. Tinggal taruh saja di depan.<br><span class='gd-jp'>先週借りた本</span>（buku yang dipinjam minggu lalu）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bagian yang menerangkan kata benda memakai <b>bentuk biasa (普通形)</b>, yaitu bentuk santai seperti bicara dengan teman, tanpa ます dan です. Lalu langsung tempelkan di depan kata benda.<br><span class='gd-pair'><span class='gd-jp'>本を借りました</span> → <span class='gd-jp'>借りた</span></span> → <span class='gd-jp'>先週借りた本</span></div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Artinya ikut berubah sesuai bentuk yang kamu pakai:<br><span class='gd-jp'>見る映画</span>（film yang akan ditonton）<br><span class='gd-jp'>見ない映画</span>（film yang tidak ditonton）<br><span class='gd-jp'>見た映画</span>（film yang sudah ditonton）<br><span class='gd-jp'>見なかった映画</span>（film yang tidak ditonton）<br><span class='gd-jp'>見ている映画</span>（film yang sedang ditonton）</div><div class='gd-sec'><span class='gd-tag'>Akhiran い-adjektiva</span>Langsung disambung.<br><span class='gd-jp'>髪が長い人</span>（orang yang rambutnya panjang）</div><div class='gd-sec'><span class='gd-tag'>Akhiran な-adjektiva</span>Pada bentuk positif masa kini, だ diganti menjadi <b>な</b>.<br><span class='gd-pair'><span class='gd-jp'>交通が便利だ</span> → <span class='gd-jp'>交通が便利な町</span></span>（kota yang transportasinya mudah）<br>Bukan「便利だ町」.</div><div class='gd-sec'><span class='gd-tag'>Akhiran kata benda</span>Pada bentuk positif masa kini, だ diganti menjadi <b>の</b>, bukan な.<br><span class='gd-pair'><span class='gd-jp'>母が日本人だ</span> → <span class='gd-jp'>母が日本人の友達</span></span>（teman yang ibunya orang Jepang）<br>Bukan「日本人だ友達」, dan bukan juga「日本人な友達」.</div><div class='gd-sec'>Untuk bentuk lampau atau negatif, tidak perlu diubah. Langsung sambung saja:<br><span class='gd-jp'>静かじゃない部屋</span>（kamar yang tidak tenang）<br><span class='gd-jp'>昔、先生だった人</span>（orang yang dulu menjadi guru）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Seluruh rangkaian「kata benda yang ...」bisa dianggap satu kata benda besar dan dipakai di dalam kalimat. Supaya terdengar sopan, <b>cukup akhiri kalimat dengan です・ます</b>. Bagian di depannya tetap memakai bentuk biasa.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは母が作ったケーキです。</span>（Ini kue yang dibuat ibuku）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日見た映画はおもしろかったです。</span>（Film yang kutonton kemarin seru）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で行きたい所はどこですか。</span>（Tempat yang ingin kamu kunjungi di Jepang itu di mana?）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くにある店で会いましょう。</span>（Ayo kita bertemu di toko yang ada di dekat stasiun）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Karena bahasa Indonesia punya \"yang\", kamu mungkin tergoda menambah の: 「借りたの本」itu salah. Yang benar: <span class='gd-jp'>借りた本</span>.<br>・Jangan pakai ます di dalam bagian itu: 「買いました本」itu salah. Yang benar: <span class='gd-jp'>買った本</span>. Kesopanan cukup diserahkan ke です・ます di akhir kalimat.<br>・Untuk \"siapa yang melakukannya\" di dalam bagian itu, pakai <b>が</b>, bukan は: 「私は作った料理」itu salah. Yang benar: <span class='gd-jp'>私が作った料理</span>（masakan yang kubuat）. Kamu juga mungkin menemukan <span class='gd-jp'>私の作った料理</span>. が diganti の, artinya sama.<br>・な-adjektiva berubah jadi <b>な</b>（<span class='gd-jp'>静かな部屋</span>）, sedangkan kata benda berubah jadi <b>の</b>（<span class='gd-jp'>医者の父</span>, ayah yang menjadi dokter）. Jangan dicampur.<br>・<span class='gd-jp'>見た映画</span>artinya「yang sudah ditonton」, sedangkan <span class='gd-jp'>見る映画</span>artinya「yang akan ditonton / yang biasa ditonton」. Pilih waktunya dengan tepat.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama membicarakan buku, tetapi kata apa yang ada di depannya menentukan perlu tidaknya の:<br><span class='gd-jp'>私の本</span>（bukuku）: di depannya kata benda, jadi pakai の<br><span class='gd-jp'>私が買った本</span>（buku yang kubeli）: di depannya kata kerja, langsung sambung<br><span class='gd-jp'>新しい本</span>（buku baru）: di depannya い-adjektiva, langsung sambung</div><div class='gd-warn'>Trik cepat: lihat kata yang menempel tepat di depan kata benda. Kalau itu kata benda, tambahkan の. Kalau kata kerja atau い-adjektiva, langsung sambung. Kata \"yang\" dari bahasa Indonesia tidak usah dipikirkan.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜とき」（ketika ...）memakai cara sambung yang sama: <span class='gd-jp'>日本へ行くとき</span>（ketika pergi ke Jepang）, <span class='gd-jp'>子どものとき</span>（ketika masih kecil）.</div>","n5-49":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「の」bisa <b>membungkus sebuah kegiatan menjadi \"satu hal\"</b>, seperti saat kita bilang「<b>hal</b> berfoto」atau「<b>kegiatan</b> berenang」. Dalam bahasa Indonesia, kata kerja bisa langsung dipakai: \"Aku suka berenang\". Dalam bahasa Jepang tidak bisa. Kata kerja harus diberi「の」dulu agar menjadi \"hal berenang\". Baru setelah itu bisa disambung dengan <span class='gd-jp'>は</span>, <span class='gd-jp'>が</span>, atau <span class='gd-jp'>を</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja memakai <b>bentuk biasa (普通形)</b>, yaitu bentuk kamus seperti <span class='gd-jp'>泳ぐ</span>, <span class='gd-jp'>撮る</span>. Bukan bentuk setelah ます dibuang seperti <span class='gd-jp'>泳ぎ</span>, <span class='gd-jp'>撮り</span>. Langsung tambahkan「の」.<br><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぐの</span></span>（hal berenang）<br><span class='gd-pair'><span class='gd-jp'>写真を撮る</span> → <span class='gd-jp'>写真を撮るの</span></span>（hal mengambil foto）<br>Untuk bilang \"tidak melakukan sesuatu\", pakai bentuk ない lalu tambah の: <span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないの</span></span>（hal tidak makan）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>のが好き・上手</span>Untuk bilang suka tidaknya atau jago tidaknya melakukan sesuatu. Kalau diikuti <span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>上手</span>, <span class='gd-jp'>下手</span>, pakai「が」.</div><div class='gd-ex-line'>・<span class='gd-jp'>小説を読むのが好きです。</span>（Aku suka membaca novel）</div><div class='gd-ex-line'>・<span class='gd-jp'>母は料理を作るのが上手です。</span>（Ibuku jago memasak）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は歌うのが下手です。</span>（Aku tidak pandai menyanyi）</div><div class='gd-sec'><span class='gd-tag'>のは＋kesan</span>Sebutkan dulu suatu hal, lalu katakan bagaimana menurutmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>写真を撮るのは楽しいです。</span>（Berfoto itu menyenangkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を話すのは難しいです。</span>（Berbicara bahasa Jepang itu sulit）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べないのは体によくないです。</span>（Tidak sarapan itu tidak baik untuk tubuh）</div><div class='gd-sec'><span class='gd-tag'>のを＋tindakan</span>Menjadikan \"hal itu\" sebagai objek dari sebuah tindakan.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を出すのを忘れました。</span>（Aku lupa mengumpulkan PR）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来るのを待っています。</span>（Aku sedang menunggu Tanaka datang）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Langsung menaruh kata kerja seperti di bahasa Indonesia: <span class='gd-jp'>泳ぐが好きです</span>itu salah. Yang benar: <span class='gd-jp'>泳ぐのが好きです</span>.<br>・Di depan の tidak boleh memakai bentuk ます. Tidak bisa bilang「泳ぎますのが好きです」. Kesopanan cukup diletakkan di <span class='gd-jp'>です</span> pada akhir kalimat.<br>・Kalau sudah kata benda, tidak perlu menambah の lagi: <span class='gd-jp'>音楽が好きです</span>（Aku suka musik）. Jangan jadi「音楽のが好きです」.<br>・Di depan <span class='gd-jp'>好き</span> dan <span class='gd-jp'>上手</span> pakai「が」. Jangan memakai「を」hanya karena dalam bahasa Indonesia terasa seperti \"suka <b>melakukan</b> ～\".<br>・Ini berbeda dari「の」pada <span class='gd-jp'>私の本</span>（bukuku）. Di sana di depannya kata benda dan artinya \"milik\". Di sini di depannya kata kerja dan artinya \"hal / kegiatan\".</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「こと」juga bisa mengubah tindakan menjadi \"satu hal\", dan sering kali keduanya bisa dipakai:<br><span class='gd-jp'>本を読むのが好きです。</span>／<span class='gd-jp'>本を読むことが好きです。</span>（Keduanya artinya \"Aku suka membaca buku\", こと terdengar sedikit lebih formal）<br><br>Tetapi ada tempat yang hanya bisa memakai salah satunya:<br><b>Untuk pemandangan yang kamu lihat atau dengar langsung, hanya の</b>: <span class='gd-jp'>田中さんが走っているのを見ました。</span>（Aku melihat Tanaka sedang berlari）<br><b>Untuk akhir kalimat berpola \"A adalah ～\", pakai こと</b>: <span class='gd-jp'>私の趣味は写真を撮ることです。</span>（Hobiku adalah berfoto）. Tidak bilang「撮るのです」.</div><div class='gd-warn'>Trik cepat: kalau kamu melihat atau mendengarnya langsung, pakai の. Kalau \"... adalah melakukan sesuatu\" di akhir kalimat, pakai こと. Untuk suka atau seru tidaknya, keduanya boleh, tetapi dalam percakapan sehari-hari の terasa paling mulus.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau sudah akrab dengan「こと」, langkah berikutnya adalah <span class='gd-jp'>〜ことができる</span> = bisa melakukan ～: <span class='gd-jp'>私は泳ぐことができます。</span>（Aku bisa berenang）</div>","n5-50":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kita cukup bilang 「ada」 untuk semuanya: ada buku di meja, ada kucing di kamar. Bahasa Jepang membedakannya satu langkah lagi: <b>benda dan tumbuhan</b> pakai <span class='gd-jp'>あります</span>, sedangkan <b>orang dan hewan</b> pakai <span class='gd-jp'>います</span>. Cukup lihat apakah sesuatu itu hidup dan bisa bergerak sendiri, maka kamu tahu mana yang dipakai.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tempat＋<span class='gd-jp'>に</span>＋benda atau orang＋<span class='gd-jp'>が</span>＋<span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span><br><span class='gd-jp'>に</span> mirip 「di」 dalam bahasa Indonesia, menandai tempat. <span class='gd-jp'>が</span> menandai 「apa yang ada」.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き出しにハサミがあります。</span>（Ada gunting di dalam laci）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に生徒がいます。</span>（Ada murid di dalam kelas）</div><div class='gd-h'>あります atau います</div><div class='gd-sec'><span class='gd-tag'>あります</span>Benda, tumbuhan, bangunan. Pohon memang hidup, tapi tidak berjalan ke mana-mana, jadi pakai <span class='gd-jp'>あります</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上に本があります。</span>（Ada buku di atas meja）</div><div class='gd-ex-line'>・<span class='gd-jp'>庭に大きい木があります。</span>（Ada pohon besar di halaman）</div><div class='gd-sec'><span class='gd-tag'>います</span>Orang dan hewan, termasuk ikan dan serangga.</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋に猫がいます。</span>（Ada kucing di kamar）</div><div class='gd-ex-line'>・<span class='gd-jp'>川に魚がいます。</span>（Ada ikan di sungai）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>～ada di mana</span>Kalau mau bilang sesuatu 「ada di」 suatu tempat, taruh bendanya di depan dengan <span class='gd-jp'>は</span>. Tempatnya tetap pakai <span class='gd-jp'>に</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ハサミは引き出しにあります。</span>（Gunting ada di dalam laci）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>（Toilet ada di mana?）</div><div class='gd-sec'><span class='gd-tag'>Tidak ada</span>Ganti ます menjadi ません: <span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ありません</span></span><span class='gd-pair'><span class='gd-jp'>います</span> → <span class='gd-jp'>いません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>教室に誰もいません。</span>（Tidak ada siapa pun di kelas）</div><div class='gd-sec'><span class='gd-tag'>Aku punya ～</span>Untuk 「punya」 seperti anggota keluarga atau waktu, bahasa Jepang juga sering memakai dua kata ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>姉が一人います。</span>（Aku punya satu kakak perempuan）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、時間がありますか。</span>（Besok kamu ada waktu?）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Untuk orang, pasti pakai <span class='gd-jp'>います</span>. 「Ada guru」 adalah <span class='gd-jp'>先生がいます</span>, dan 「先生があります」 itu salah. Anggota keluarga juga sama: <span class='gd-jp'>妹がいます</span>.<br>・Tumbuhan pakai <span class='gd-jp'>あります</span>. Ikan dan serangga, sekecil apa pun, kalau hidup pakai <span class='gd-jp'>います</span>.<br>・Untuk benda, orang, atau hewan yang 「berada di suatu tempat」, tempatnya pakai <span class='gd-jp'>に</span>. Yang benar adalah <span class='gd-jp'>部屋に猫がいます</span>, bukan 部屋で猫がいます.<br>・<b>Pengecualian</b>: kalau yang 「ada」 adalah kegiatan atau acara (<span class='gd-jp'>テスト</span>, <span class='gd-jp'>パーティー</span>, <span class='gd-jp'>会議</span>…), artinya 「diadakan di sana」, jadi tempatnya pakai <span class='gd-jp'>で</span>: <span class='gd-jp'>あした学校でテストがあります。</span>（Besok ada ujian di sekolah）<br>・<span class='gd-jp'>何も</span> dan <span class='gd-jp'>誰も</span> dalam arti 「tidak ada apa pun」 dan 「tidak ada siapa pun」 harus selalu diikuti bentuk negatif <span class='gd-jp'>ありません</span>／<span class='gd-jp'>いません</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama di taman, lihat apa yang ada di belakangnya:<br><b>Keberadaan</b> pakai <span class='gd-jp'>に</span>: <span class='gd-jp'>公園に犬がいます。</span>（Ada anjing di taman）<br><b>Melakukan aksi</b> pakai <span class='gd-jp'>で</span>: <span class='gd-jp'>公園で犬と遊びます。</span>（Bermain dengan anjing di taman）<br><b>Acara diadakan</b> pakai <span class='gd-jp'>で</span>: <span class='gd-jp'>公園でお祭りがあります。</span>（Ada festival di taman）</div><div class='gd-warn'>Trik cepat: kalau di belakangnya <span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span> dan yang ada adalah benda, orang, atau hewan, pakai <span class='gd-jp'>に</span>. Kalau di belakangnya sebuah aksi, atau yang 「ada」 adalah kegiatan atau acara, pakai <span class='gd-jp'>で</span>.</div><div class='gd-h'>Setelah ini, kamu bisa lanjut belajar</div><div class='gd-sec'>Menambahkan jumlah: <span class='gd-jp'>猫が二匹います。</span>（Ada dua ekor kucing）<br>Selain itu, <span class='gd-jp'>います</span> dalam <span class='gd-jp'>～ています</span> yang berarti 「sedang ～」 adalah kata yang sama dengan yang baru kamu pelajari hari ini.</div>","n5-52":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ています」 kurang lebih sama dengan <b>「sedang ～」, 「sudah ～ (dan sekarang masih begitu)」, dan 「belakangan ini rutin ～」</b>. Intinya, bentuk ini tidak menunjuk satu titik waktu, melainkan <b>keadaan yang sedang berlangsung</b>: aksi yang sedang berjalan, hasil yang masih bertahan, atau kebiasaan yang terus dilakukan akhir-akhir ini.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu kata kerjanya ke bentuk て, lalu tambahkan <b>います</b>. Kalau lupa cara membentuk て, kembali saja ke pelajaran 「bentuk て」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べています</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでいます</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しています</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span> → <span class='gd-jp'>来ています</span>（きています）</span></div><div class='gd-h'>Tiga arti</div><div class='gd-sec'><span class='gd-tag'>Sedang melakukan</span>Aksi sedang berlangsung saat ini, sering muncul bersama 「今」.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、洗濯しています。</span>（Sekarang aku sedang mencuci baju）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はテレビを見ています。</span>（Adikku sedang menonton TV）</div><div class='gd-sec'><span class='gd-tag'>Hasilnya masih bertahan</span>Ada aksi yang <b>selesai seketika</b>, misalnya menikah, (pintu atau jendela) terbuka (<span class='gd-jp'>開く</span>), atau pindah rumah. Kalau kata kerja seperti ini diberi ています, artinya bukan 「sedang」, melainkan 「sudah selesai, dan sekarang masih dalam keadaan itu」. Untuk menggambarkan keadaan suatu benda sekarang, pakai kata kerja intransitif seperti <span class='gd-jp'>開く</span>. Katakan <span class='gd-jp'>窓が開いています</span>, jangan <span class='gd-jp'>窓を開けています</span> (itu terdengar seperti 「ada orang yang sedang membuka jendela」).</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いています。</span>（Jendelanya terbuka）</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に住んでいます。</span>（Aku tinggal di Kyoto）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚しています。</span>（Kakak perempuanku sudah menikah）</div><div class='gd-sec'><span class='gd-tag'>Belakangan ini rutin dilakukan</span>Hal yang terus dilakukan akhir-akhir ini atau pada masa sekarang, seperti pekerjaan, kabar terkini, atau kebiasaan baru.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝走っています。</span>（Aku rutin lari setiap pagi）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は銀行で働いています。</span>（Ayahku bekerja di bank）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>結婚しています</span> artinya 「sudah menikah」, bukan 「sedang menggelar pesta pernikahan」. Begitu juga <span class='gd-jp'>住んでいます</span> artinya 「tinggal di」. Untuk bilang tempat tinggalmu sekarang, pasti pakai ini. <span class='gd-jp'>京都に住みます</span> justru berarti 「(nanti) akan tinggal di Kyoto」.<br>・「Tahu」 adalah <span class='gd-jp'>知っています</span>, tapi 「tidak tahu」 adalah <span class='gd-jp'>知りません</span>, bukan 知っていません.<br>・Kalau ada yang bertanya <span class='gd-jp'>もう食べましたか</span> dan kamu mau menjawab 「belum」, katakan <span class='gd-jp'>まだ食べていません</span>, jangan まだ食べませんでした.<br>・<span class='gd-jp'>来ています</span> dibaca dengan 来 sebagai <b>き</b>.<br>・Di antara teman, い sering dihilangkan: <span class='gd-jp'>食べています</span> jadi <span class='gd-jp'>食べてる</span>. Jangan bingung kalau mendengarnya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ます</b> dan <b>ています</b> paling sering tertukar. Lihat perbedaannya pada aksi yang sama:<br><span class='gd-jp'>本を読みます。</span>（Aku membaca buku: kebiasaan, atau akan dibaca sebentar lagi）<br><span class='gd-jp'>本を読んでいます。</span>（Aku sedang membaca buku）<br><br><span class='gd-jp'>来月結婚します。</span>（Bulan depan aku akan menikah）<br><span class='gd-jp'>もう結婚しています。</span>（Aku sudah menikah）<br><br>Keduanya bisa dipakai untuk kebiasaan, tapi nuansanya berbeda:<br><span class='gd-jp'>毎日コーヒーを飲みます。</span>（Aku minum kopi setiap hari: kebiasaan umum, fakta）<br><span class='gd-jp'>最近、毎朝走っています。</span>（Belakangan ini aku lari setiap pagi: sedang rutin dilakukan akhir-akhir ini）</div><div class='gd-warn'>Trik cepat: kalau maksudmu 「sedang melakukan saat ini」, 「sudah ～ / dalam keadaan ～」, atau 「belakangan ini rutin ～」, pakai ています. Kalau maksudmu kebiasaan umum atau hal yang akan dilakukan, pakai ます.</div><div class='gd-h'>Setelah ini, kamu bisa lanjut belajar</div><div class='gd-sec'>Saat belajar 「kata kerja intransitif・transitif」, kamu akan sering menemui ungkapan 「hasilnya masih bertahan」 seperti <span class='gd-jp'>ドアが閉まっています</span> (pintunya tertutup). Nanti kalau dibandingkan, kamu akan jauh lebih paham.</div>","n5-53":"<div class='gd-h'>Langsung paham dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, menyebut beberapa kegiatan berurutan itu gampang: 「Pagi ini aku bangun, sikat gigi, lalu berangkat」, tinggal disambung dengan koma atau \"lalu\". Dalam bahasa Jepang tidak bisa langsung begitu. Kata kerja di bagian depan harus diubah dulu jadi <b>bentuk て</b>, yang artinya kira-kira \"…lalu…\". Hanya <b>kata kerja terakhir</b> yang menentukan kalimatnya present atau lampau, sopan atau tidak.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: langsung pakai bentuk て (cara mengubahnya ada di pelajaran 「bentuk て」).<br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span></div><div class='gd-sec'><b>Kata sifat-い</b>: ganti 「い」di akhir jadi 「くて」.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → ganti い jadi くて → <span class='gd-jp'>安くて</span></span><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくて</span></span>(pengecualian ini harus dihafal)</div><div class='gd-sec'><b>Kata sifat-な dan kata benda</b>: tambahkan 「で」langsung di belakangnya.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かで</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生で</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sesuai urutan</span>Satu hal selesai, baru hal berikutnya. Ceritakan sesuai urutan kejadiannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、歯を磨いて、出かけます。</span>(Pagi bangun, sikat gigi, lalu berangkat)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は家に帰って、すぐ寝ました。</span>(Kemarin sampai rumah langsung tidur)</div><div class='gd-sec'><span class='gd-tag'>Menyebut beberapa sifat</span>Menggambarkan orang atau benda dengan dua sifat sekaligus, seperti 「~ dan juga ~」 dalam bahasa Indonesia.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くて、おいしいです。</span>(Toko ini murah dan enak)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は台湾人で、大学生です。</span>(Aku orang Taiwan, dan seorang mahasiswa)</div><div class='gd-sec'><span class='gd-tag'>Cara melakukan</span>Tindakan di depan adalah \"cara\" atau \"keadaan\" saat melakukan hal di belakangnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>歩いて駅へ行きます。</span>(Pergi ke stasiun dengan berjalan kaki)</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持って出かけます。</span>(Pergi dengan membawa payung)</div><div class='gd-sec'><span class='gd-tag'>Sebab</span>Bagian depan adalah sebab. Bagian belakang biasanya perasaan, keadaan, atau 「tidak bisa ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ニュースを聞いて、びっくりしました。</span>(Mendengar berita itu, aku kaget)</div><div class='gd-ex-line'>・<span class='gd-jp'>頭が痛くて、何もできませんでした。</span>(Kepalaku sakit sekali, jadi tidak bisa melakukan apa-apa)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Waktu dan tingkat kesopanan <b>hanya dilihat dari kata kerja terakhir</b>: <span class='gd-jp'>昨日、デパートへ行って、靴を買いました。</span>(Kemarin pergi ke mal dan membeli sepatu) <span class='gd-jp'>行って</span> di depan tidak perlu diubah ke bentuk lampau. 「Lampau」diserahkan pada <span class='gd-jp'>買いました</span> di akhir.<br>・Kata sifat-い jadi <span class='gd-jp'>安くて</span>, bukan 「安いて」. <span class='gd-jp'>いい</span> berubah jadi <span class='gd-jp'>よくて</span>. Kata sifat-な jadi <span class='gd-jp'>静かで</span>, bukan 「静かくて」.<br>・Kalau menyebut dua sifat sekaligus, sebaiknya arahnya sama (dua-duanya kelebihan atau dua-duanya kekurangan). Untuk yang satu bagus satu jelek seperti 「murah tapi tidak enak」, pakai <span class='gd-jp'>が</span>: <span class='gd-jp'>この店は安いですが、おいしくないです。</span>(Toko ini murah, tapi tidak enak)<br>・Untuk て yang menyatakan sebab, di belakangnya <b>tidak boleh</b> ada 「ayo ~」「tolong ~」「aku mau ~」. Untuk bilang 「Lagi hujan, ayo naik taksi」, pakai <span class='gd-jp'>から</span>: <span class='gd-jp'>雨が降っているから、タクシーで行きましょう。</span></div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bercerita tentang apa yang dilakukan di akhir pekan:<br><span class='gd-jp'>映画を見て、ご飯を食べました。</span>(Nonton film, lalu makan: bercerita sesuai urutan)<br><span class='gd-jp'>映画を見てから、ご飯を食べました。</span>(Baru makan <b>setelah</b> selesai nonton film: urutan ditekankan)<br><span class='gd-jp'>映画を見たり、ご飯を食べたりしました。</span>(Nonton film, makan, dan semacamnya: hanya contoh, urutan tidak penting, mungkin masih ada hal lain yang dilakukan)</div><div class='gd-warn'>Trik cepat: untuk bercerita satu per satu sesuai urutan pakai 「て」, untuk menekankan 「baru B setelah A selesai」pakai 「てから」, dan untuk menyebut beberapa contoh secara acak pakai 「たり～たり」.</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Setelah bentuk て, masih banyak pola yang sering dipakai, misalnya 「tolong ~」: <span class='gd-jp'>ちょっと待ってください。</span>(Tolong tunggu sebentar), dan 「sedang ~」: <span class='gd-jp'>今、ご飯を食べています。</span>(Sekarang aku sedang makan)</div>","n5-55":"<div class='gd-h'>Langsung paham dalam satu kalimat</div><div class='gd-sec'>「〜てください」setara dengan <b>「tolong ~」</b> dalam bahasa Indonesia, dan 「〜ないでください」setara dengan <b>「tolong jangan ~」「dilarang ~」</b>. Kalau teman bilang 「tolong tunggu sebentar」, itu <span class='gd-jp'>ちょっと待ってください</span>. Kalau papan pengumuman menulis 「dilarang memotret」, itu <span class='gd-jp'>写真を撮らないでください</span>. Dua pola inilah yang dipakai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Meminta tolong</span>Meminta lawan bicara melakukan sesuatu untukmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう一度言ってください。</span>(Tolong ulangi sekali lagi)</div><div class='gd-sec'><span class='gd-tag'>Instruksi, arahan</span>Sering terdengar saat guru mengajar, dokter memberi arahan, atau saat menjelaskan langkah-langkah.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>(Tolong tulis namamu di sini)</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を毎日飲んでください。</span>(Obat ini tolong diminum setiap hari)</div><div class='gd-sec'><span class='gd-tag'>Meminta agar tidak melakukan</span>Dipakai untuk mengingatkan, melarang, dan menenangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>心配しないでください。</span>(Tolong jangan khawatir)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室で食べないでください。</span>(Tolong jangan makan di kelas)</div><div class='gd-h'>Cara menyambung: tolong lakukan 〜</div><div class='gd-sec'>Ubah dulu kata kerja jadi <b>bentuk て</b> (bentuk yang dipelajari di pelajaran 「bentuk て」), lalu tambahkan <span class='gd-jp'>ください</span> langsung di belakangnya.<br><b>Golongan 1 (kata kerja godan)</b>: lihat huruf terakhirnya untuk menentukan perubahan.<br>・Berakhiran う、つ、る → って: <span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってください</span></span><br>・Berakhiran む、ぶ、ぬ → んで: <span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んでください</span></span><br>・Berakhiran く → いて: <span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いてください</span></span><br>・Berakhiran ぐ → いで: <span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いでください</span></span><br>・Berakhiran す → して: <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話してください</span></span><br>・Pengecualian: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ってください</span></span>(bukan 行いて)</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」, lalu tambahkan 「て」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてください</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見てください</span></span></div><div class='gd-sec'><b>Golongan 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来てください</span>(きてください)</span></div><div class='gd-h'>Cara menyambung: tolong jangan 〜</div><div class='gd-sec'>Ubah dulu kata kerja jadi <b>bentuk ない</b>, lalu tambahkan <span class='gd-jp'>でください</span>.<br><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris 「あ」pada baris yang sama, lalu tambahkan ない.<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → ganti る jadi ら → <span class='gd-jp'>撮らない</span> → <span class='gd-jp'>撮らないでください</span></span><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かないでください</span></span><br>Yang berakhiran う diganti jadi 「わ」: <span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わないでください</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」, lalu tambahkan ない.<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないでください</span></span></div><div class='gd-sec'><b>Golongan 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないでください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないでください</span>(こないでください)</span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Untuk 「tolong jangan」, ない diikuti <b>で</b>: <span class='gd-jp'>見ないでください</span>, bukan 「見ないてください」, dan bentuk 「見ませんでください」juga tidak ada.<br>・Kata kerja berakhiran う di bentuk ない berubah jadi 「わ」: <span class='gd-jp'>吸わない</span>、<span class='gd-jp'>買わない</span>, bukan 「吸あない」.<br>・来る punya dua cara baca yang berbeda: <span class='gd-jp'>来てください</span> dibaca <b>きて</b>, sedangkan <span class='gd-jp'>来ないでください</span> dibaca <b>こないで</b>.<br>・Meski diterjemahkan jadi 「tolong」, sebenarnya pola ini <b>menyuruh lawan bicara</b> melakukan sesuatu. Kalau meminta tolong pada guru atau atasan, <span class='gd-jp'>〜てくださいませんか</span>(bisakah tolong ~) terdengar lebih sopan.<br>・Antarteman, ください sering dihilangkan: <span class='gd-jp'>ちょっと待って。</span>(Tunggu sebentar) <span class='gd-jp'>見ないで。</span>(Jangan lihat)<br>・Pelayan toko sering bilang <span class='gd-jp'>少々お待ちください</span>(mohon tunggu sebentar) kepada pelanggan. Itu bentuk lain yang lebih sopan, bukan bentuk て dari pelajaran ini, jadi cukup dikenali saat mendengarnya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Kalau di depan <span class='gd-jp'>ください</span> ada <b>benda</b>, artinya 「tolong beri aku」. Kalau di depannya <b>kata kerja bentuk て</b>, artinya 「tolong lakukan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>水をください。</span>(Tolong beri aku air)</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲んでください。</span>(Tolong minum air)</div><div class='gd-warn'>Trik cepat: 「kata benda + をください」berarti meminta barang dari seseorang, sedangkan 「bentuk て + ください」berarti meminta seseorang melakukan sesuatu.</div>","n5-60":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜でしょう」mirip dengan “mungkin ... ya” atau “... kan?” dalam bahasa Indonesia. Kalau nadanya turun, kamu sedang menebak sendiri: “Besok mungkin hujan ya”. Kalau nadanya naik, kamu minta konfirmasi dari lawan bicara: “Enak, kan?” Bentuknya sama, tapi <b>artinya dibedakan oleh intonasi</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak (nada turun ↓)</span>Kamu tidak 100% yakin, hanya menduga-duga. Sering dipakai bersama <span class='gd-jp'>たぶん</span> (mungkin / barangkali), dan juga sering muncul di ramalan cuaca.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はたぶん雨でしょう。</span>(Besok mungkin hujan ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったでしょう。</span>(Pak Tanaka sepertinya sudah pulang)</div><div class='gd-sec'><span class='gd-tag'>Konfirmasi (nada naik ↑)</span>Kamu merasa lawan bicara pasti berpikir sama, jadi kamu bertanya dan menunggu dia mengangguk.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいでしょう？</span>(Kue ini enak, kan?)</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょう？</span>(Tuh kan, sudah kubilang, kan?)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja dan い-keiyoushi</b>: langsung disambung. Bentuk negatif dan lampau juga langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いでしょう</span></span><span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないでしょう</span></span></div><div class='gd-sec'><b>な-keiyoushi dan kata benda</b>: buang 「だ」 dulu, baru sambung.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ dibuang → <span class='gd-jp'>静かでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨でしょう</span></span><br>Untuk bentuk lampau, 「だった」 tetap dipertahankan: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったでしょう</span></span></div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Setelah kata benda dan な-keiyoushi, 「だ」 tidak boleh dipertahankan: yang benar <span class='gd-jp'>学生でしょう</span>, sedangkan 「学生だでしょう」 salah.<br>・Jangan menaruh です di depannya: cukup <span class='gd-jp'>寒いでしょう</span>, bukan 「寒いですでしょう」. でしょう sendiri sudah merupakan “versi dugaan” dari です, jadi sudah sopan.<br>・Tidak bisa dipakai untuk hal yang <b>kamu rencanakan sendiri</b>. 「私は明日行くでしょう」 terdengar aneh. Untuk rencanamu sendiri, langsung bilang <span class='gd-jp'>明日行きます</span>.<br>・「でしょう？」 untuk konfirmasi punya nuansa “kamu pasti tahu, kan?”, jadi kepada guru atau atasan bisa terdengar kurang sopan. Kalau ingin bertanya dengan sopan kepada orang yang lebih tua, pakai <span class='gd-jp'>〜でしょうか</span> (permisi, ... ya?), misalnya <span class='gd-jp'>駅はどこでしょうか。</span> (Permisi, stasiunnya di mana ya?)<br>・Di antara teman, sering dipersingkat jadi <span class='gd-jp'>でしょ？</span>. Jangan kaget kalau dengar, artinya sama.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ましょう</b> dan <b>でしょう</b> sama-sama berakhiran 「しょう」, tapi artinya sangat berbeda:<br>・<span class='gd-jp'>一緒に行きましょう。</span> (Ayo pergi bersama: mengajak)<br>・<span class='gd-jp'>田中さんも行くでしょう。</span> (Pak Tanaka mungkin juga pergi: menebak)<br>Cara menyambungnya juga beda: ましょう disambung ke bentuk ます (<span class='gd-jp'>行き</span>＋ましょう), sedangkan でしょう disambung ke bentuk biasa seperti bentuk kamus (<span class='gd-jp'>行く</span>＋でしょう).</div><div class='gd-sec'><b>でしょう？</b> dan <b>ね</b> sama-sama bisa diterjemahkan “ya / kan”, bedanya apakah lawan bicara ikut merasakan hal yang sama:<br>・Dua orang berjalan bersama di luar: <span class='gd-jp'>寒いですね。</span> (Dingin ya: kalian sama-sama merasakannya saat itu, kamu hanya menimpali)<br>・Temanmu baru masuk dari luar, dan kamu bertanya dari dalam rumah: <span class='gd-jp'>外、寒いでしょう？</span> (Di luar dingin, kan?: kamu tidak ada di luar, kamu menebak dia kedinginan dan minta dia mengiyakan)</div><div class='gd-warn'>Tips membedakan: “Ayo lakukan bersama” → ましょう; “mungkin ...” atau “... kan?” → でしょう; kalau kedua orang sama-sama merasakannya saat itu dan kamu hanya menimpali, pakai ね.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kalau ingin bilang dengan keyakinan yang lebih rendah, “bisa jadi ~”, pakai <span class='gd-jp'>〜かもしれません</span>: <span class='gd-jp'>明日は雨かもしれません。</span> (Besok bisa jadi hujan)</div>","n5-61":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜からです」artinya <b>“karena ~”</b>. Saat lawan bicara bertanya dengan <span class='gd-jp'>どうして</span> (kenapa), kamu cukup menyebutkan alasannya lalu menambahkan 「からです」 di belakangnya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menjawab “kenapa”</span>Lawan bicara bertanya “kenapa” dulu, lalu kamu hanya menjawab alasannya, tanpa mengulang kejadian sebelumnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして休んだんですか。</span>(Kenapa kamu izin tidak masuk?)</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったからです。</span>(Karena aku demam)</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして日本語を勉強しているんですか。</span>(Kenapa kamu belajar bahasa Jepang?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本のアニメが好きだからです。</span>(Karena aku suka anime Jepang)</div><div class='gd-sec'><span class='gd-tag'>Menambahkan alasan sendiri</span>Sebutkan satu hal dulu, lalu tambahkan alasannya di kalimat berikutnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はパーティーに行きません。忙しいからです。</span>(Hari ini aku tidak ikut pesta. Karena sibuk)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Sebelum 「から」, pakai <b>bentuk tanpa ます dan tanpa です</b> (bentuk yang dipakai ke teman). Kesopanannya diserahkan ke 「です」 di akhir.<br><b>Kata kerja</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くからです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったからです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないからです</span></span><br><b>い-keiyoushi</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いからです</span></span><br><b>な-keiyoushi dan kata benda</b>: tambahkan 「だ」 di tengah.<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きだからです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だからです</span></span></div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Lupa menambahkan 「だ」 setelah な-keiyoushi dan kata benda: <span class='gd-jp'>好きからです</span> dan <span class='gd-jp'>雨からです</span> sama-sama salah. Yang benar <span class='gd-jp'>好きだからです</span> dan <span class='gd-jp'>雨だからです</span>.<br>・Sebaliknya, い-keiyoushi <b>tidak boleh</b> diberi 「だ」: yang benar <span class='gd-jp'>高いからです</span>, bukan 高いだからです.<br>・Jangan menaruh ます sebelum 「から」: <span class='gd-jp'>熱がありましたからです</span> salah, yang benar <span class='gd-jp'>熱があったからです</span>.<br>・Dalam bahasa Indonesia, “karena” diletakkan di <b>depan</b> alasan, tapi 「から」 di bahasa Jepang diletakkan di <b>belakang</b> alasan. Jangan bilang から熱があった.<br>・Ke teman, cukup buang です: <span class='gd-jp'>熱があったから。</span> (Karena demam, tahu)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kamu sudah belajar partikel 「から」 (alasan), dan artinya sama dengan 「からです」. Bedanya ada pada <b>susunan kalimat</b>. Untuk hal yang sama:<br><span class='gd-tag'>〜から、〜</span>Alasan di depan, hasil di belakang, selesai dalam satu kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったから、休みました。</span>(Karena demam, jadi aku izin tidak masuk)</div><div class='gd-sec'><span class='gd-tag'>〜からです</span>Hasilnya disebut dulu, lalu alasannya ditambahkan di kalimat lain; atau saat ditanya “kenapa”, kamu hanya menjawab alasannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みました。熱があったからです。</span>(Aku izin tidak masuk. Karena demam)</div><div class='gd-warn'>Tips membedakan: kalau setelah alasan masih ada “jadi begini” yang mau disambung, pakai 「〜から、」; kalau alasan itu sendiri menjadi akhir kalimat, pakai 「〜からです」.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kalau hasilnya ditaruh di depan dan ditambah 「のは」, alasannya bisa dijelaskan lebih jelas: <span class='gd-jp'>昨日休んだのは、熱があったからです。</span> (Alasan aku izin kemarin adalah karena demam)</div>","n5-63":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Kata tanya adalah kata untuk bertanya, setara dengan 「apa, siapa, di mana, kapan, yang mana, berapa harganya, bagaimana」 dalam bahasa Indonesia. Cara pakainya mirip: <b>letakkan kata tanya di posisi hal yang ingin kamu tanyakan, lalu tambahkan か di akhir kalimat</b>. Selain itu, kalau setelah kata tanya ditambah 「も」 atau 「か」, artinya berubah total. Inilah poin utama pelajaran ini.</div><div class='gd-h'>Kenali dulu tujuh yang paling sering dipakai</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何ですか。</span>(Ini apa?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は誰ですか。</span>(Orang itu siapa?)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>(Toiletnya di mana?)</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日はいつですか。</span>(Kapan ulang tahunmu?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どれがいいですか。</span>(Yang mana yang bagus?)</div><div class='gd-ex-line'>・<span class='gd-jp'>これはいくらですか。</span>(Ini berapa harganya?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本はどうでしたか。</span>(Bagaimana Jepang?)</div><div class='gd-sec'>Kalau bicara dengan tamu atau orang yang lebih tua dan ingin lebih sopan: <span class='gd-jp'>誰</span> bisa diganti dengan <span class='gd-jp'>どなた</span>, dan <span class='gd-jp'>どう</span> bisa diganti dengan <span class='gd-jp'>いかが</span>. Pelayan toko sering bilang <span class='gd-jp'>コーヒーはいかがですか。</span>(Mau minum kopi?)</div><div class='gd-h'>「何」dibaca なに atau なん?</div><div class='gd-sec'>Kalau diikuti <span class='gd-jp'>です</span>, <span class='gd-jp'>の</span>, atau unit hitung seperti 「jam ～, ～ orang」, dibaca <b>なん</b>: <span class='gd-jp'>何ですか</span>、<span class='gd-jp'>何の本</span>、<span class='gd-jp'>何時</span>、<span class='gd-jp'>何人</span>、<span class='gd-jp'>何曜日</span>.<br>Kalau diikuti <span class='gd-jp'>を</span>, <span class='gd-jp'>が</span>, <span class='gd-jp'>も</span>, atau <span class='gd-jp'>か</span>, dibaca <b>なに</b>: <span class='gd-jp'>何を食べますか</span>、<span class='gd-jp'>何も</span>、<span class='gd-jp'>何か</span>.</div><div class='gd-h'>Tambah 「も」: semuanya tidak</div><div class='gd-sec'><span class='gd-tag'>Kata tanya＋も＋bentuk negatif</span> artinya 「tidak ada apa pun, tidak ada siapa pun, tidak ke mana pun」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何も飲みませんでした。</span>(Tidak minum apa pun)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も来ませんでした。</span>(Tidak ada seorang pun yang datang)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日はどこへも行きませんでした。</span>(Hari Minggu tidak pergi ke mana pun)</div><div class='gd-sec'>Perhatikan partikelnya: <span class='gd-jp'>を</span> dan <span class='gd-jp'>が</span> yang asli akan digantikan oleh も (<span class='gd-pair'><span class='gd-jp'>何を</span> → <span class='gd-jp'>何も</span></span>). Tapi <span class='gd-jp'>へ</span> dan <span class='gd-jp'>に</span> tetap dipertahankan dan ditaruh sebelum も: <span class='gd-jp'>どこへも</span>、<span class='gd-jp'>どこにも</span>、<span class='gd-jp'>誰にも</span>.</div><div class='gd-h'>Tambah 「か」: sesuatu, tidak tentu</div><div class='gd-sec'><span class='gd-tag'>Kata tanya＋か</span> artinya 「sesuatu, seseorang, suatu tempat, suatu hari」. Ada, tapi tidak disebutkan yang mana.</div><div class='gd-ex-line'>・<span class='gd-jp'>何か食べたいです。</span>(Ingin makan sesuatu)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰かいますか。</span>(Ada orang di sini?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこか静かな場所へ行きたいです。</span>(Ingin pergi ke suatu tempat yang tenang)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつか日本に住みたいです。</span>(Suatu hari nanti ingin tinggal di Jepang)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kalau kata tanya jadi subjek, pakai <b>が</b>, bukan は: <span class='gd-jp'>誰が来ましたか。</span> Tidak boleh bilang 誰は来ましたか。<br>・<span class='gd-jp'>いつも</span> bukan 「kapan pun tidak ～」, tapi artinya 「selalu」. Bisa diikuti bentuk positif maupun negatif: <span class='gd-jp'>いつも朝ご飯を食べます。</span>(Aku selalu sarapan) / <span class='gd-jp'>いつも朝ご飯を食べません。</span>(Aku selalu tidak sarapan)<br>・<span class='gd-jp'>何も</span> dibaca なにも, bukan なんも.<br>・<span class='gd-jp'>どれ</span> dipakai untuk memilih satu dari tiga atau lebih. Kalau hanya dua pilihan, pakai <span class='gd-jp'>どちら</span>.</div><div class='gd-h'>Bedakan yang mirip-mirip</div><div class='gd-sec'>Sama-sama menanyakan apa yang diminum temanmu, beda satu huruf saja sudah beda arti:<br><b>何を</b> = menanyakan 「apa」, lawan bicara menjawab dengan nama benda: <span class='gd-jp'>何を飲みましたか。</span>(Kamu minum apa?) → <span class='gd-jp'>お茶です。</span><br><b>何か</b> = menanyakan 「ada atau tidak」, lawan bicara menjawab はい・いいえ dulu: <span class='gd-jp'>何か飲みましたか。</span>(Kamu minum sesuatu?) → <span class='gd-jp'>はい、お茶を飲みました。</span><br><b>何も</b>＋negatif = 「tidak ada apa pun」: <span class='gd-jp'>いいえ、何も飲みませんでした。</span>(Tidak, aku tidak minum apa pun)</div><div class='gd-warn'>Trik cepat: kalau mau tahu 「apa」, pakai 何を; kalau mau tahu 「ada atau tidak」, pakai 何か; kalau mau bilang 「tidak ada sama sekali」, pakai 何も＋negatif.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「Ini, itu, yang mana」 lebih mudah diingat kalau dipelajari sekaligus. Lanjut ke kata penunjuk (こそあど): <span class='gd-jp'>どの本ですか。</span>(Buku yang mana?)</div>","n5-64":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bahasa Indonesia hanya punya 「ini」 dan 「itu」, sedangkan bahasa Jepang membaginya jadi empat: <b>こ</b> = ini (dekat aku), <b>そ</b> = itu (dekat kamu), <b>あ</b> = itu (jauh dari kita berdua), <b>ど</b> = yang mana. Hafalkan dulu empat awalan 「こそあど」 ini, lalu ganti akhirannya, dan kamu bisa menunjuk benda, tempat, dan arah.</div><div class='gd-h'>Bayangkan sebuah adegan</div><div class='gd-sec'>Kamu dan temanmu berdiri di pinggir jalan. Kamu memegang ponsel, temanmu memegang segelas kopi, dan di seberang sana, jauh, ada sebuah gedung tinggi.<br>Ponsel ada di sisimu, pakai <b>こ</b>. Kopi ada di sisi temanmu, pakai <b>そ</b>. Gedung itu jauh dari kalian berdua, pakai <b>あ</b>. Kalau tidak tahu yang mana, pakai <b>ど</b>.</div><div class='gd-h'>Lihat keempat kelompoknya</div><div class='gd-sec'><span class='gd-tag'>Menunjuk benda</span><span class='gd-jp'>これ・それ・あれ・どれ</span><br>Kata-kata ini bisa jadi subjek sendiri, langsung diikuti 「は」 atau 「が」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>(Ini payungku)</div><div class='gd-ex-line'>・<span class='gd-jp'>それ、何ですか。</span>(Yang kamu pegang itu apa?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれは東京タワーです。</span>(Itu Tokyo Tower)</div><div class='gd-sec'><span class='gd-tag'>Diikuti kata benda</span><span class='gd-jp'>この・その・あの・どの</span><br>Kata-kata ini tidak bisa dipakai sendirian, harus selalu diikuti kata benda.</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、おもしろいですよ。</span>(Buku ini seru, lho)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、かわいいですね。</span>(Tasmu itu lucu ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人はだれですか。</span>(Orang itu siapa?)</div><div class='gd-sec'><span class='gd-tag'>Menunjuk tempat</span><span class='gd-jp'>ここ・そこ・あそこ・どこ</span></div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>(Toiletnya di mana?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あそこにコンビニがあります。</span>(Di sana ada minimarket)</div><div class='gd-sec'><span class='gd-tag'>Versi sopan</span><span class='gd-jp'>こちら・そちら・あちら・どちら</span><br>Bisa menunjuk arah, tempat, dan juga memperkenalkan orang dengan sopan. Sering dipakai pelayan toko dan petugas resepsionis. Kalau bicara dengan teman, berubah jadi <span class='gd-jp'>こっち・そっち・あっち・どっち</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>受付はあちらです。</span>(Resepsionisnya di sebelah sana)</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらは田中さんです。</span>(Ini Pak/Bu Tanaka)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>この・その・あの・どの</span> tidak bisa dipakai sendirian. Untuk 「ini punyaku」 bilang <span class='gd-jp'>これは私のです</span>, bukan このは私のです.<br>・「Di sana」 untuk tempat adalah <b>あそこ</b>, bukan あこ. Bentuk kata ini berbeda dari kata lain di kelompoknya, jadi hafalkan baik-baik.<br>・Bahasa Indonesia sama-sama bilang 「itu」, tapi bahasa Jepang membedakannya: kalau bendanya ada di dekat atau di tangan lawan bicara, pakai <b>それ</b>; hanya kalau jauh dari kalian berdua, pakai <b>あれ</b>.<br>・Posisi berdiri berbeda, kata yang dipakai juga ikut berubah. Kalau lawan bicara menunjuk benda di tangannya dan bertanya <span class='gd-jp'>これは何ですか</span>, kamu menjawab dengan <span class='gd-jp'>それは～です</span>, karena benda itu ada di sisinya.<br>・Hal yang baru saja disebut lawan bicara juga ditunjuk dengan kata berawalan 「そ」: <span class='gd-jp'>それ、いいですね。</span>(Itu bagus ya)<br>・Saat memperkenalkan orang, pakai <span class='gd-jp'>こちら</span>. Menunjuk orang dengan <span class='gd-jp'>これ</span> seperti menganggap orang itu benda, dan itu sangat tidak sopan.</div><div class='gd-h'>Bedakan yang mirip-mirip</div><div class='gd-sec'><b>これ</b> dan <b>この</b>: sama-sama berarti 「ini」, bedanya pada apa yang mengikutinya.<br><span class='gd-jp'>これは私の本です。</span>(Ini bukuku)<br><span class='gd-jp'>この本は私のです。</span>(Buku ini punyaku)<br>Pada kalimat pertama, <span class='gd-jp'>これ</span> diikuti 「は」. Pada kalimat kedua, <span class='gd-jp'>この</span> diikuti 「本」.</div><div class='gd-sec'><b>どれ</b> dan <b>どちら</b>: sama-sama 「yang mana」, bedanya pada jumlah pilihan.<br><span class='gd-jp'>この三つの中で、どれがいいですか。</span>(Di antara tiga ini, yang mana yang bagus?)<br><span class='gd-jp'>コーヒーと紅茶、どちらがいいですか。</span>(Kopi atau teh, kamu pilih yang mana?)<br>Untuk memilih 「yang mana」 dari tiga benda atau lebih, pakai どれ; kalau hanya memilih satu dari dua, pakai どちら.</div><div class='gd-warn'>Trik cepat: kalau langsung diikuti kata benda, pakai この; kalau diikuti 「は」「が」, pakai これ. Pilih satu dari tiga atau lebih, pakai どれ; pilih satu dari dua, pakai どちら.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kelompok berawalan 「ど」 ini sebenarnya adalah kata untuk bertanya. Lanjut ke 「kata tanya」 dan pelajari sekalian <span class='gd-jp'>だれ</span>, <span class='gd-jp'>なに</span>, dan <span class='gd-jp'>いつ</span>.</div>","n5-57":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, “aku mau / aku ingin” dipakai untuk dua hal: menginginkan sebuah <b>benda</b> (aku mau HP baru) dan ingin <b>melakukan</b> sesuatu (aku ingin pergi ke Jepang). Bahasa Jepang memisahkan keduanya: untuk benda pakai <b>「欲しい」</b>, untuk tindakan pakai <b>「〜たい」</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Ingin benda</span>kata benda＋が欲しいです</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいスマホが欲しいです。</span>（Aku mau HP baru）</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日に時計が欲しいです。</span>（Untuk ulang tahun, aku mau jam tangan）</div><div class='gd-sec'><span class='gd-tag'>Ingin melakukan sesuatu</span>Ubah kata kerja ke bentuk ます, buang 「ます」, lalu tambahkan 「たいです」.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → buang ます → <span class='gd-jp'>行きたい</span></span><br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べたい</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見たい</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>したい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来たい</span>（きたい）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行きたいです。</span>（Aku ingin pergi ke Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>温泉に入りたいです。</span>（Aku ingin berendam di onsen）</div><div class='gd-h'>Perhatikan partikelnya</div><div class='gd-sec'>Sebelum <span class='gd-jp'>欲しい</span> pakai <b>が</b>.<br>Untuk <span class='gd-jp'>〜たい</span>, di tempat yang biasanya memakai 「を」, kamu boleh tetap memakai 「を」 atau menggantinya dengan 「が」. Dua-duanya benar:<br><span class='gd-jp'>水を飲みたいです。</span>／<span class='gd-jp'>水が飲みたいです。</span>（Aku ingin minum air）<br>Partikel lain tidak boleh diganti, tetap seperti aslinya: <span class='gd-jp'>友達に会いたいです。</span>（Aku ingin bertemu temanku）. 「に」 di sini tidak bisa diganti dengan が.</div><div class='gd-h'>Bentuk negatif dan lampau: berubah seperti kata sifat-い</div><div class='gd-sec'><span class='gd-jp'>欲しい</span> dan <span class='gd-jp'>〜たい</span> sama-sama berakhiran 「い」, jadi perubahannya persis seperti kata sifat-い:<br><span class='gd-pair'><span class='gd-jp'>欲しいです</span> → <span class='gd-jp'>欲しくないです</span></span>（tidak mau）<span class='gd-pair'><span class='gd-jp'>欲しかったです</span></span>（dulu mau）<br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたくないです</span></span>（tidak ingin pergi）<span class='gd-pair'><span class='gd-jp'>行きたかったです</span></span>（dulu ingin pergi）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は何もしたくないです。</span>（Hari ini aku tidak ingin melakukan apa pun）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・たい disambung ke bentuk ます, bukan bentuk kamus. 「行くたい」 itu salah; yang benar <span class='gd-jp'>行きたい</span>.<br>・たい sudah menjadi kata sifat, jadi tidak boleh ditambah ます lagi: yang benar <span class='gd-jp'>行きたいです</span>, bukan 「行きたいます」. Untuk negatif: <span class='gd-jp'>行きたくないです</span>, bukan 「行きたいません」.<br>・<span class='gd-jp'>来たい</span> dibaca <b>きたい</b>.<br>・Keduanya hanya untuk perasaan <b>diri sendiri</b>. Kalau kamu bilang 「田中さんは車が欲しいです」 begitu saja, orang Jepang akan merasa janggal, karena kamu tidak bisa merasakan apa yang dirasakan orang lain. Untuk orang lain, katakan <span class='gd-jp'>田中さんは車が欲しいと言っていました。</span>（Tanaka bilang dia mau mobil）. Tapi bertanya langsung ke lawan bicara boleh: <span class='gd-jp'>何が欲しいですか。</span>（Kamu mau apa?）<br>・Kepada guru, atasan, atau tamu, bertanya langsung 「〜たいですか」 terdengar seperti mengorek-ngorek keinginan orang, jadi kurang sopan. Kalau mau menawarkan minuman, lebih pantas bilang <span class='gd-jp'>コーヒーはいかがですか。</span> atau <span class='gd-jp'>コーヒーを飲みませんか。</span></div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal secangkir kopi:<br><span class='gd-jp'>コーヒーが欲しいです。</span>（Aku mau kopi: yang diinginkan adalah bendanya, “kopi”）<br><span class='gd-jp'>コーヒーが飲みたいです。</span>（Aku ingin minum kopi: yang ingin dilakukan adalah tindakan “minum”）<br>Orang Indonesia sering tersangkut di kalimat “Aku mau pergi ke Jepang”. Ada kata “mau” di situ, tapi yang sebenarnya ingin dilakukan adalah tindakan “pergi”, jadi katakan <span class='gd-jp'>日本へ行きたいです。</span>, bukan dengan 欲しい.</div><div class='gd-warn'>Trik menilai: buang kata “mau / ingin” dan lihat apa yang ada di belakangnya. Kalau <b>kata benda</b> (HP, kopi), pakai 欲しい; kalau <b>kata kerja</b> (pergi, makan, lihat), pakai たい.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Dipadukan dengan 「に（tujuan）」: <span class='gd-jp'>映画を見に行きたいです。</span>（Aku ingin pergi menonton film）. Nanti kamu juga akan belajar cara menyatakan keinginan orang lain: <span class='gd-jp'>欲しがっている</span>、<span class='gd-jp'>〜たがっている</span>.</div>","n5-59":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とき」 sama dengan <b>“saat / ketika / waktu ...”</b> dalam bahasa Indonesia. Bedanya, bahasa Jepang menaruh 「とき」 di bagian paling belakang, dan seluruh bagian di depannya menerangkan 「とき」 itu. Contohnya <span class='gd-jp'>暇なとき</span>（saat senggang）、<span class='gd-jp'>子どものとき</span>（waktu kecil）.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>「とき」 sendiri adalah kata benda, jadi cara menyambung bagian depannya sama persis dengan cara “menerangkan kata benda” yang sudah kamu pelajari.<br><b>Kata kerja</b>: disambung langsung<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとき</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないとき</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったとき</span></span><br><b>Kata sifat-い</b>: disambung langsung<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいとき</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いとき</span></span><br><b>Kata sifat-な</b>: tambahkan 「な」<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇なとき</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なとき</span></span><br><b>Kata benda</b>: tambahkan 「の」<br><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものとき</span></span><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのとき</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>暇なとき、何をしますか。</span>（Kalau lagi senggang, kamu biasanya ngapain?）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、よくこの公園で遊びました。</span>（Waktu kecil, aku sering bermain di taman ini）</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないとき、先生に聞きます。</span>（Kalau tidak paham, aku bertanya ke guru）</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないとき、コンビニでご飯を買います。</span>（Kalau tidak sempat, aku beli makanan di minimarket）</div><div class='gd-h'>Poin terpenting: 行くとき dan 行ったとき</div><div class='gd-sec'>Kata kerja di depan 「とき」 memakai bentuk kamus atau bentuk た, dan itu <b>bukan tergantung kalimatnya sekarang atau lampau</b>, melainkan tergantung apakah tindakan itu <b>sudah selesai</b> pada saat tersebut.<br><span class='gd-tag'>Bentuk kamus＋とき</span>Tindakan belum selesai: baru akan dilakukan, atau sedang berlangsung.<br><span class='gd-tag'>Bentuk た＋とき</span>Tindakan sudah selesai.</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるとき、「いってきます」と言います。</span>（Saat mau keluar rumah, kita bilang “Aku berangkat dulu”）</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったとき、「ただいま」と言います。</span>（Saat sudah sampai rumah, kita bilang “Aku pulang”）</div><div class='gd-sec'>Lihat satu pasang lagi. Kedua kalimat berakhir dengan bentuk lampau, tapi artinya jauh berbeda:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行くとき、辞書を買いました。</span>（Saat mau pergi ke Jepang, aku membeli kamus: dibeli sebelum berangkat atau di perjalanan）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行ったとき、辞書を買いました。</span>（Saat sudah pergi ke Jepang, aku membeli kamus: dibeli setelah tiba di Jepang）</div><div class='gd-sec'>Kalimat pertama jelas kejadian masa lalu, tapi bagian depannya tetap memakai <span class='gd-jp'>行く</span>, karena pada saat membeli kamus, orangnya belum sampai di Jepang.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda harus diberi の: <span class='gd-jp'>子どものとき</span>, bukan 子どもとき.<br>・Kata sifat-な harus diberi な, dan tidak boleh memakai だ: <span class='gd-jp'>暇なとき</span>, bukan 暇とき, dan bukan juga 暇だとき. Hanya untuk lampau boleh <span class='gd-jp'>暇だったとき</span>.<br>・Setelah kata kerja dan kata sifat-い, <b>jangan</b> tambahkan の. Karena terbiasa dengan kata penghubung seperti “yang” dalam bahasa Indonesia, banyak orang jadi mengucapkan 「行くのとき」. Itu salah.<br>・Sebelum 「とき」 tidak dipakai ます atau です: <span class='gd-jp'>行くとき、〜ます</span> sudah cukup sopan, jangan bilang 「行きますとき」. Tingkat kesopanan ditentukan di akhir kalimat.<br>・Untuk kebiasaan atau kondisi, 「ときは」 dengan は sering dipakai, seperti <span class='gd-jp'>寒いときは、温かいお茶を飲みます。</span>（Kalau dingin, aku minum teh hangat）. Terdengar sangat alami.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><span class='gd-jp'>〜まえに</span> dan <span class='gd-jp'>〜たあとで</span> yang sudah kamu pelajari juga berkaitan dengan waktu, jadi gampang tertukar dengan 「とき」.<br><b>とき</b> ＝ tepat pada saat itu, selama proses itu: <span class='gd-jp'>家に帰るとき、パンを買いました。</span>（Di perjalanan pulang, aku membeli roti）<br><b>まえに</b> ＝ hanya menyatakan “sebelum itu”, selisihnya boleh sejauh apa pun: <span class='gd-jp'>家に帰るまえに、パンを買いました。</span>（Sebelum pulang, aku membeli roti dulu）<br><b>たとき</b> ＝ titik waktu ketika tindakan sudah selesai: <span class='gd-jp'>家に帰ったとき、母はいませんでした。</span>（Waktu aku sampai di rumah, ibu tidak ada）<br><b>たあとで</b> ＝ setelah selesai, lalu melakukan hal berikutnya: <span class='gd-jp'>家に帰ったあとで、宿題をしました。</span>（Setelah pulang, aku mengerjakan PR）</div><div class='gd-warn'>Trik menilai: kalau mau bilang “pada saat itu”, pakai とき; kalau mau menyatakan urutan sebelum-sesudah, pakai まえに atau あとで.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Untuk menyatakan “saat tindakan sudah selesai” di depan 「とき」, dipakai bentuk た, jadi kamu perlu akrab dulu dengan perubahan <span class='gd-jp'>た形</span>. Nanti di N4 kamu akan belajar <span class='gd-jp'>〜たら</span>（kalau ～, setelah ～）, yang sering dibandingkan dengan 「とき」.</div>","n5-65":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang \"selembar kertas, sebatang pensil, seekor kucing\", jadi saat menghitung benda ada kata penggolong di tengah. Bahasa Jepang juga begitu. Kata semacam ini disebut <b>kata penghitung (counter)</b>, dan cara membaginya mirip: benda tipis dan pipih pakai <span class='gd-jp'>枚</span>, benda kecil dan panjang pakai <span class='gd-jp'>本</span>. Untuk bilang \"kira-kira\", tambahkan <span class='gd-jp'>くらい</span> setelah jumlahnya.</div><div class='gd-h'>Hafalkan dulu beberapa penghitung ini</div><div class='gd-sec'><span class='gd-tag'>つ</span>Bisa dipakai untuk benda apa saja. Kalau kamu bingung harus pakai penghitung yang mana, ini yang paling serbaguna, dan sering dipakai juga saat memesan makanan. Angka 1 sampai 10 harus dihafal terpisah: <span class='gd-jp'>ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお</span>. Setelah lewat 10, つ tidak dipakai lagi.</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごを3つ買いました。</span>(Aku membeli 3 apel)</div><div class='gd-sec'><span class='gd-tag'>人</span>Untuk menghitung orang. Bacaan 1 dan 2 orang istimewa: <span class='gd-jp'>ひとり、ふたり</span>. Mulai 3 orang jadi <span class='gd-jp'>さんにん</span>, dan 4 orang jadi <span class='gd-jp'>よにん</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族は4人です。</span>(Keluargaku ada 4 orang)</div><div class='gd-sec'><span class='gd-tag'>本</span>Benda panjang dan ramping: pensil, botol, payung, pisang.</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆を1本貸してください。</span>(Tolong pinjami aku sebatang pensil)</div><div class='gd-sec'><span class='gd-tag'>枚</span>Benda tipis dan pipih: kertas, perangko, kemeja, piring.</div><div class='gd-ex-line'>・<span class='gd-jp'>切手を5枚ください。</span>(Tolong beri saya 5 lembar perangko)</div><div class='gd-sec'><span class='gd-tag'>匹</span>Hewan kecil seperti kucing, anjing, dan ikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちに猫が2匹います。</span>(Di rumahku ada 2 ekor kucing)</div><div class='gd-sec'>Yang juga sering muncul: buku pakai <span class='gd-jp'>冊</span>, mesin seperti mobil dan TV pakai <span class='gd-jp'>台</span>, dan minuman per gelas pakai <span class='gd-jp'>杯</span>.</div><div class='gd-h'>Cara memasukkannya ke kalimat</div><div class='gd-sec'>Urutan yang paling natural: <b>benda + を (atau が) + jumlah + kata kerja</b>. Jumlah langsung diletakkan sebelum kata kerja, dan setelahnya tidak perlu partikel lagi.<br>Dalam bahasa Indonesia kita bilang \"beli tiga apel\", sedangkan dalam bahasa Jepang <span class='gd-jp'>りんごを3つ買います</span>: sebut bendanya dulu, baru jumlahnya.<br>Untuk bertanya \"berapa\", ganti angkanya dengan <span class='gd-jp'>何</span>: <span class='gd-jp'>何人</span>(なんにん)、<span class='gd-jp'>何本</span>(なんぼん)、<span class='gd-jp'>何枚</span>(なんまい). Untuk benda yang dihitung dengan つ, tanyakan dengan <span class='gd-jp'>いくつ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄弟は何人いますか。</span>(Kamu punya berapa saudara?)</div><div class='gd-h'>Cara menyebut waktu</div><div class='gd-sec'><span class='gd-jp'>時</span> artinya \"jam (pukul)\", sedangkan <span class='gd-jp'>時間</span> artinya \"berapa jam (durasi)\": <span class='gd-jp'>2時</span> berarti pukul dua, <span class='gd-jp'>2時間</span> berarti dua jam.<br>Bacaan <span class='gd-jp'>分</span> (menit) berubah-ubah, jadi harus dihafal: <span class='gd-jp'>いっぷん、にふん、さんぷん、よんぷん、ごふん、ろっぷん、ななふん、はっぷん、きゅうふん、じゅっぷん</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日7時間寝ます。</span>(Aku tidur 7 jam setiap hari)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩いて10分くらいです。</span>(Jalan kaki ke stasiun kira-kira 10 menit)</div><div class='gd-ex-line'>・<span class='gd-jp'>1時間くらいかかります。</span>(Butuh waktu kira-kira 1 jam)</div><div class='gd-sec'><span class='gd-jp'>くらい</span> dan <span class='gd-jp'>ぐらい</span> artinya sama, pakai yang mana saja boleh.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>Posisi \"kira-kira\" kebalikan dari bahasa Indonesia</b>: kita bilang \"kira-kira satu jam\" dengan \"kira-kira\" di depan, tapi dalam bahasa Jepang <span class='gd-jp'>1時間くらい</span>, くらい ada di <b>belakang</b>.<br>・Jangan tambahkan を lagi setelah jumlah: yang benar <span class='gd-jp'>りんごを3つ買いました</span>, bukan 「りんごを3つを買いました」.<br>・Bacaan <span class='gd-jp'>本</span> dan <span class='gd-jp'>匹</span> berubah: <span class='gd-jp'>1本</span>いっぽん、<span class='gd-jp'>3本</span>さんぼん、<span class='gd-jp'>6本</span>ろっぽん; <span class='gd-jp'>1匹</span>いっぴき、<span class='gd-jp'>3匹</span>さんびき.<br>・1 dan 2 orang dibaca ひとり、ふたり, bukan 「いちにん」「ににん」.<br>・Pukul 4 adalah <span class='gd-jp'>4時</span>(よじ), pukul 9 adalah <span class='gd-jp'>9時</span>(くじ), jangan dibaca よんじ atau きゅうじ.<br>・Untuk menghitung orang selalu pakai <span class='gd-jp'>人</span>, tidak boleh pakai つ.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Dalam bahasa Indonesia keduanya bisa disebut \"sekitar\" atau \"kira-kira\", tapi dalam bahasa Jepang tergantung apa yang ada di depannya:<br><b>くらい</b> dipakai setelah <b>durasi atau jumlah</b>: <span class='gd-jp'>3時間くらい待ちました。</span>(Aku menunggu sekitar 3 jam)<br><b>ごろ</b> dipakai setelah <b>titik waktu</b> seperti jam atau tanggal: <span class='gd-jp'>3時ごろ着きます。</span>(Aku tiba sekitar pukul 3)<br>Dalam percakapan kamu juga bisa mendengar 「3時くらい」, tetapi kebalikannya, 「3時間ごろ」, itu salah.</div><div class='gd-warn'>Tips cepat: untuk \"kira-kira berapa lama/berapa banyak\" pakai くらい, untuk \"sekitar jam berapa\" pakai ごろ.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Tambahkan <span class='gd-jp'>だけ</span> setelah jumlah = hanya sebanyak itu: <span class='gd-jp'>1つだけください。</span>(Satu saja, tolong)</div>","n5-66":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Adverbia adalah kata kecil yang diletakkan sebelum kata kerja atau kata sifat untuk menambahkan keterangan <b>\"seberapa ~\"</b>, <b>\"berapa banyak\"</b>, atau <b>\"seberapa sering ~\"</b>. \"Sangat\" dalam \"sangat enak\", \"sering\" dalam \"sering pergi\", dan \"kurang\" dalam \"kurang suka\" semuanya adalah adverbia dalam bahasa Jepang. Kartu ini membahas tiga kelompok: <b>tingkat</b>, <b>jumlah</b>, dan <b>frekuensi</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tingkat: sangat</span><span class='gd-jp'>とても</span> = sangat, amat; diletakkan sebelum kata sifat.</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(Sangat menyenangkan)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはとてもおいしいです。</span>(Ramen ini enak sekali)</div><div class='gd-sec'><span class='gd-tag'>Jumlah: banyak</span><span class='gd-jp'>たくさん</span> = banyak, untuk menyatakan \"jumlah\". Diletakkan sebelum kata kerja, atau pakai pola 「たくさんの＋kata benda」.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はたくさん食べました。</span>(Kemarin aku makan banyak)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅にたくさんの人がいます。</span>(Di stasiun ada banyak orang)</div><div class='gd-sec'><span class='gd-tag'>Frekuensi: seberapa sering</span>Dari yang paling sering sampai sama sekali tidak, urutannya seperti satu garis:<br><b>いつも＞よく＞ときどき＞たまに＞あまり～ない＞全然～ない</b></div><div class='gd-ex-line'>・<span class='gd-jp'>いつも7時に起きます。</span>(Aku selalu bangun jam 7)</div><div class='gd-ex-line'>・<span class='gd-jp'>よくこの店に来ます。</span>(Aku sering datang ke toko ini)</div><div class='gd-ex-line'>・<span class='gd-jp'>ときどき料理をします。</span>(Aku kadang-kadang masak)</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに映画を見ます。</span>(Aku jarang-jarang nonton film)</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビはあまり見ません。</span>(Aku tidak terlalu sering nonton TV)</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は全然飲みません。</span>(Aku sama sekali tidak minum alkohol)</div><div class='gd-sec'><span class='gd-tag'>Arti lain dari よく</span>Selain \"sering\", <span class='gd-jp'>よく</span> juga bisa berarti \"dengan baik, sepenuhnya\". Kamu bisa tahu artinya dari kata kerja setelahnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(Kemarin aku tidur nyenyak)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、よく分かりません。</span>(Maaf, aku kurang begitu paham)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>あまり</span> dan <span class='gd-jp'>全然</span> harus diikuti bentuk <b>negatif</b>: 「<span class='gd-jp'>あまり好きです</span>」 itu salah, yang benar <span class='gd-jp'>あまり好きじゃないです</span> (tidak terlalu suka).<br>・Untuk \"tidak terlalu enak\", jangan diterjemahkan langsung menjadi とても + negatif. Pakailah <span class='gd-jp'>あまりおいしくないです</span>.<br>・Jangan tertukar: \"sangat\" untuk tingkat dan \"banyak\" untuk jumlah itu dua kata yang berbeda. \"Sangat enak\" pakai とても, \"banyak orang\" pakai たくさん. 「とても人がいます」 itu salah, yang benar <span class='gd-jp'>人がたくさんいます</span>.<br>・Kamu mungkin mendengar anak muda Jepang bilang 「<span class='gd-jp'>全然大丈夫</span>」 (sama sekali tidak masalah); itu bahasa lisan. Untuk buku pelajaran dan ujian, ingat dulu pola 「全然＋negatif」.<br>・Adverbia biasanya diletakkan sebelum kata kerja atau kata sifat yang diterangkannya: <span class='gd-jp'>よく行きます</span>. Jangan taruh よく di akhir kalimat.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>あまり～ない</b> = tidak terlalu ~, tapi masih ada sedikit: <span class='gd-jp'>お酒はあまり飲みません。</span>(Aku tidak terlalu sering minum alkohol, sesekali masih minum sedikit)<br><b>全然～ない</b> = sama sekali tidak ~, nol: <span class='gd-jp'>お酒は全然飲みません。</span>(Aku sama sekali tidak minum alkohol)<br>Kalau ditanya <span class='gd-jp'>よく行きますか。</span>(Sering pergi?), jawab <span class='gd-jp'>いいえ、あまり行きません。</span> kalau kadang-kadang pergi, dan <span class='gd-jp'>いいえ、全然行きません。</span> kalau tidak pernah pergi.</div><div class='gd-warn'>Tips cepat: untuk \"tidak terlalu\" pakai あまり, untuk \"sama sekali tidak\" pakai 全然, dan keduanya harus diikuti bentuk negatif.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kata sifat juga bisa menjadi adverbia, misalnya <span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早く</span></span>: <span class='gd-jp'>早く起きます。</span>(bangun pagi). Lanjutkan ke pelajaran \"penggunaan kata sifat sebagai adverbia\".</div>","n5-67":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>Kartu ini berisi tiga jenis kata kecil yang bikin bahasa Jepangmu terdengar lebih <b>seperti orang yang benar-benar bicara</b>:<br><b>Kata sambung (接続詞)</b> = seperti “lalu, dan juga, tapi, jadi” dalam bahasa Indonesia. Kata ini ditaruh di awal kalimat kedua untuk menyambung dua kalimat.<br><b>Kata seru/respons (感応詞)</b> = suara untuk menjawab atau membuka pembicaraan, misalnya “ya, bukan, anu…, hmm…”.<br><b>Onomatope (擬聲擬態語)</b> = kata yang meniru bunyi atau keadaan, seperti “guk-guk, bersin-bersin, senyum-senyum”. Bahasa Jepang memakainya jauh lebih banyak daripada bahasa Indonesia.</div><div class='gd-h'>Kata sambung: menyambung dua kalimat</div><div class='gd-sec'>Cara pakainya mudah: selesaikan kalimat pertama, taruh kata sambung di awal kalimat kedua, lalu biasanya diikuti koma 「、」.</div><div class='gd-sec'><span class='gd-tag'>そして</span>Dan juga, lalu. Menambahkan hal yang searah.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いです。そして、おいしいです。</span>(Toko ini murah, dan juga enak)</div><div class='gd-sec'><span class='gd-tag'>それから</span>Lalu, dan lagi. Untuk hal yang dilakukan berikutnya, atau menambahkan “dan juga ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンを買いました。それから、牛乳も買いました。</span>(Aku beli roti, lalu beli susu juga)</div><div class='gd-sec'><span class='gd-tag'>でも</span>Tapi. Isinya berlawanan dengan kalimat sebelumnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいです。でも、おもしろいです。</span>(Bahasa Jepang itu sulit, tapi seru)</div><div class='gd-sec'><span class='gd-tag'>だから</span>Jadi, makanya. Sebelumnya sebab, sesudahnya akibat.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>(Hujan turun, makanya tidak pergi)</div><div class='gd-h'>Kata seru/respons: menjawab dan membuka pembicaraan</div><div class='gd-sec'><span class='gd-tag'>はい・いいえ</span>Ya / bukan (tidak).</div><div class='gd-ex-line'>・<span class='gd-jp'>「学生ですか。」「はい、そうです。」</span>(“Kamu mahasiswa?” “Ya, benar.”)</div><div class='gd-sec'><span class='gd-tag'>あのう</span>Dipakai saat memanggil orang atau mau bertanya, dengan nuansa “maaf mengganggu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あのう、すみません。駅はどこですか。</span>(Anu… permisi, stasiun di mana ya?)</div><div class='gd-sec'><span class='gd-tag'>ええと</span>Dipakai sambil berpikir, seperti “hmm…” atau “anu…” dalam bahasa Indonesia.</div><div class='gd-ex-line'>・<span class='gd-jp'>ええと、三つください。</span>(Hmm… minta tiga ya)</div><div class='gd-h'>Onomatope: meniru bunyi dan keadaan</div><div class='gd-sec'><b>Giseigo (擬聲語)</b> meniru suara yang sungguh terdengar, sedangkan <b>gitaigo (擬態語)</b> menggambarkan keadaan atau perasaan lewat bunyi. Biasanya berupa dua suku kata yang diulang.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨がザーザー降っています。</span>(Hujan turun deras, srrr: giseigo)</div><div class='gd-ex-line'>・<span class='gd-jp'>犬がワンワン鳴いています。</span>(Anjing menggonggong guk-guk: giseigo)</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がぺこぺこです。</span>(Perutku lapar sekali: gitaigo)</div><div class='gd-sec'>Ada juga <span class='gd-jp'>ゆっくり</span> (pelan-pelan) dan <span class='gd-jp'>はっきり</span> (dengan jelas). Keduanya adverbia yang menggambarkan cara melakukan sesuatu, bukan meniru bunyi, tapi sama-sama sangat sering dipakai:</div><div class='gd-ex-line'>・<span class='gd-jp'>ゆっくり話してください。</span>(Tolong bicara pelan-pelan)</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Kata sambung harus ditaruh di <b>awal kalimat kedua</b>, tidak boleh diselipkan di tengah kalimat: <span class='gd-jp'>高いです。でも、買います。</span> boleh, tapi tidak boleh bilang 「高いでも買います」.<br>・Kalau <span class='gd-jp'>だから</span> langsung diikuti 「言ったでしょう」, seperti 「だから、言ったでしょう」, nuansanya jengkel, seperti “tuh kan, sudah kubilang”. Jangan dipakai ke orang yang lebih tua.<br>・Untuk arti “jadi/makanya” biasa, ke orang yang lebih tua atau di situasi formal, ganti <span class='gd-jp'>だから</span> dengan <span class='gd-jp'>ですから</span> yang lebih sopan.<br>・Kata seru <span class='gd-jp'>あのう</span> (bisa juga ditulis <span class='gd-jp'>あの</span>, <span class='gd-jp'>あのー</span>) asalnya sama dengan kata tunjuk <span class='gd-jp'>あの</span> (itu + kata benda), tapi pemakaiannya beda. Untuk memanggil orang, 「あの、すみません」 atau yang agak dipanjangkan 「あのう…」 sama-sama boleh. Versi panjang terdengar lebih ragu dan sungkan.<br>・<span class='gd-jp'>はい</span> bukan cuma “ya”. Saat namamu dipanggil, menjawab <span class='gd-jp'>はい</span> artinya “hadir / saya”.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk situasi yang sama, “Mahal, tapi aku beli”, ada dua cara bilang:<br><span class='gd-jp'>高いです。でも、買います。</span> (dua kalimat, kalimat kedua dibuka dengan <b>でも</b>)<br><span class='gd-jp'>高いですが、買います。</span>／<span class='gd-jp'>高いけど、買う。</span> (satu kalimat, <b>が・けど</b> menempel di ujung klausa pertama)<br><br>“Hujan, jadi tidak pergi” juga begitu:<br><span class='gd-jp'>雨が降りました。だから、行きませんでした。</span> (dua kalimat, pakai <b>だから</b>)<br><span class='gd-jp'>雨が降ったから、行きませんでした。</span> (satu kalimat, <b>から</b> menempel setelah sebabnya)</div><div class='gd-warn'>Trik membedakan: <b>でも・だから</b> berdiri di awal kalimat baru; <b>が・けど・から</b> menempel di ujung kalimat sebelumnya. Lihat saja ada titik di depannya atau tidak, kamu langsung tahu mana yang dipakai.</div>","n5-68":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「AというB」artinya <b>“B yang bernama A”</b>. Misalnya kamu cerita ke teman, “Di dekat rumahku ada kedai yang bernama ‘Warung Bu Sri’”. Nah, di bahasa Jepang kamu pakai「という」untuk menyambung nama kedai dengan kata 「店」. Pakai pola ini kalau lawan bicara <b>mungkin belum tahu</b> nama itu, sebagai perkenalan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nama (kata benda A) ＋ という ＋ jenis benda apa itu (kata benda B)<br><span class='gd-pair'><span class='gd-jp'>村田</span> ＋ <span class='gd-jp'>人</span> → <span class='gd-jp'>村田という人</span></span> (seseorang yang bernama Murata)<br><span class='gd-pair'><span class='gd-jp'>さくら</span> ＋ <span class='gd-jp'>店</span> → <span class='gd-jp'>さくらという店</span></span> (toko yang bernama Sakura)<br>B di belakang biasanya kata seperti 「人、店、町、食べ物、ドラマ、本」, yaitu kata yang memberi tahu “ini jenis benda apa”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memperkenalkan nama</span>Dipakai saat menyebut orang, toko, karya, atau makanan yang mungkin belum pernah didengar lawan bicara.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前に「さくら」という喫茶店があります。</span>(Di depan stasiun ada kafe yang bernama 「さくら」)</div><div class='gd-ex-line'>・<span class='gd-jp'>山田という人から電話がありました。</span>(Ada telepon dari seseorang bernama Yamada)</div><div class='gd-ex-line'>・<span class='gd-jp'>小籠包という食べ物を知っていますか。</span>(Kamu tahu makanan yang namanya xiaolongbao?)</div><div class='gd-sec'><span class='gd-tag'>Menanyakan nama</span>Kalau tidak tahu namanya, tanya dengan <span class='gd-jp'>何という</span>. Di sini 「何」dibaca <b>なん</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何という花ですか。</span>(Bunga ini namanya apa?)</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Setelah という <b>harus ada kata benda</b>. Tidak boleh bilang 「さくらというです」, harus lengkap: <span class='gd-jp'>さくらという店です</span>.<br>・Jangan dipakai untuk hal yang semua orang sudah tahu. Kalau kamu bilang 「富士山という山」ke orang Jepang, kedengarannya seperti “ada gunung bernama Fuji, kamu pasti belum tahu ya”, jadi aneh.<br>・「いう」dalam praktik sering diucapkan <b>ゆう</b>, tapi tulisannya tetap 「いう」, jangan ditulis 「とゆう」.<br>・「いう」di sini biasanya ditulis dengan hiragana, jarang dengan kanji 「言う」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>という</b> = yang bernama ~: <span class='gd-jp'>村田という人</span> (orang yang bernama Murata)<br><b>の</b> = milik ~ / dari pihak ~: <span class='gd-jp'>村田さんの友達</span> (teman Pak Murata)<br>Dalam bahasa Indonesia, “orang Murata” bisa saja dipahami sebagai “orang yang bernama Murata”, jadi mudah tergoda menulis 「村田の人」. Padahal 「村田の人」artinya “orang dari keluarga/pihak Murata”, bukan “orang bernama Murata”.</div><div class='gd-sec'>Selain itu, <span class='gd-jp'>林といいます。</span> (Saya bernama Hayashi) yang sering terdengar saat perkenalan diri menaruh “bernama” di <b>akhir kalimat</b> dan tidak diikuti kata benda.<br><span class='gd-jp'>林といいます。</span> (Nama saya Hayashi)<br><span class='gd-jp'>林という人がいます。</span> (Ada seseorang bernama Hayashi)<br>Saat menyebut nama sendiri, <b>jangan tambahkan さん</b>: 「林さんといいます」itu salah.</div><div class='gd-warn'>Trik membedakan: kalau dalam bahasa Indonesia artinya “yang <b>bernama</b> ~”, pakai という. Kalau cuma “milik siapa, dari mana”, pakai の.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Menanyakan “ini bahasa Jepangnya apa”: <span class='gd-jp'>これは日本語で何といいますか。</span> (Ini dalam bahasa Jepang disebut apa?)</div>","n5-10":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜なります」artinya <b>「menjadi ～」「jadi ～」</b>. Cuaca dari panas jadi dingin, kamar dari berantakan jadi bersih, anak kecil tumbuh jadi dewasa. Pokoknya kalau ada <b>perubahan dari satu keadaan ke keadaan lain</b>, bahasa Jepang pakai なります.</div><div class='gd-h'>Cara menyambungnya: lihat dulu jenis kata di depannya</div><div class='gd-sec'><b>Kata sifat-い</b>: ganti 「い」 di akhir dengan 「く」, lalu tambahkan なります.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い diganti く → <span class='gd-jp'>寒くなります</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくなります</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くなります</span></span></div><div class='gd-sec'><b>Kata sifat-な</b>: tambahkan 「に」 di belakangnya, lalu なります.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいになります</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気になります</span></span><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きになります</span></span></div><div class='gd-sec'><b>Kata benda</b>: sama seperti kata sifat-な, tambahkan 「に」.<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春になります</span></span><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者になります</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寒くなりましたね。</span>(Sudah jadi dingin ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋がきれいになりました。</span>(Kamarnya jadi bersih)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本が好きになりました。</span>(Aku jadi suka Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>来月、二十歳になります。</span>(Bulan depan aku berumur dua puluh tahun)</div><div class='gd-h'>Memilih なります atau なりました</div><div class='gd-sec'>Kalau kamu mau bilang「sudah jadi dingin」, yaitu perubahan yang sudah terjadi dan sekarang keadaannya memang begitu, pakai <b>なりました</b>.<br><b>なります</b> artinya「akan menjadi ～」「sebentar lagi ～」. Dipakai untuk hal yang belum terjadi, atau hal yang selalu terjadi begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>もうすぐ夏になります。</span>(Sebentar lagi musim panas)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んで、よくなりました。</span>(Setelah minum obat, jadi lebih baik)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>いい</span> itu pengecualian: bilangnya <span class='gd-jp'>よくなります</span>, bukan いくなります. Sembuh dari sakit atau cuaca yang membaik, semuanya pakai <span class='gd-jp'>よくなりました</span>.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>きらい</span>, <span class='gd-jp'>有名</span> bunyinya berakhiran 「い」, tapi semuanya kata sifat-な: yang benar <span class='gd-jp'>きれいになります</span>, bukan きれくなります.<br>・「に」 untuk kata benda dan kata sifat-な tidak boleh ketinggalan: <span class='gd-jp'>先生になりました</span>, bukan 先生なりました.<br>・Dalam bahasa Indonesia kita bilang「cuacanya jadi dingin」, tapi banyak orang langsung bilang <span class='gd-jp'>寒いです</span> di bahasa Jepang. Itu cuma berarti「sekarang dingin」, tidak ada kesan「berubah」. Kalau mau menekankan bahwa cuaca jadi dingin, bilang <span class='gd-jp'>寒くなりました</span>.<br>・Untuk「siapa/apa yang berubah」, di depannya dipakai <span class='gd-jp'>が</span> (atau <span class='gd-jp'>は</span>), bukan を: <span class='gd-jp'>部屋がきれいになりました</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>「〜くします・〜にします」di pelajaran berikutnya bedanya cuma satu huruf, tapi artinya lain. Contohnya sama-sama kamar jadi bersih:<br><b>なります</b> = menyatakan <b>sesuatu menjadi</b> begini, fokusnya pada hasil: <span class='gd-jp'>部屋がきれいになりました。</span>(Kamarnya jadi bersih)<br><b>します</b> = menyatakan <b>seseorang membuat sesuatu menjadi</b> begini, fokusnya pada siapa yang bertindak: <span class='gd-jp'>部屋をきれいにしました。</span>(Aku membersihkan kamar sampai rapi)<br>Satu pasangan lagi: <span class='gd-jp'>音が大きくなりました。</span>(Suaranya jadi besar) / <span class='gd-jp'>音を小さくしてください。</span>(Tolong kecilkan suaranya)</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia artinya「menjadi ～」, pakai <b>が＋なります</b>; kalau artinya「membuat ～ jadi ～」, pakai <b>を＋します</b>.</div><div class='gd-h'>Yang bisa kamu pelajari setelah ini</div><div class='gd-sec'>Kata kerja tidak bisa langsung disambung dengan なります. Kalau mau bilang「sekarang jadi bisa ～」, pakai 「〜ようになります」dari N4: <span class='gd-jp'>日本語が話せるようになりました。</span>(Aku sekarang sudah bisa bicara bahasa Jepang)</div>","n5-11":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜くします／〜にします」artinya <b>「membuat ～ jadi ～」</b>. Misalnya \"mengecilkan volume\" atau \"membuat kamar jadi rapi\". Intinya, <b>ada orang yang bertindak</b> untuk mengubahnya, bukan sesuatu yang berubah sendiri.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata sifat-い</b>: buang 「い」 di akhir, ganti dengan 「く」, lalu tambahkan します.<br><span class='gd-pair'><span class='gd-jp'>短い</span> → い diganti く → <span class='gd-jp'>短くします</span></span><br><span class='gd-pair'><span class='gd-jp'>小さい</span> → <span class='gd-jp'>小さくします</span></span><span class='gd-pair'><span class='gd-jp'>暖かい</span> → <span class='gd-jp'>暖かくします</span></span></div><div class='gd-sec'><b>Kata sifat-な</b>: langsung tambahkan 「にします」.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいにします</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かにします</span></span></div><div class='gd-sec'><b>Kata benda</b>: sama, langsung tambahkan 「にします」.<br><span class='gd-pair'><span class='gd-jp'>子どもの部屋</span> → <span class='gd-jp'>子どもの部屋にします</span></span></div><div class='gd-sec'>Setelah benda yang diubah, pakai <b>を</b>. Ini cocok dengan pola \"membuat/menjadikan ～\" dalam bahasa Indonesia:</div><div class='gd-ex-line'>・<span class='gd-jp'>音を小さくしてください。</span>(Tolong kecilkan suaranya)</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上をきれいにします。</span>(Merapikan bagian atas meja)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋を子どもの部屋にします。</span>(Kamar ini akan dijadikan kamar anak)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Meminta orang lain mengubah</span>Sambungkan dengan 「てください」 untuk meminta lawan bicara membuat sesuatu menjadi begini atau begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かにしてください。</span>(Tolong tenang)</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し安くしてください。</span>(Tolong kurangi sedikit lagi harganya)</div><div class='gd-sec'><span class='gd-tag'>Memesan・memilih</span>Kata benda + にします juga sering dipakai untuk bilang \"aku pilih ～\" atau \"aku putuskan ～\". Ini sering sekali terdengar saat memesan di restoran.</div><div class='gd-ex-line'>・<span class='gd-jp'>私はコーヒーにします。</span>(Aku pesan kopi)</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行は京都にしました。</span>(Untuk liburan, aku memutuskan pergi ke Kyoto)</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・「い」pada kata sifat-い harus dibuang dulu: yang benar <span class='gd-jp'>短くします</span>, bukan 「短いくします」 dan bukan 「短いにします」.<br>・<span class='gd-jp'>きれい</span> memang berakhiran い, tapi ia kata sifat-な: yang benar <span class='gd-jp'>きれいにします</span>, bukan 「きれくします」.<br>・<span class='gd-jp'>いい</span> berubah menjadi <span class='gd-jp'>よく</span>: <span class='gd-jp'>この町をよくしたいです。</span>(Aku ingin membuat kota ini jadi lebih baik), bukan 「いくします」.<br>・Untuk benda yang diubah, pakai <b>を</b>, jangan ditulis が.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>くなります／になります</b> = sesuatu <b>berubah sendiri</b> menjadi begitu, pakai <b>が</b>:<br><span class='gd-jp'>部屋が暖かくなりました。</span>(Kamarnya jadi hangat: mungkin karena matahari sudah keluar)<br><b>くします／にします</b> = <b>ada orang yang bertindak</b> membuatnya begitu, pakai <b>を</b>:<br><span class='gd-jp'>部屋を暖かくしました。</span>(Aku menghangatkan kamarnya: misalnya dengan menyalakan penghangat)</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia kamu bisa bilang \"membuat ～ jadi ～\", pakai <b>を＋します</b>. Kalau hanya bisa bilang \"～ menjadi ～\", pakai <b>が＋なります</b>.</div><div class='gd-h'>Yang bisa dipelajari selanjutnya</div><div class='gd-sec'>Kata benda + にします bisa berarti \"memutuskan memilih ～\". Kalau yang diputuskan adalah melakukan sesuatu, nanti kamu akan belajar kata kerja + ことにします: <span class='gd-jp'>日本へ行くことにしました。</span>(Aku memutuskan pergi ke Jepang)</div>"});
